INSERT INTO `sanity_post` (`id`, `data`) VALUES ('drafts.article-26', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"drafts.article-26","_rev":"b88ab125-47c2-4506-9638-34feae4fc4cf","_system":{"base":{"id":"article-26","rev":"8VyNrOEo8uWkcWBKVY22oB"}},"_type":"post","_updatedAt":"2026-07-21T13:43:44Z","body":[{"_key":"3563e33469b6","_type":"block","children":[{"_key":"3563e33469b60","_type":"span","marks":[],"text":"It is a type of mutual fund scheme primarily investing in equity and equity-related instruments, and it offers tax benefits under Section 80C of the Income Tax Act, 1961."}],"markDefs":[],"style":"normal"},{"_key":"c609765e92b7","_type":"block","children":[{"_key":"c609765e92b70","_type":"span","marks":[],"text":"Features"}],"markDefs":[],"style":"h2"},{"_key":"bd429298e53f","_type":"block","children":[{"_key":"bd429298e53f0","_type":"span","marks":[],"text":"A minimum of 80% of the total investible corpus is invested in equity and equity-related instruments"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"792e1f93229c","_type":"block","children":[{"_key":"792e1f93229c0","_type":"span","marks":[],"text":"The fund invested in equity in a diversified manner – across different market capitalization, themes and sectors."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f2103c60cefa","_type":"block","children":[{"_key":"f2103c60cefa0","_type":"span","marks":[],"text":"There is no maximum tenure of investment. However, there is a lock-in period of 3 years."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a64adf6d57e0","_type":"block","children":[{"_key":"a64adf6d57e00","_type":"span","marks":[],"text":"Tax exemption on the invested amount available under section 80C upto ₹ 1.5 lakh."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a68d26caeb00","_type":"block","children":[{"_key":"a68d26caeb000","_type":"span","marks":[],"text":"Income is treated as Long Term Capital Gain and taxed as per the prevalent tax rules. These gains are tax-free up to ₹ 1 lakh per year, and any earnings beyond this amount are subject to a 10% long-term capital gains tax."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"66652a2147f4","_type":"block","children":[{"_key":"66652a2147f40","_type":"span","marks":[],"text":"It allows the investor to start investing as low as ₹ 500."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5cfc8d907df5","_type":"block","children":[{"_key":"5cfc8d907df50","_type":"span","marks":[],"text":"It allows the investor to invest in lumpsum amount or in the form of SIPs."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"706dde358824","_type":"block","children":[{"_key":"706dde3588240","_type":"span","marks":[],"text":"Return and Risk"}],"markDefs":[],"style":"h2"},{"_key":"ce0bc3bf6570","_type":"block","children":[{"_key":"ce0bc3bf65700","_type":"span","marks":[],"text":"ELSS funds carry higher risk compared to traditional tax-saving options like PPF and NSC due to their equity exposure. However, they also offer the potential for higher returns over the long-term, aligning with the higher risk-reward profile of equities."}],"markDefs":[],"style":"normal"},{"_key":"54bca5f5e6b8","_type":"block","children":[{"_key":"54bca5f5e6b80","_type":"span","marks":[],"text":"The strategy of diversification across companies and sectors helps in mitigating the risk to some extent. However, the inherent risk present in equities as an investment class continues."}],"markDefs":[],"style":"normal"},{"_key":"d0fd50ba4c51","_type":"block","children":[{"_key":"d0fd50ba4c510","_type":"span","marks":[],"text":"ELSS vs NPS"}],"markDefs":[],"style":"h2"},{"_key":"172d0d4d4594","_type":"table","rows":[{"_key":"1z5g4q6","_type":"tableRow","cells":["","ELSS","NPS"]},{"_key":"rqlxtu0","_type":"tableRow","cells":["Nature of investment","A type of mutual fund that primarily invests in equity and equity-related instruments. It offers the potential for high returns but also carries higher market risk due to equity exposure.","A government-sponsored pension scheme that offers a mix of equity, corporate bonds, government securities, and alternative assets. It is designed for retirement planning and offers a diversified portfolio with varying risk profiles based on the investment option"]},{"_key":"k86l9c9","_type":"tableRow","cells":["Tax implications","Investments qualify for tax deductions under Section 80C of the Income Tax Act, up to a maximum of ₹1.5 lakh in a financial year. Additionally, long-term capital gains (LTCG) up to ₹1 lakh from ELSS are tax-exempt.","Contributions to NPS Tier I account qualify for tax deductions under Section 80CCD(1) within the overall limit of ₹1.5 lakh under Section 80C. An additional deduction of up to ₹50,000 is available under Section 80CCD(1B). Withdrawals from the mandatory NPS Tier 1 are not taxed."]},{"_key":"nyj7ys1","_type":"tableRow","cells":["Lock-in period","ELSS has a lock-in period of three years, which is the shortest among tax-saving investment options under Section 80C.","NPS has a longer lock-in period, with investments in the Tier I account being locked in until retirement age, although partial withdrawals are allowed under certain conditions."]},{"_key":"kqmrx0d","_type":"tableRow","cells":["Flexibility","ELSS offers flexibility in terms of investment amount and withdrawal options after the lock-in period. Investors can choose to invest through lump-sum or systematic investment plans (SIPs).","NPS offers flexibility in choosing investment options, allocation among asset classes, and fund managers. Withdrawals from the Tier I account are restricted, with conditions attached. Withdrawals can be freely made from the Tier 2 account."]}]},{"_key":"6399445bd48f","_type":"block","children":[{"_key":"6399445bd48f0","_type":"span","marks":[],"text":"Comparison of returns"}],"markDefs":[],"style":"h2"},{"_key":"a0dffa8ffe95","_type":"block","children":[{"_key":"a0dffa8ffe950","_type":"span","marks":[],"text":"ELSS"}],"markDefs":[],"style":"h3"},{"_key":"78ee5cb85d95","_type":"block","children":[{"_key":"78ee5cb85d950","_type":"span","marks":[],"text":"Trailing returns delivered by the 10 largest funds 9(by AUM) as per data tracked by "},{"_key":"78ee5cb85d951","_type":"span","marks":["3b5d667f80ae"],"text":"Moneycontrol.com"},{"_key":"78ee5cb85d952","_type":"span","marks":[],"text":":"}],"markDefs":[{"_key":"3b5d667f80ae","_type":"link","href":"https://www.moneycontrol.com/mutual-funds/"}],"style":"normal"},{"_key":"a8e83b9bede8","_type":"table","rows":[{"_key":"3xp95mo","_type":"tableRow","cells":["Scheme Name","AuM (Cr)","1Y","5Y","10Y"]},{"_key":"0k5erh4","_type":"tableRow","cells":["Axis ELSS Tax Saver Fund - Direct Plan - Growth","36,257.53","5%","18%","13%"]},{"_key":"y44ldef","_type":"tableRow","cells":["SBI ELSS Tax Saver Fund - Direct Plan - Growth","30,616.22","3%","28%","15%"]},{"_key":"syq082n","_type":"tableRow","cells":["Mirae Asset ELSS Tax Saver Fund - Direct Plan - Growth","26,537.48","6%","24%","-"]},{"_key":"vn1bjbu","_type":"tableRow","cells":["DSP ELSS Tax Saver Fund - Direct Plan - Growth","17,427.57","5%","26%","17%"]},{"_key":"yasaamz","_type":"tableRow","cells":["HDFC ELSS Tax saver - Direct Plan – Growth","16,908.00","7%","27%","14%"]},{"_key":"lqd643k","_type":"tableRow","cells":["Aditya Birla Sun Life ELSS Tax Saver Fund - Direct Plan - Growth","15,869.72","4%","16%","12%"]},{"_key":"zoo8k54","_type":"tableRow","cells":["Nippon India ELSS Tax Saver Fund - Direct Plan - Growth","15,623.15","1%","25%","11%"]},{"_key":"wdv09ub","_type":"tableRow","cells":["ICICI Prudential ELSS Tax Saver Fund - Direct Plan - Growth","14,660.64","5%","23%","14%"]},{"_key":"du0y2of","_type":"tableRow","cells":["Quant ELSS Tax Saver Fund - Direct Plan - Growth","11,922.65","-9%","33%","22%"]},{"_key":"f3hotnp","_type":"tableRow","cells":["Canara Robeco ELSS Tax Saver Fund - Direct Plan - Growth","9,102.87","4%","23%","15%"]}]},{"_key":"662bedf99c10","_type":"block","children":[{"_key":"662bedf99c100","_type":"span","marks":[],"text":"NPS"}],"markDefs":[],"style":"h3"},{"_key":"178f2746d3fb","_type":"block","children":[{"_key":"178f2746d3fb0","_type":"span","marks":[],"text":"Trailing returns (% p.a.) delivered by various Pension Fund Managers for the Tier 1 E (Equity) Scheme over a 10-year period ending on 11th July, 2025, as published by the "},{"_key":"178f2746d3fb1","_type":"span","marks":["24b8b8fe202a"],"text":"NPS Trust"},{"_key":"178f2746d3fb2","_type":"span","marks":[],"text":", are shown below:"}],"markDefs":[{"_key":"24b8b8fe202a","_type":"link","href":"https://npstrust.org.in/weekly-snapshot-nps-schemes"}],"style":"normal"},{"_key":"783fc638880e","_type":"table","rows":[{"_key":"fq1wan8","_type":"tableRow","cells":["Pension Fund","AUM(₹ Crs)","1 Year","5 Years","10 Years"]},{"_key":"5fsv8hn","_type":"tableRow","cells":["Aditya Birla Sun Life Pension Fund Management Limited","1,746.66","3.42%","20.03%","NA"]},{"_key":"2vre558","_type":"tableRow","cells":["Axis Pension Fund Management Limited","4,266.92","3.07%","NA","NA"]},{"_key":"wgflp4m","_type":"tableRow","cells":["HDFC Pension Fund Management Ltd.","60,891.46","4.47%","21.32%","13.40%"]},{"_key":"9nn6i46","_type":"tableRow","cells":["ICICI Pru. Pension Fund Mgmt Co. Ltd.","21,908.75","3.46%","22.33%","13.14%"]},{"_key":"zry3i12","_type":"tableRow","cells":["Kotak Mahindra Pension Fund Ltd.","3,209.39","5.50%","21.99%","13.33%"]},{"_key":"2js3w23","_type":"tableRow","cells":["LIC Pension Fund Ltd.","6,960.23","3.71%","21.83%","12.27%"]},{"_key":"x7q50z7","_type":"tableRow","cells":["SBI Pension Funds Pvt. Ltd","23,501.93","-0.36%","19.48%","12.01%"]},{"_key":"99cs82w","_type":"tableRow","cells":["Tata Pension Fund Management Pvt. Ltd.","2,002.39","1.77%","NA","NA"]},{"_key":"hutp77s","_type":"tableRow","cells":["UTI Pension Fund Ltd.","4,727.24","3.10%","22.36%","13.37%"]},{"_key":"1nnjft3","_type":"tableRow","cells":["DSP Pension Fund Managers Private Limited","2,087.90","12.24%","NA","NA"]}]},{"_key":"b86cbd3f6c6c","_type":"block","children":[{"_key":"b86cbd3f6c6c0","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"1ccf307012bc","_type":"block","children":[{"_key":"1ccf307012bc0","_type":"span","marks":[],"text":"The returns delivered by most NPS funds are within a narrow range. ELSS funds, on the other hand, display a greater variance in performance. Thus:"}],"markDefs":[],"style":"normal"},{"_key":"0fd041a1afea","_type":"block","children":[{"_key":"0fd041a1afea0","_type":"span","marks":[],"text":"ELSS funds have the capacity to deliver better gross returns than NPS funds."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"e6a8a7eed37e","_type":"block","children":[{"_key":"8523256aeca00","_type":"span","marks":[],"text":"NPS Tier 1 has tax benefits on withdrawals that are unlimited while gains on ELSS liquidation are tax-exempt only upto ₹ 1 lakh in a year. Thus, ELSS should be the preferred investment for smaller amounts and NPS for larger."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"bb390fa75d60","_type":"block","children":[{"_key":"3d696012ab070","_type":"span","marks":[],"text":"Where the investment is being made as a means to achieving the allocation to equity, ELSS should be prioritized over NPS."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}],"publishedAt":"2026-07-19T18:30:00.000Z","slug":{"_type":"slug","current":"2023-10-03-equity-linked-saving-scheme"},"title":"Equity Linked Saving Scheme (ELSS)"}');
