INSERT INTO `sanity_page` (`id`, `data`) VALUES ('drafts.page-about-us', '{"_createdAt":"2026-07-15T06:12:14Z","_id":"drafts.page-about-us","_rev":"c635d45a-523f-4a8f-83d2-5d5fd46f2582","_system":{"base":{"id":"page-about-us","rev":"ZD9hpBEYl1x1VYz1fFmMsP"}},"_type":"page","_updatedAt":"2026-08-06T09:30:46Z","body":[{"_key":"ff2e208f34db","_type":"block","children":[{"_key":"ff2e208f34db0","_type":"span","marks":[],"text":"About Us"}],"markDefs":[],"style":"h2"},{"_key":"ff4f69591096","_type":"block","children":[{"_key":"ff4f695910960","_type":"span","marks":[],"text":"Personal Financial Advice is a huge area of activity. It can have a significant impact on household wealth and wellbeing. It is our experience and observation that things are often not working very well."}],"markDefs":[],"style":"normal"},{"_key":"59aa3f9d2cf6","_type":"block","children":[{"_key":"59aa3f9d2cf60","_type":"span","marks":[],"text":"People find it difficult to understand and make investment decisions. They end up with too little or too much risk relative to what they would have chosen if they had the expertise to make the best decisions for themselves. They often incur costs and fees in the process, but do not know what they are paying and what results they are getting for the payments."}],"markDefs":[],"style":"normal"},{"_key":"c76fbd66a4d1","_type":"block","children":[{"_key":"c76fbd66a4d10","_type":"span","marks":[],"text":"Unfortunately, there is often a conflict of interest between the product providers and advisors and the clients. The products that generate the highest profits for the providers are not the best investments for their clients, while the best investment solutions generate very low profits for the providers."}],"markDefs":[],"style":"normal"},{"_key":"f552536e250f","_type":"block","children":[{"_key":"f552536e250f0","_type":"span","marks":[],"text":"DhanOpinion is an experiment to see if we can contribute to making the investment process and outcomes better for people. The objective is to provide simple effective guidance at low cost. We believe we can leverage our education, training and experience to provide something of value to a large number of people in an efficient way."}],"markDefs":[],"style":"normal"},{"_key":"549a1699ee8b","_type":"block","children":[{"_key":"549a1699ee8b0","_type":"span","marks":[],"text":"If you find DhanOpinion useful, please let us know. If there is something you would like us to analyze that would be useful to you and many others, let us know and we will consider doing the analysis. If you have any specific suggestions or expertise that you would like to contribute to the effort please let us know. It will help us greatly if you can fill in the brief questionnaire below."}],"markDefs":[],"style":"normal"},{"_key":"formBlockContact","_type":"formBlock","destinationEmail":"response@dhanopinion.com","fields":[{"_key":"awwk3loh","inputType":"text","label":"Name","name":"contactName","required":true},{"_key":"mqpjw8ud","inputType":"email","label":"Email","name":"contactEmail","required":true},{"_key":"p39vey6m","inputType":"tel","label":"Phone Number","name":"contactPhone","required":true},{"_key":"82ln7omu","inputType":"textarea","label":"Message","name":"message","required":true}],"formType":"custom","submitButtonText":"Send Message","subtitle":"Have a question? Send us a message or email us at response@dhanopinion.com.","title":"Contact Us"},{"_key":"formBlockFeedback","_type":"formBlock","fields":[{"_key":"rvrb2z9r","inputType":"text","label":"Name","name":"name","required":true},{"_key":"hk0ic3ly","inputType":"tel","label":"Mobile","name":"mobile","required":true},{"_key":"fotulctr","inputType":"email","label":"Email","name":"email","required":true},{"_key":"4fhzjzh3","inputType":"radio","label":"Is DhanOpinion useful?","name":"isUseful","options":["Yes","No"],"required":true},{"_key":"6d6d9mfn","inputType":"radio","label":"Do you know how much you are paying for your investments?","name":"knowFees","options":["Yes","No"],"required":true},{"_key":"dlcmynom","inputType":"radio","label":"Do you know what percentage of your investments are in equity?","name":"knowStocksPct","options":["Yes","No"],"required":true},{"_key":"coq8mrci","inputType":"radio","label":"Would you be willing to pay anything to cover costs?","name":"willingToPay","options":["Yes","No"],"required":true},{"_key":"ba7f2d597608","inputType":"radio","label":"Did Dhanopinion help you get to a better equity allocation?","name":"Betterallocation","options":["Yes","No"],"required":true},{"_key":"30c9e44f9131","inputType":"radio","label":"Did you open an NPS account or use it more?","name":"NPSaccount","options":["Yes","No"],"required":true},{"_key":"hqvapgh2","inputType":"textarea","label":"What else would be valuable to you?","name":"valuableThings","required":true},{"_key":"a2egerwn","inputType":"textarea","label":"Anything else you would like to share?","name":"anythingElse","required":true}],"formType":"custom","submitButtonText":"Submit Feedback","subtitle":"If you have specific suggestions or expertise you would like to contribute, please let us know.","title":"Leave Feedback"},{"_key":"62d96e4f7638","_type":"block","children":[{"_key":"229386ac044f","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"}],"slug":{"_type":"slug","current":"about-us"},"title":"About Us"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-8', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-8","_rev":"s2wDSUpWBbCAmLaTqSHdlt","_system":{"base":{"id":"article-8","rev":"gvb15rYHBFgFq42eS6o9sU"}},"_type":"post","_updatedAt":"2026-07-17T14:23:54Z","body":[{"_key":"18dd82f16255","_type":"block","children":[{"_key":"18dd82f162550","_type":"span","marks":[],"text":"The nature of equity investing"}],"markDefs":[],"style":"h2"},{"_key":"ee9205b2a10d","_type":"block","children":[{"_key":"ee9205b2a10d0","_type":"span","marks":[],"text":"Equity is designed to bear risk in bad times."}],"markDefs":[],"style":"normal"},{"_key":"c7adc4b613e3","_type":"block","children":[{"_key":"c7adc4b613e30","_type":"span","marks":[],"text":"When you invest in equity you take the risk that the business will be unsuccessful and that you will lose money. The only reason that people invest in equity is because they expect on average that the business will be successful and that they will make money in compensation for bearing this risk. Historically equity markets have delivered high returns. It is reasonable to expect that in the future too one could expect to get higher returns for bearing equity risk."}],"markDefs":[],"style":"normal"},{"_key":"6d566899be99","_type":"block","children":[{"_key":"6d566899be990","_type":"span","marks":[],"text":"Equity markets returns have been very attractive historically, particularly over long horizons. However, the trade-off is that one is exposed to significant risk of losses. When one invests in equity, one is taking risk while hoping to generate higher returns than fixed income investments and interest rate investments like government or corporate bonds or bank fixed deposits."}],"markDefs":[],"style":"normal"},{"_key":"9812acd575cd","_type":"block","children":[{"_key":"9812acd575cd0","_type":"span","marks":[],"text":"Understanding equity drawdown"}],"markDefs":[],"style":"h2"},{"_key":"9469cb2ef17c","_type":"block","children":[{"_key":"9469cb2ef17c0","_type":"span","marks":[],"text":"A drawdown, or equity drawdown, is a key measure to understand the maximum loss an investor could have made during a past period."}],"markDefs":[],"style":"normal"},{"_key":"1494ab90bf31","_type":"block","children":[{"_key":"1494ab90bf310","_type":"span","marks":[],"text":"Calculating a drawdown’s magnitude"}],"markDefs":[],"style":"h3"},{"_key":"16a73ad5a6ce","_type":"block","children":[{"_key":"16a73ad5a6ce0","_type":"span","marks":[],"text":"It is expressed as a percentage of the peak against which it is measured."}],"markDefs":[],"style":"normal"},{"_key":"fc9641b318bc","_type":"block","children":[{"_key":"fc9641b318bc0","_type":"span","marks":[],"text":"Drawdown = Peak Value – Trough Value"}],"markDefs":[],"style":"normal"},{"_key":"729227a92e60","_type":"block","children":[{"_key":"729227a92e600","_type":"span","marks":[],"text":"Drawdown % = (Peak Value – Trough Value) / Peak Value %"}],"markDefs":[],"style":"normal"},{"_key":"2a054afffeca","_type":"block","children":[{"_key":"2a054afffeca0","_type":"span","marks":[],"text":"As can be gleaned from the formula, it is a lag measure and can be calculated only in hindsight. Also, it can be calculated at any point against a prior peak. However, if the market is continuing to decline, the current calculation may not reveal the full magnitude of the drawdown."}],"markDefs":[],"style":"normal"},{"_key":"52a463822e7a","_type":"block","children":[{"_key":"52a463822e7a0","_type":"span","marks":[],"text":"As opposed to a loss, the calculation of which is triggered by a sale event, drawdown is an ongoing, intrinsic part of equity movements. In a volatile, independent marketplace, it is inherently fallacious to believe that equity values will only go up. In fact, it is believed that US equities have spent nearly 90% of their time below a prior peak."}],"markDefs":[],"style":"normal"},{"_key":"dd073e23adcc","_type":"block","children":[{"_key":"dd073e23adcc0","_type":"span","marks":[],"text":"Recovery from a drawdown"}],"markDefs":[],"style":"h3"},{"_key":"203cc3fd0154","_type":"block","children":[{"_key":"203cc3fd01540","_type":"span","marks":[],"text":"Another critical aspect of drawdowns is the nonlinear relationship between the downward slope to the trough and, thereafter, the climb back up the hill."}],"markDefs":[],"style":"normal"},{"_key":"3f53c8026ffe","_type":"block","children":[{"_key":"3f53c8026ffe0","_type":"span","marks":[],"text":"The percentage gain needed to return to the break-even point (prior peak) is always greater than the percentage of the drawdown. To illustrate:"}],"markDefs":[],"style":"normal"},{"_key":"a13be7f9b77e","_type":"block","children":[{"_key":"a13be7f9b77e0","_type":"span","marks":[],"text":"A 10% drawdown requires an 11.1% gain to recover."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"77f5e9957d0f","_type":"block","children":[{"_key":"77f5e9957d0f0","_type":"span","marks":[],"text":"A 20% drawdown requires a 25% gain to recover."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"51a2f9617359","_type":"block","children":[{"_key":"51a2f96173590","_type":"span","marks":[],"text":"A 50% drawdown requires a 100% gain to recover."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5a3e12b4bf52","_type":"block","children":[{"_key":"5a3e12b4bf520","_type":"span","marks":[],"text":"A 70% drawdown requires a 233% gain to recover."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"22dc63314f64","_type":"block","children":[{"_key":"22dc63314f640","_type":"span","marks":[],"text":"Historical performance"}],"markDefs":[],"style":"h2"},{"_key":"2821d549eddf","_type":"block","children":[{"_key":"2821d549eddf0","_type":"span","marks":[],"text":"The US markets have the longest and best statistics available and are also the largest equity markets, estimated to account for 60% of global capitalization weighted indices. They are a good place to start to get a sense of historical returns for equity. Investing is about making choices and so one should look at the returns on equity and other assets as well to make an informed choice."}],"markDefs":[],"style":"normal"},{"_key":"a6ce8e21ff90","_type":"block","children":[{"_key":"a6ce8e21ff900","_type":"span","marks":[],"text":"History can provide some context. Table 1 shows the historical performance of US stocks and bonds over a 100-year period as tracked by Northern Trust. In other words, it shows the types of losses one should be prepared to withstand when one invests in equity."}],"markDefs":[],"style":"normal"},{"_key":"7b1980c68e95","_type":"block","children":[{"_key":"7b1980c68e950","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/e707fd185de82ab12e34e588d45c1c366f1486ec-727x366.png","_key":"d91f20e991d6","_type":"image"},{"_key":"79b00486e43f","_type":"block","children":[{"_key":"79b00486e43f0","_type":"span","marks":[],"text":"Source: "},{"_key":"79b00486e43f1","_type":"span","marks":["1c30e3f89073"],"text":"Northern Trust"}],"markDefs":[{"_key":"1c30e3f89073","_type":"link","href":"https://www.northerntrust.com/content/dam/northerntrust/pws/nt/documents/commentary/wealth-management/a-history-of-drawdowns.pdf"}],"style":"normal"},{"_key":"4da4523db778","_type":"block","children":[{"_key":"4da4523db7780","_type":"span","marks":[],"text":"Extracts from the same data, differently presented, capture the maximum drawdown, the lowest point reached since the previous peak, across different drawdown events in history. The Great Depression is clearly the sharpest, will a fall in value of over 80%."}],"markDefs":[],"style":"normal"},{"_key":"f9eb80e189e8","_type":"block","children":[{"_key":"f9eb80e189e80","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/9ea5326330c6a96c51320af40be9eabaa8659021-653x258.png","_key":"29c616aca409","_type":"image"},{"_key":"a7868982092e","_type":"block","children":[{"_key":"a7868982092e0","_type":"span","marks":[],"text":"Source: "},{"_key":"a7868982092e1","_type":"span","marks":["f9f2e16499a1"],"text":"Northern Trust"}],"markDefs":[{"_key":"f9f2e16499a1","_type":"link","href":"https://www.northerntrust.com/content/dam/northerntrust/pws/nt/documents/commentary/wealth-management/a-history-of-drawdowns.pdf"}],"style":"normal"},{"_key":"2e58799bffff","_type":"block","children":[{"_key":"2e58799bffff0","_type":"span","marks":[],"text":"The Great Depression took 151 months to recover, nearly 13 years, even though the drawdown had taken only 34 months."}],"markDefs":[],"style":"normal"},{"_key":"7ba7d1f2359e","_type":"block","children":[{"_key":"7ba7d1f2359e0","_type":"span","marks":[],"text":"In an article published in December 2024, "},{"_key":"7ba7d1f2359e1","_type":"span","marks":["cb3e92d47841"],"text":"StatOasis"},{"_key":"7ba7d1f2359e2","_type":"span","marks":[],"text":" commented on drawdowns in other global markets and said, “Market volatility isn’t unique to the U.S. In the UK, the stock index faced a devastating 73% drawdown in 1972, taking nine years to recover. Even worse, the crash in 2000 required a gruelling 20 years to finally post new highs in 2024.”"}],"markDefs":[{"_key":"cb3e92d47841","_type":"link","href":"https://statoasis.com/post/sp500-drawdowns-since-1870?"}],"style":"normal"},{"_key":"7bde7a0918bb","_type":"block","children":[{"_key":"7bde7a0918bb0","_type":"span","marks":[],"text":"Japan’s Nikkei index presents another sobering example. After a massive speculative bubble burst in 1990, the index posted annualized returns of -4.78% for over 20 years. It still hasn’t recovered to its peak levels today.”"}],"markDefs":[],"style":"normal"},{"_key":"2942331d4ed6","_type":"block","children":[{"_key":"2942331d4ed60","_type":"span","marks":[],"text":"Indian equity is not immune to drawdowns either. A "},{"_key":"2942331d4ed61","_type":"span","marks":["d05236a8a21b"],"text":"LinkedIn post by Sonali Das"},{"_key":"2942331d4ed62","_type":"span","marks":[],"text":" states that between January and October 2008, the Nifty 50 witnessed a drawdown of over 60%. Though the race to the bottom took less than a year, the recovery took over 5 years."}],"markDefs":[{"_key":"d05236a8a21b","_type":"link","href":"https://www.linkedin.com/posts/sonali-das-90374649_historical-insights-nifty-50-bear-market-activity-7287748037529980928-e0Gz/?utm_source=chatgpt.com"}],"style":"normal"},{"_key":"e6ab3aa95cfc","_type":"block","children":[{"_key":"e6ab3aa95cfc0","_type":"span","marks":[],"text":"The challenge for investors"}],"markDefs":[],"style":"h2"},{"_key":"54c78bcf9715","_type":"block","children":[{"_key":"54c78bcf97150","_type":"span","marks":[],"text":"Herein lies one of the great challenges of stock investing. Though values did eventually recover, they took many years. If an investor needed to cash out during this period, he/ she would have had to invariably book losses. This is also one of the reasons why investors are advised to reduce their equity exposure as they age. At a young age one has time to recover from drawdowns. But, at an advanced age, one may not."}],"markDefs":[],"style":"normal"},{"_key":"b36bee600aab","_type":"block","children":[{"_key":"b36bee600aab0","_type":"span","marks":[],"text":"In an article published on July 17, 2025, "},{"_key":"b36bee600aab1","_type":"span","marks":["80348175d9d7"],"text":"MorningStar"},{"_key":"b36bee600aab2","_type":"span","marks":[],"text":" suggests, “Market crashes always feel scary when they happen, but there’s no way to know in the moment whether you’re encountering a minor correction or looking down the barrel of the next Great Depression. But since the path to recovery is so uncertain, the best way to be prepared is by owning a well-diversified portfolio that fits your time horizon and risk tolerance. Investors who stay invested in the market in the long run will reap rewards that make the turmoil worthwhile.”"}],"markDefs":[{"_key":"80348175d9d7","_type":"link","href":"https://www.morningstar.com/economy/what-weve-learned-150-years-stock-market-crashes"}],"style":"normal"},{"_key":"b4ccd986b765","_type":"block","children":[{"_key":"b4ccd986b7650","_type":"span","marks":[],"text":"Looking through historical data, one can get some sense of possible losses. When investing in a well-diversified portfolio of equities, one should be prepared that one has a loss of 30 to 50%. One cannot rule out the possibility of losses of 80% or even more."}],"markDefs":[],"style":"normal"},{"_key":"77b1447eb248","_type":"block","children":[{"_key":"77b1447eb2480","_type":"span","marks":[],"text":"Recommendations for prudent investors"}],"markDefs":[],"style":"h2"},{"_key":"33a1569a9c9e","_type":"block","children":[{"_key":"33a1569a9c9e0","_type":"span","marks":[],"text":"The good thing is that, historically, values have recovered over time. Even if you were looking down the barrel of the next Great Depression, history shows us that there was a light at the end of the tunnel."}],"markDefs":[],"style":"normal"},{"_key":"6ba4398feba5","_type":"block","children":[{"_key":"6ba4398feba50","_type":"span","marks":[],"text":"With the ultimate goal of building a portfolio that withstands extreme market stress and grows during favourable conditions, the prudent investor focuses on resilience and planning and avoids predicting and avoiding drawdowns."}],"markDefs":[],"style":"normal"},{"_key":"2849ee2bdb55","_type":"block","children":[{"_key":"2849ee2bdb550","_type":"span","marks":[],"text":"Know thyself – Identify one’s ability to withstand extreme conditions without capitulating. An honest evaluation itself will drive equity allocation strategies."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"cba4c2b70842","_type":"block","children":[{"_key":"cba4c2b708420","_type":"span","marks":[],"text":"Allocation – This remains the bedrock of long-term investing. Allocation can be done at multiple levels. Within equity, one could allocate judiciously between industry sector, high/mid/low cap, based on investment styles, etc."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f5a650d97411","_type":"block","children":[{"_key":"f5a650d974110","_type":"span","marks":[],"text":"Rebalancing discipline – As values go up and down, it becomes important to rebalance. Instead of impulsive rebalancing, a rules-based approach, whether based on a calendar, or thresholds of value, is recommended."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"408811ccd40c","_type":"block","children":[{"_key":"408811ccd40c0","_type":"span","marks":[],"text":"Monitor – The investor cannot make investing a one-time activity. The portfolio needs to be monitored, along with keeping an eye on the broader market with the help of information provided by analysts. Over time, an investor should develop a set of indicators and tools to be monitored on a regular basis."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f69096dcca82","_type":"block","children":[{"_key":"f69096dcca820","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"88a5d31c3475","_type":"block","children":[{"_key":"88a5d31c34750","_type":"span","marks":[],"text":"Does this mean that equities do not have much risk if one is prepared to hold for long periods of time and follow a prudent approach? The answer is no. Just because the markets came back historically, does not mean that they will recover fully from large losses in the future. Owners of equity are taking a risk and should be prepared for a permanent loss and the loss could be significant. However, given the historical experience – selling after a large loss may not be well advised. If one does take equity risk, it is worthwhile to plan to ride through large losses rather than sell when the pain is highest."}],"markDefs":[],"style":"normal"},{"_key":"d9412be856b5","_type":"block","children":[{"_key":"d9412be856b50","_type":"span","marks":[],"text":"Uncertainty lies at the heart of all future events. An investor’s focus should be on planning and discipline, and not prediction and one-offs. By doing so, an investor can hope to benefit from the long-term wealth-creation opportunities that equities have historically offered."}],"markDefs":[],"style":"normal"}],"publishedAt":"2025-03-29T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-08-risk-and-return-profile-of-equity"},"title":"Equity - Risk and Return profile"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-9', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-9","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"c83448e047c5","_type":"block","children":[{"_key":"c83448e047c50","_type":"span","marks":[],"text":"Fixed income investments refer to investments which promise upfront the returns of interest and principal. For very strong entities, like the Government, there is little risk of default on these promises to pay. Therefore, on a horizon matching the maturity of these investments, one knows exactly what one will get and there is no risk of returns different from those promised. For a short-term government obligation, there is no risk of loss in the nominal value of the investment and therefore these investments are often referred to as risk-free investments. For longer maturity fixed income investments, the value will fluctuate on a day-to-day basis as interest rates fluctuate. As interest rates go up the value of the investments will go down and as the interest rates go down, the value of the investments goes up. The longer the maturity of the investments, the more the fluctuation in value. However, unlike equity investments, while the value fluctuates on a day-to-day basis, the maturity value is fixed, and the value will converge to the maturity value."}],"markDefs":[],"style":"normal"},{"_key":"f3c2434f3f2f","_type":"block","children":[{"_key":"f3c2434f3f2f0","_type":"span","marks":[],"text":"Does this mean that fixed income is without risk?"}],"markDefs":[],"style":"normal"},{"_key":"19e56b090239","_type":"block","children":[{"_key":"19e56b0902390","_type":"span","marks":[],"text":"No. There is no risk if one is interested in nominal returns with a horizon equal to the maturity of the investment. However, over a horizon different from that of the maturity of the investment there will be fluctuations in value and therefore risk. However, this risk is much lower than for equity investments."}],"markDefs":[],"style":"normal"},{"_key":"ccfdfb252a6c","_type":"block","children":[{"_key":"ccfdfb252a6c0","_type":"span","marks":[],"text":"The second factor that creates risk for fixed income investments is that most people are concerned over long horizons with the real value of their investments. Since inflation over time is both significant and potentially volatile, investments in fixed income do not eliminate risk in real terms. While there are options to invest in real or inflation linked fixed income investments and these can eliminate inflation risk over a term equal to that of the fixed income investment, for taxable investors even these do not eliminate inflation risk completely because income taxes will be due on nominal returns and high inflation will result in negative after-tax real returns even after investing in inflation linked fixed income investments."}],"markDefs":[],"style":"normal"},{"_key":"070b5dadd03b","_type":"block","children":[{"_key":"070b5dadd03b0","_type":"span","marks":[],"text":"Often when economies are doing well, equity markets go up and interest rates go up and the prices of fixed income investments go down. Conversely when economies do badly, interest rates go down and the value of fixed income investments go up. Adding fixed income investments therefore diversifies an equity-only portfolio. Fixed income investments are also less risky than equity investments, particularly in nominal terms and generally also in inflation adjusted terms."}],"markDefs":[],"style":"normal"},{"_key":"cfd9e6c0da3e","_type":"block","children":[{"_key":"cfd9e6c0da3e0","_type":"span","marks":[],"text":"Unexpected increases in inflation generally have a negative impact on the value of both equity and fixed income investments. There can therefore be situations where fixed income investments fail to diversify an equity portfolio."}],"markDefs":[],"style":"normal"},{"_key":"eac09282fd0b","_type":"block","children":[{"_key":"eac09282fd0b0","_type":"span","marks":[],"text":"Short-term fixed income investments for someone with a short horizon have no risk in nominal terms. For those with a longer horizon, there is no risk in nominal terms to the horizon but there is risk in nominal terms to different horizons than the maturity of the instruments. The risk of fixed income is typically much lower than for equity, particularly over short and medium-term horizons. However, in cases of unexpected hyperinflation such as was experienced in Germany, Hungary and Zimbabwe and more recently in Venezuela and Argentina, over longer periods, the value of fixed income investments can be totally decimated in real terms being more exposed to risk than even equity, because equity has a better chance of compensating for hyperinflation over longer horizons through the ability to adjust prices and revenues to inflation. In India over long periods of time, inflation has substantially degraded the real value of fixed income investments."}],"markDefs":[],"style":"normal"},{"_key":"94569d4e3abf","_type":"block","children":[{"_key":"94569d4e3abf0","_type":"span","marks":[],"text":"This is the reason why we believe that there is no asset without risk in real terms."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-03-30T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-09-risk-and-return-profile-of-fixed-income"},"title":"Fixed Income – Risk and Return profile"}');
DROP TABLE IF EXISTS `sanity_stepsToSuccessPage`;
CREATE TABLE `sanity_stepsToSuccessPage` (
  `id` VARCHAR(255) NOT NULL,
  `data` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sanity_stepsToSuccessPage` (`id`, `data`) VALUES ('stepsToSuccessSingleton', '{"_createdAt":"2026-07-22T13:07:37Z","_id":"stepsToSuccessSingleton","_rev":"3f5OQyfSZVAKd0RUZ9va6K","_system":{"base":{"id":"stepsToSuccessSingleton","rev":"ZD9hpBEYl1x1VYz1fBOOsf"}},"_type":"stepsToSuccessPage","_updatedAt":"2026-07-23T19:37:09Z","introText":[{"_key":"block1","_type":"block","children":[{"_key":"span1","_type":"span","marks":[],"text":"Dear Investor,"}],"markDefs":[],"style":"normal"},{"_key":"block2","_type":"block","children":[{"_key":"span2","_type":"span","marks":[],"text":"Thank you for your interest in Dhanopinion''s investment advisory service. On this page you will find a set of steps that you can go through in order to discover the most suitable investment avenues for yourself. This service uses the new income tax regime for all decisions and illustrations."}],"markDefs":[],"style":"normal"},{"_key":"block3","_type":"block","children":[{"_key":"span3","_type":"span","marks":[],"text":"Should you wish to seek a confidential, paid consulting with one of our experts, kindly click the \\"Personalized Investment Consulting\\" button below. A personalised investment consulting service is expected to be launched in the future. At this time, you will be joining a wait-list."}],"markDefs":[],"style":"normal"},{"_key":"block4","_type":"block","children":[{"_key":"span4","_type":"span","marks":[],"text":"We hope this advisory service provides you with the key inputs you need to move forward in your investment journey. Before proceeding, please read the Disclaimer and move forward only if you agree with the terms therein."}],"markDefs":[],"style":"normal"},{"_key":"block5","_type":"block","children":[{"_key":"span5","_type":"span","marks":[],"text":"We wish you a successful investing journey!"}],"markDefs":[],"style":"normal"}],"steps":[{"_key":"step-01","content":[{"_key":"2968c42496c6","_type":"block","children":[{"_key":"2968c42496c60","_type":"span","marks":[],"text":"Before investing, it is important to evaluate your debt situation. Paying high interest on debt while expecting lower returns from investments is counterproductive."}],"markDefs":[],"style":"normal"},{"_key":"98c71756563d","_type":"block","children":[{"_key":"98c71756563d0","_type":"span","marks":["strong"],"text":"Do you currently have debt which has a cost of 10% p.a. interest or higher?"}],"markDefs":[],"style":"normal"},{"_key":"a4fb1fdbb1d2","_type":"block","children":[{"_key":"a4fb1fdbb1d20","_type":"span","marks":["strong"],"text":"If Yes,"},{"_key":"a4fb1fdbb1d21","_type":"span","marks":[],"text":" paying down debt may be better than investing as investment returns are unlikely to exceed 10% p.a. sustainably."}],"markDefs":[],"style":"normal"},{"_key":"c41ce45d4ac2","_type":"block","children":[{"_key":"c41ce45d4ac20","_type":"span","marks":["strong"],"text":"If No,"},{"_key":"c41ce45d4ac21","_type":"span","marks":[],"text":" you can move to the next step and initiate the investing journey."}],"markDefs":[],"style":"normal"},{"_key":"3a2c46fa6756","_type":"block","children":[{"_key":"3a2c46fa67560","_type":"span","marks":[],"text":"At the same time, you should bear in mind that the 10% indicative threshold is for growth-oriented investments such as equity. If your primary investment target is debt investments, then you should use 7% as the benchmark instead of 10%, to determine if you should pare down debt or invest."}],"markDefs":[],"style":"normal"},{"_key":"ef7957ad915e","_type":"block","children":[{"_key":"ef7957ad915e0","_type":"span","marks":[],"text":"Notes:"}],"markDefs":[],"style":"normal"},{"_key":"d51fac3c7316","_type":"block","children":[{"_key":"d51fac3c73160","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_key":"beb4c51cec75","_type":"block","children":[{"_key":"beb4c51cec750","_type":"span","marks":[],"text":"Please ensure that tax implications are factored in. In case of some debt servicing payments, financial benefits such as setoffs against income may be available, lowering your tax liability."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1bebebecac53","_type":"block","children":[{"_key":"1bebebecac530","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_key":"ea9d5d1ef51a","_type":"block","children":[{"_key":"ea9d5d1ef51a0","_type":"span","marks":[],"text":"The 10% and 7% numbers used are indicative and relevant to the economic environment in Q2 of 2026. If the economic environment changes, eg. inflation rises, increasing the cost of money, the indicative rates used should change as well."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}],"desc":"Before investing, it is important to evaluate your debt situation. Paying high interest on debt while expecting lower returns from investments is counterproductive.","icon":"fa-solid fa-clipboard-check","link":"step-1-debt-check","num":"01","title":"Debt Check"},{"_key":"step-02","content":[{"_key":"f1c97f9e2e54","_type":"block","children":[{"_key":"f1c97f9e2e540","_type":"span","marks":[],"text":"OK! You have cleared the first hurdle of the debt check and decided that you are ready to invest."}],"markDefs":[],"style":"normal"},{"_key":"32e68d6f2d84","_type":"block","children":[{"_key":"32e68d6f2d840","_type":"span","marks":[],"text":"Your portfolio should balance equity (stocks, mutual funds) and debt (bonds, fixed income, government schemes). But how much to invest in debt and how much in equity is a personal choice. This decision is known as the allocation decision which is what you need to make at this stage."}],"markDefs":[],"style":"normal"},{"_key":"feb05c7993c5","_type":"block","children":[{"_key":"feb05c7993c50","_type":"span","marks":[],"text":"This allocation, or division, is also referred to as the growth vs. income decision. How much money are you willing to squirrel away into growth investments that will, hopefully, deliver superior returns over an extended period of time, and how much will you invest in income-generating investments that deliver predictable, if lower, returns, on a regular basis?"}],"markDefs":[],"style":"normal"},{"_key":"17af83477056","_type":"block","children":[{"_key":"17af834770560","_type":"span","marks":[],"text":"While the exact numbers might vary, most experts agree that the two variables that should influence the decision are the investor’s age and risk tolerance:"}],"markDefs":[],"style":"normal"},{"_key":"654831310657","_type":"block","children":[{"_key":"6548313106570","_type":"span","marks":[],"text":"The lower the age of the investor, the higher the allocation to equity"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"2971267c2f5e","_type":"block","children":[{"_key":"2971267c2f5e0","_type":"span","marks":[],"text":"The lower the risk tolerance of the investor, the lower the allocation to equity."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f0e4507f267f","_type":"block","children":[{"_key":"f0e4507f267f0","_type":"span","marks":[],"text":"Allocation numbers are not cast in stone. They should anyway be adjusted periodically for changing age and risk tolerance levels. They can also be adjusted for any other factor the investor wishes to take into account."}],"markDefs":[],"style":"normal"},{"_key":"5f18fedb6d1e","_type":"block","children":[{"_key":"5f18fedb6d1e0","_type":"span","marks":[],"text":"For allocation strategies, read our article on Allocation."}],"markDefs":[],"style":"normal"}],"desc":"OK! You have cleared the first hurdle of the debt check and decided that you are ready to invest. Your portfolio should balance equity (stocks, mutual funds) and debt (bonds, fixed income, government schemes). But how much to invest in debt and how much in equity is a personal choice.","icon":"fa-solid fa-chart-pie","link":"step-2-allocation-equity-debt","num":"02","title":"Allocation between Equity and Debt"},{"_key":"step-03","content":[{"_key":"3cf77565016d","_type":"block","children":[{"_key":"3cf77565016d0","_type":"span","marks":[],"text":"An unplanned pulling out from an investment can cause severe damage to the portfolio in several ways:"}],"markDefs":[],"style":"normal"},{"_key":"a66b2e55995e","_type":"block","children":[{"_key":"a66b2e55995e0","_type":"span","marks":[],"text":"Liquidating equity investments in a downward spiral can impair the returns and limit the potential to bounce back during an upswing."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"64498accf49c","_type":"block","children":[{"_key":"64498accf49c0","_type":"span","marks":[],"text":"Liquidating debt investments can invite penalties and lower than assured returns."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"02b65719673a","_type":"block","children":[{"_key":"02b65719673a0","_type":"span","marks":[],"text":"Hence, it is recommended that a part of the investment intended for debt instruments be invested for such emergencies in suitable instruments. These typically include:"}],"markDefs":[],"style":"normal"},{"_key":"9ffb60d54421","_type":"block","children":[{"_key":"9ffb60d544210","_type":"span","marks":["strong"],"text":"Bank Fixed Deposits"},{"_key":"9ffb60d544211","_type":"span","marks":[],"text":" – Can be liquidated immediately. Many banks also offer the service of liquidating an FD automatically to cover shortfalls in a linked Savings account."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"01b7c7d9c7ee","_type":"block","children":[{"_key":"01b7c7d9c7ee0","_type":"span","marks":["strong"],"text":"Liquid or Overnight Mutual Funds"},{"_key":"01b7c7d9c7ee1","_type":"span","marks":[],"text":" – These can be liquidated within 24 hours and serve the ‘urgent but not immediate’ category of requirement."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"db1e169a819d","_type":"block","children":[{"_key":"db1e169a819d0","_type":"span","marks":[],"text":"Choose from the largest in the category to get the benefit of cost efficiency. Example (as of June 2025, Liquid Funds):"}],"markDefs":[],"style":"normal"},{"_key":"1cc8ed637bf8","_type":"table","rows":[{"_key":"row-0","_type":"tableRow","cells":["Fund","Corpus (INR mn)","10-yr Annualized Return"]},{"_key":"row-1","_type":"tableRow","cells":["SBI Liquid","688,705","6.28%"]},{"_key":"row-2","_type":"tableRow","cells":["HDFC Liquid","643,976","6.28%"]},{"_key":"row-3","_type":"tableRow","cells":["Aditya Birla Liquid","568,403","6.28%"]},{"_key":"row-4","_type":"tableRow","cells":["ICICI Pru Liquid","499,999","6.33%"]}]},{"_key":"5f577c10bdee","_type":"block","children":[{"_key":"5f577c10bdee0","_type":"span","marks":[],"text":"Define the emergency liquidity you could need, including how much could be required immediately and how much within the next 24-48 hours. Invest that in the two instruments above and the balance in other debt instruments shared in the section on fixed income investing."}],"markDefs":[],"style":"normal"}],"desc":"An unplanned pulling out from an investment can cause severe damage to the portfolio in several ways: Liquidating equity investments in a downward spiral can impair the returns and limit the potential to bounce back during an upswing. Liquidating debt investments can invite penalties and lower than assured returns.","icon":"fa-solid fa-shield-halved","link":"step-3-emergency-funds","num":"03","title":"Emergency Funds"},{"_key":"step-04","content":[{"_key":"ff240d30cfe8","_type":"block","children":[{"_key":"ff240d30cfe80","_type":"span","marks":[],"text":"We recommend exposure to equity through mutual funds, not direct stock picking. This can be done either through equity mutual funds or the NPS (National Pension System) scheme."}],"markDefs":[],"style":"normal"},{"_key":"e65d045119b7","_type":"block","children":[{"_key":"e65d045119b70","_type":"span","marks":[],"text":"Equity Mutual Funds"}],"markDefs":[],"style":"h2"},{"_key":"9a4748664165","_type":"block","children":[{"_key":"9a47486641650","_type":"span","marks":[],"text":"Keep the following in mind while choosing an equity fund:"}],"markDefs":[],"style":"normal"},{"_key":"3c4e9b6d8443","_type":"block","children":[{"_key":"3c4e9b6d84430","_type":"span","marks":[],"text":"Choose Direct Plans, not Regular Plans (to avoid distributor commissions)."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"51ead80c10e3","_type":"block","children":[{"_key":"51ead80c10e30","_type":"span","marks":[],"text":"Choose Index Funds (Passive) over Active Funds."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"b018b3f4f589","_type":"block","children":[{"_key":"b018b3f4f5890","_type":"span","marks":[],"text":"Choose large funds from reputed houses (e.g., SBI, UTI, LIC, HDFC, ICICI, Axis) to bring down the cost burden per unit."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"9e1fb4da77ad","_type":"block","children":[{"_key":"9e1fb4da77ad0","_type":"span","marks":[],"text":"Example (as of June 2025, Nifty-based index funds):"}],"markDefs":[],"style":"normal"},{"_key":"dc8059fe6f2d","_type":"table","rows":[{"_key":"row-0","_type":"tableRow","cells":["Fund","Corpus (INR mn)","10-yr Annualized Return"]},{"_key":"row-1","_type":"tableRow","cells":["UTI Nifty 50 Index Fund – Direct Growth","232,494","13.12%"]},{"_key":"row-2","_type":"tableRow","cells":["HDFC Nifty 50 Index Fund – Direct Growth","204,093","13.04%"]},{"_key":"row-3","_type":"tableRow","cells":["ICICI Pru Nifty 50 Index Fund – Direct Growth","135,350","12.96%"]},{"_key":"row-4","_type":"tableRow","cells":["SBI Nifty Index Fund – Direct Growth","98,387","12.96%"]}]},{"_key":"85d71325c971","_type":"block","children":[{"_key":"85d71325c9710","_type":"span","marks":[],"text":"Investing through NPS (National Pension System)"}],"markDefs":[],"style":"h2"},{"_key":"a7b1fdddfc61","_type":"block","children":[{"_key":"a7b1fdddfc610","_type":"span","marks":[],"text":"NPS has its own system of allocation of investor funds between debt and equity based on age. Hence, within one investment scheme you could potentially meet your allocation goals for exposure to equity as well as debt."}],"markDefs":[],"style":"normal"},{"_key":"117dd180f035","_type":"block","children":[{"_key":"117dd180f0350","_type":"span","marks":[],"text":"In case the NPS allocation is different from your own preferred allocation, you could select the non-NPS investments in a manner that enables you to reach your target allocation."}],"markDefs":[],"style":"normal"},{"_key":"d4e3e5f7f121","_type":"block","children":[{"_key":"d4e3e5f7f1210","_type":"span","marks":[],"text":"For example:"}],"markDefs":[],"style":"normal"},{"_key":"ddeedb94f525","_type":"block","children":[{"_key":"ddeedb94f5250","_type":"span","marks":[],"text":"If NPS allocation to equity is lower than your preference, choose equity funds to get a higher exposure than provided by NPS."}],"markDefs":[],"style":"normal"},{"_key":"fc83cfa5c9ba","_type":"block","children":[{"_key":"fc83cfa5c9ba0","_type":"span","marks":[],"text":"If NPS allocation to equity is higher than your preference, choose debt schemes outside NPS to get a higher exposure than provided by NPS. At the same time, NPS permits investors to choose a level of equity exposure lower than its recommended exposure for the age, but does not permit a higher exposure. Hence, you could also choose a lower exposure to equity within NPS if you so prefer."}],"markDefs":[],"style":"normal"},{"_key":"f62dd5702cd9","_type":"block","children":[{"_key":"f62dd5702cd90","_type":"span","marks":[],"text":"Allocate maximum permissible equity exposure under NPS for your age and choose passive funds within NPS to minimize costs."}],"markDefs":[],"style":"normal"},{"_key":"5cad4ae14bce","_type":"block","children":[{"_key":"5cad4ae14bce0","_type":"span","marks":[],"text":"Read our knowledge article on the NPS scheme for more information."}],"markDefs":[],"style":"normal"},{"_key":"b43d45fb2c6d","_type":"block","children":[{"_key":"b43d45fb2c6d0","_type":"span","marks":[],"text":"Refer to the following articles in our Information Centre to know more about the strategies recommended here:"}],"markDefs":[],"style":"normal"},{"_key":"88ab6b5d7260","_type":"block","children":[{"_key":"88ab6b5d72600","_type":"span","marks":["ul1wlg"],"text":"Index Investing Strategy"}],"level":1,"listItem":"bullet","markDefs":[{"_key":"ul1wlg","_type":"link","href":"/2023/08/11/index-funds"}],"style":"normal"},{"_key":"24e2fdb06785","_type":"block","children":[{"_key":"24e2fdb067850","_type":"span","marks":["4bgv89"],"text":"When investing in a Mutual Fund, choose a Direct MF over a Regular MF"}],"level":1,"listItem":"bullet","markDefs":[{"_key":"4bgv89","_type":"link","href":"/2023/08/18/when-investing-in-a-mutual-fund-choose-a-direct-mf-over-a-regular-mf"}],"style":"normal"},{"_key":"bfaf380056f6","_type":"block","children":[{"_key":"bfaf380056f60","_type":"span","marks":["8w8av"],"text":"Active and Passive Investment Management"}],"level":1,"listItem":"bullet","markDefs":[{"_key":"8w8av","_type":"link","href":"/2023/08/10/active-and-passive-investment-management"}],"style":"normal"}],"desc":"We recommend exposure to equity through mutual funds, not direct stock picking. This can be done either through equity mutual funds or the NPS (National Pension System) scheme.","icon":"fa-solid fa-arrow-trend-up","link":"step-4-investing-in-equity","num":"04","title":"Investing in Equity (Stocks / Mutual Funds)"},{"_key":"step-05","content":[{"_key":"ab302d0ea365","_type":"block","children":[{"_key":"ab302d0ea3650","_type":"span","marks":[],"text":"Government-backed schemes"}],"markDefs":[],"style":"h2"},{"_key":"54ab98b1983f","_type":"block","children":[{"_key":"54ab98b1983f0","_type":"span","marks":[],"text":"Prioritize government schemes for fixed income investing."}],"markDefs":[],"style":"normal"},{"_key":"e96801281862","_type":"block","children":[{"_key":"e968012818620","_type":"span","marks":[],"text":"An overview of the popular schemes:"}],"markDefs":[],"style":"normal"},{"_key":"ee00879f2bd3","_type":"table","rows":[{"_key":"row-0","_type":"tableRow","cells":["Scheme","Gross Return","Tax Treatment (New Regime)","Effective Post-Tax Return (10% / 20% / 30%)"]},{"_key":"row-1","_type":"tableRow","cells":["PPF","~7.1%","Fully tax-free","7.1 / 7.1 / 7.1"]},{"_key":"row-2","_type":"tableRow","cells":["SCSS","~8.2%","Interest taxable","7.38 / 6.56 / 5.74"]},{"_key":"row-3","_type":"tableRow","cells":["NSC","~7.7%","Interest taxable","6.93 / 6.16 / 5.39"]}]},{"_key":"e9cdaebd3594","_type":"block","children":[{"_key":"e9cdaebd35940","_type":"span","marks":[],"text":"NPS (National Pension System)"}],"markDefs":[],"style":"h2"},{"_key":"e569ffbc9171","_type":"block","children":[{"_key":"e569ffbc91710","_type":"span","marks":[],"text":"NPS can serve the need for both equity as well as fixed income investing since it follows an age-based allocation system."}],"markDefs":[],"style":"normal"},{"_key":"f7700f17fa89","_type":"block","children":[{"_key":"f7700f17fa890","_type":"span","marks":[],"text":"Some thumb rules:"}],"markDefs":[],"style":"normal"},{"_key":"ce315acda841","_type":"block","children":[{"_key":"ce315acda8410","_type":"span","marks":[],"text":"NPS permits investors to choose a level of equity exposure lower than its recommended exposure for the age, but does not permit a higher exposure. Hence, you could also choose a lower exposure to equity within NPS to reach your optimum allocation."}],"markDefs":[],"style":"normal"},{"_key":"b7da358e150c","_type":"block","children":[{"_key":"b7da358e150c0","_type":"span","marks":[],"text":"If NPS allocation to debt is higher than your preference, choose equity funds outside NPS to get a higher exposure than provided by NPS."}],"markDefs":[],"style":"normal"}],"desc":"Prioritize government schemes for fixed income investing. NPS can serve the need for both equity as well as fixed income investing since it follows an age-based allocation system.","icon":"fa-solid fa-building-columns","link":"step-5-investing-in-debt","num":"05","title":"Investing in Debt (Fixed Income)"},{"_key":"step-06","content":[{"_key":"ff4f0061576d","_type":"block","children":[{"_key":"ff4f0061576d0","_type":"span","marks":[],"text":"Ensure that tax implications are factored in, at the time of investment, on the income that is generated, and on liquidation or encashment."}],"markDefs":[],"style":"normal"},{"_key":"c08f30e12540","_type":"block","children":[{"_key":"c08f30e125400","_type":"span","marks":[],"text":"Review allocation and investments periodically, but at least annually, and rebalance. Market fluctuations may cause deviations."}],"markDefs":[],"style":"normal"},{"_key":"5186fda7e3c7","_type":"block","children":[{"_key":"5186fda7e3c70","_type":"span","marks":[],"text":"At any point of time, do not hesitate to reach out to an expert for guidance. You can reach the Dhanopinion investment advisors at response@dhanopinion.com."}],"markDefs":[],"style":"normal"}],"desc":"Ensure that tax implications are factored in, at the time of investment, on the income that is generated, and on liquidation or encashment. Review allocation and investments periodically, but at least annually, and rebalance.","icon":"fa-solid fa-rotate","link":"step-6-ongoing","num":"06","title":"Ongoing"}],"title":"Steps to Investing Success"}');
DROP TABLE IF EXISTS `sanity_caseStudiesPage`;
CREATE TABLE `sanity_caseStudiesPage` (
  `id` VARCHAR(255) NOT NULL,
  `data` JSON NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sanity_caseStudiesPage` (`id`, `data`) VALUES ('caseStudiesSingleton', '{"_createdAt":"2026-07-22T13:07:37Z","_id":"caseStudiesSingleton","_rev":"ZD9hpBEYl1x1VYz1fBNG3x","_system":{"base":{"id":"caseStudiesSingleton","rev":"ZD9hpBEYl1x1VYz1fBNDuX"}},"_type":"caseStudiesPage","_updatedAt":"2026-07-23T19:20:27Z","cases":[{"_key":"case-1","age":30,"content":[{"_key":"8e989a9d2a8b","_type":"block","children":[{"_key":"8e989a9d2a8b0","_type":"span","marks":[],"text":"Rajeev Agarwal is 30 years old and is married to Aarti who is 29. They have a daughter who is two years old. Rajeev is an engineer employed with a multinational firm and his annual salary is Rs 15 lakhs. Aarti is a housewife. They save 2 lakhs a year. They have 2 lakhs in an ICICI savings account for liquidity to meet any emergency needs and 3 lakhs invested in the ICICI Prudential Balanced Advantage Fund Growth. Their goals are to save for a home, their retirement and daughter''s education and marriage. Their risk tolerance is average for both of them."}],"markDefs":[],"style":"normal"},{"_key":"fd42bf58d7aa","_type":"block","children":[{"_key":"fd42bf58d7aa0","_type":"span","marks":[],"text":"Analysis and Recommendations"}],"markDefs":[],"style":"h2"},{"_key":"8668ff57d5e1","_type":"block","children":[{"_key":"8668ff57d5e10","_type":"span","marks":[],"text":"Rajiv and Aarti have a relatively simple portfolio. Their liquid savings amount of 200,000 is 40% of their portfolio. Their annual expenditures are 11,00,000 so their liquid savings are 2.2 months of expenditure. Looking through the balanced fund which has 66.66% equity and rest debt."}],"markDefs":[],"style":"normal"},{"_key":"f29c24620b72","_type":"block","children":[{"_key":"f29c24620b720","_type":"span","marks":[],"text":"What we''re going to do first is to identify the Easy Wins that we think they can make with respect to their portfolio."}],"markDefs":[],"style":"normal"},{"_key":"701e4c9f54d2","_type":"block","children":[{"_key":"701e4c9f54d20","_type":"span","marks":[],"text":"They have 3 lakhs in the ICICI Prudential Balanced Advantage Fund growth. This is a regular fund which has a much higher fee than the direct fund equivalent. This fund has an expense ratio of 1.53%. The direct version of this fund has an expense ratio of 0.91%. The portfolio for both classes are the same. By switching to the direct fund, they are going to save 0.62% per annum or Rs 1860 per annum, till they hold it."}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"860480f3db03","_type":"block","children":[{"_key":"860480f3db030","_type":"span","marks":[],"text":"Their liquid reserves are currently in a savings account earning 3%. They can instead keep their liquid savings in a liquid fund. The ICICI Prudential Liquid Fund as of July 31, 2023 had assets with a yield to maturity of 6.91 and the direct class has a fee of 0.21%. We therefore currently expect to earn about 6.71%. The maturity of the holdings of this fund are very short at 53 days so we do not expect any significant gains or losses from changes in interest rates. For now, the return is expected to be 6.5% and this will go up or down in future as interest rates go up or down. This means that they are going to have an additional income of Rs 7,420 per annum on their current balances of 200,000. Bank deposits are insured up to 5 lakhs per depositor, so their savings account is fully insured. The liquid fund invests in highly related short term instruments so the credit risk is low though it exists. However we believe that this is a switch worth making because this risk is very small and the cushion of incremental yield and return at 3.5% per annum is very high in relation to potential credit losses. You can access the money in a savings account on any day. For the liquid fund, you will have to put in a redemption and the money will be available the next day so the liquidity is almost as good."}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"5c6cbb4de730","_type":"block","children":[{"_key":"5c6cbb4de7300","_type":"span","marks":[],"text":"Other Observations"}],"markDefs":[],"style":"h2"},{"_key":"1a2d292781f9","_type":"block","children":[{"_key":"1a2d292781f90","_type":"span","marks":[],"text":"Their choice of balanced fund comes with an exit load of 1% if they sell more than 30% of their holdings in less than a year. The fees in the balanced fund are also very high. Even after switching to the direct class, they will still be paying 0.91% per annum. They should consider substitutes with lower fees and without loads."}],"markDefs":[],"style":"normal"},{"_key":"c5ebd3ea3c42","_type":"block","children":[{"_key":"c5ebd3ea3c420","_type":"span","marks":[],"text":"Asset Allocation"}],"markDefs":[],"style":"h2"},{"_key":"023488e5dd1c","_type":"block","children":[{"_key":"023488e5dd1c0","_type":"span","marks":[],"text":"If we look through the holdings of the balanced fund which has 66.6% in equity and the balance in fixed income, their asset allocation has a 40% exposure to equity and a 60% allocation to fixed income. The real driver of reasonably diversified portfolio''s returns is the amount of equity exposure. If you take more equity exposure and equity markets do well, you will make more money. If equity markets do badly, you will lose more money."}],"markDefs":[],"style":"normal"},{"_key":"03ef16884697","_type":"block","children":[{"_key":"03ef168846970","_type":"span","marks":[],"text":"Advisors have limited ability to forecast markets well and this is a decision clients should think about carefully, understand as best they can and get to a level of comfort with. Unlike easy wins there is expected reward but it comes with a potential downside if equity markets do poorly. Rajeev and Aarti have said that they have average risk tolerance. However if you look at their equity allocation, it is quite low for their age at 40%. Rajeev and Aarti are young. Most of their capital is their human capital embodied in their earnings capacity. They can stand the risk of losses in their equity investments with the expectation that increasing their equity exposure will increase their returns and portfolio value over time. Our recommendation for them given their average risk tolerance is 75%."}],"markDefs":[],"style":"normal"},{"_key":"a66bfb9d170b","_type":"block","children":[{"_key":"a66bfb9d170b0","_type":"span","marks":[],"text":"Investment Recommendations"}],"markDefs":[],"style":"h2"},{"_key":"5ce790c1b3fa","_type":"block","children":[{"_key":"5ce790c1b3fa0","_type":"span","marks":[],"text":"With a higher target allocation to equities, our recommendation is:"}],"markDefs":[],"style":"normal"},{"_key":"8b0bd5520981","_type":"block","children":[{"_key":"8b0bd55209810","_type":"span","marks":[],"text":"Switch savings account balances of 200,000 to Prudential Liquid Fund Direct Growth"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"fee427712c06","_type":"block","children":[{"_key":"fee427712c060","_type":"span","marks":[],"text":"Sell their Prudential Balanced Fund"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"a7d94b6282fb","_type":"block","children":[{"_key":"a7d94b6282fb0","_type":"span","marks":[],"text":"Reinvest the 300,000 as follows:"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"99178b4fffdd","_type":"block","children":[{"_key":"99178b4fffdd0","_type":"span","marks":[],"text":"50,000 in the Tier 1 National Pension Scheme (and repeat annually). Put 75% in the scheme Tier 1 Equity and 25% in Tier 1 Govt Securities. Pick State Bank of India as the investment provider."}],"level":2,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"693b29a22c0e","_type":"block","children":[{"_key":"693b29a22c0e0","_type":"span","marks":[],"text":"2,50,000 in the SBI Nifty Index ETF Direct Class"}],"level":2,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"55317fac7afc","_type":"block","children":[{"_key":"55317fac7afc0","_type":"span","marks":[],"text":"Logic for the NPS"}],"markDefs":[],"style":"h2"},{"_key":"0915da04195d","_type":"block","children":[{"_key":"0915da04195d0","_type":"span","marks":[],"text":"The earnings within the NPS are not going to generate any tax liability during the investment period. Any reallocations within funds also will not trigger any taxes. On withdrawal, 60% can be taken as a lump sum and will not generate any taxes. 40% has to be taken as an annuity. It is good to have an annuity for a portion of your assets since it will last for your life and will hedge the risk that you live a very long life and run out of retirement income. After retirement, your income level is going to be much lower and the effective tax rate will also be quite low. The fees at the NPS are about 0.10% and are much lower than the 1.53% they are currently paying on the balanced fund. They are also much lower than the 0.91% you can reduce the fees to by switching into a direct fund. We have picked State Bank of India as the investment advisor as it is the largest investment manager on the NPS platform."}],"markDefs":[],"style":"normal"},{"_key":"ecaad07a5198","_type":"block","children":[{"_key":"ecaad07a51980","_type":"span","marks":[],"text":"Rationale for the SBI Nifty Index ETF Direct Class"}],"markDefs":[],"style":"h2"},{"_key":"786f856018c9","_type":"block","children":[{"_key":"786f856018c90","_type":"span","marks":[],"text":"The SBI Nifty Index is the largest ETF in India. It gives you exposure to the Nifty Fifty which is the 50 largest companies in India. This covers the largest companies in India and the ones most likely to benefit from the projected growth of the economy and the consumer. The fees are very low at 0.04% for the direct class in comparison with about 1% for the average large capitalisation equity fund."}],"markDefs":[],"style":"normal"},{"_key":"d18cab408057","_type":"block","children":[{"_key":"d18cab4080570","_type":"span","marks":[],"text":"We would have been open to recommending an even broader index based like the Nifty 500. However these are very small in comparison to the Nifty 50 ETF and we have decided to guide to the SBI Nifty ETF Direct Class."}],"markDefs":[],"style":"normal"},{"_key":"5c854892c181","_type":"block","children":[{"_key":"5c854892c1810","_type":"span","marks":[],"text":"Another option that could have been considered is to put all the funds into the NPS scheme. The tax advantages are better but the downside is that the funds are not available until retirement and the couple may want to access the funds for a down payment on a house or for other purposes. One could use the NPS Tier II instead as that allows for early withdrawals as well. This would be a very good alternative as well and the portfolio here is actively managed and broader than the Nifty Fifty Index. The fees are a little higher than the index but they are very low at under 0.10%."}],"markDefs":[],"style":"normal"}],"desc":"Rajeev Agarwal is 30 years old and is married to Aarti who is 29. They have a daughter who is two years old. Rajeev is an engineer employed with a multinational firm and his annual salary is Rs 15 lakhs.","equity":40,"id":"case-1","risk":"Average","title":"Case 1"},{"_key":"case-2","age":47,"content":[{"_key":"39ba0ac5e3f3","_type":"block","children":[{"_key":"39ba0ac5e3f30","_type":"span","marks":[],"text":"Data coming soon."}],"markDefs":[],"style":"normal"}],"desc":"Sunil, an MNC senior manager has just got promoted as Chief Marketing Officer. He is 47, and his wife Anita, 45 is a homemaker. They have two school going children, a son 14 and a daughter 12.","equity":60,"id":"case-2","risk":"High","title":"Case 2"},{"_key":"case-3","age":92,"content":[{"_key":"ae8228150440","_type":"block","children":[{"_key":"ae82281504400","_type":"span","marks":[],"text":"Data coming soon."}],"markDefs":[],"style":"normal"}],"desc":"Jyoti Sharma is 92 years old. She is widowed. She has a pension of 75,000 per year adjusted for inflation. She owns a house which she used to live in and is now rented and generates a rent of 30,000 per month.","equity":10,"id":"case-3","risk":"Low","title":"Case 3"}],"title":"Case Studies"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-23', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-23","_rev":"8VyNrOEo8uWkcWBKVY1juF","_system":{"base":{"id":"article-23","rev":"2Ylzj40DB4KRPTzoYQFbjF"}},"_type":"post","_updatedAt":"2026-07-17T15:01:57Z","body":[{"_key":"4c502c5b8691","_type":"block","children":[{"_key":"4c502c5b86910","_type":"span","marks":[],"text":"The "},{"_key":"4c502c5b86911","_type":"span","marks":["2e8c21675530"],"text":"Senior Citizens Savings Scheme (SCSS)"},{"_key":"4c502c5b86912","_type":"span","marks":[],"text":" account is designed to offer superior returns to senior citizens, along with security of the money. It could be viewed as a retirement benefit account as it is only available to people above 60, with some exceptions. Along with excellent returns and safety, the account also offers tax benefits."}],"markDefs":[{"_key":"2e8c21675530","_type":"link","href":"https://www.nsiindia.gov.in/(S(1r31zi45fhv4hwvblq4bka45))/InternalPage.aspx?Id_Pk=62"}],"style":"normal"},{"_key":"d02f81445633","_type":"block","children":[{"_key":"d02f814456330","_type":"span","marks":[],"text":"By paying out interest every quarter to a designated account, the scheme fulfils one of the primary objectives of the scheme of providing regular income for seniors."}],"markDefs":[],"style":"normal"},{"_key":"24ad8ac3d08e","_type":"block","children":[{"_key":"24ad8ac3d08e0","_type":"span","marks":[],"text":"The account can be opened with the Post Office or with designated public and private sector banks ."}],"markDefs":[],"style":"normal"},{"_key":"c48046263945","_type":"block","children":[{"_key":"c480462639450","_type":"span","marks":[],"text":"With banks offering the facility of opening and closing the account online, it has become easier to open this account for people who have shied away from transacting at post offices."}],"markDefs":[],"style":"normal"},{"_key":"153ee5e402f7","_type":"block","children":[{"_key":"153ee5e402f70","_type":"span","marks":[],"text":"Benefits"}],"markDefs":[],"style":"h2"},{"_key":"6ebf2e3ffef1","_type":"block","children":[{"_key":"6ebf2e3ffef10","_type":"span","marks":[],"text":"The return offered SCSS is 8.2% currently and is the highest amongst all assured-return, government guaranteed schemes if you look at the comparative returns of all schemes under the section on government schemes."}],"markDefs":[],"style":"normal"},{"_key":"fa259e23378f","_type":"block","children":[{"_key":"fa259e23378f0","_type":"span","marks":[],"text":"Historically, SCSS has offered attractive rates of interest, as demonstrated by the "},{"_key":"fa259e23378f1","_type":"span","marks":["169d09a2cb21"],"text":"historical table"},{"_key":"fa259e23378f2","_type":"span","marks":[],"text":" below:"}],"markDefs":[{"_key":"169d09a2cb21","_type":"link","href":"https://www.nsiindia.gov.in/(S(cc442jiyooblg455jqkcax45))/InternalPage.aspx?Id_Pk=132"}],"style":"normal"},{"_key":"d919b023bd2c","_type":"table","rows":[{"_key":"26tntqk","_type":"tableRow","cells":["From","To","Interest Rate"]},{"_key":"91zkfok","_type":"tableRow","cells":["1 Apr 2015","31 Mar 2016","9.30"]},{"_key":"8e0qk9g","_type":"tableRow","cells":["1 Apr 2016","30 Sep 2016","8.60"]},{"_key":"o47xv5k","_type":"tableRow","cells":["1 Oct 2016","31 Mar 2017","8.50"]},{"_key":"d7rd6y2","_type":"tableRow","cells":["1 Apr 2017","30 Jun 2017","8.40"]},{"_key":"sfcqpnm","_type":"tableRow","cells":["1 Jul 2017","30 Sep 2018","8.30"]},{"_key":"byfrja2","_type":"tableRow","cells":["1 Oct 2018","30 Jun 2019","8.70"]},{"_key":"rxub3w1","_type":"tableRow","cells":["1 Jul 2019","31 Mar 2020","8.60"]},{"_key":"bsmybgd","_type":"tableRow","cells":["1 Apr 2020","30 Sep 2020","7.40"]},{"_key":"qbcs7mx","_type":"tableRow","cells":["1 Oct 2022","31 Dec 2022","7.60"]},{"_key":"6gw6ds2","_type":"tableRow","cells":["1 Jan 2023","31 Mar 2023","8.00"]},{"_key":"t5s2rhv","_type":"tableRow","cells":["1 Apr 2023","30 June 2026","8.20"]}]},{"_key":"c24352401b18","_type":"block","children":[{"_key":"c24352401b180","_type":"span","marks":[],"text":"The interest earned on the account is added to the account holder’s taxable income for the year."}],"markDefs":[],"style":"normal"},{"_key":"f29af210866b","_type":"block","children":[{"_key":"f29af210866b0","_type":"span","marks":[],"text":"Being a government scheme, it offers the highest level of security to account holders."}],"markDefs":[],"style":"normal"},{"_key":"2edc08fca864","_type":"block","children":[{"_key":"2edc08fca8640","_type":"span","marks":[],"text":"Features"}],"markDefs":[],"style":"h2"},{"_key":"38d7848b1c2e","_type":"block","children":[{"_key":"38d7848b1c2e0","_type":"span","marks":[],"text":"An account can be opened with a minimum of ₹ 1,000. The account operates like a Fixed Deposit. Once opened, you cannot add or subtract from it. At the time of closure, the full amount has to be withdrawn."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"763c1acfeff9","_type":"block","children":[{"_key":"763c1acfeff90","_type":"span","marks":[],"text":"Multiple accounts can be opened subject to a maximum limit of ₹ 30 lakh at any point of time in the name of a depositor."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"ddae0dd42b80","_type":"block","children":[{"_key":"ddae0dd42b800","_type":"span","marks":[],"text":"An account holder may operate more than one account under this Scheme subject to the condition that the deposits in all the accounts taken together shall not exceed the maximum limit of ₹ 30 lakh."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"092021ff475c","_type":"block","children":[{"_key":"092021ff475c0","_type":"span","marks":[],"text":"The account can be opened by a person who has reached the age of 60. This is lowered, with some conditions, to:"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"041e50a0f531","_type":"block","children":[{"_key":"041e50a0f5310","_type":"span","marks":[],"text":"55 for people who have retired under Superannuation, VRS or Special VRS."}],"level":2,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"022ce47f42eb","_type":"block","children":[{"_key":"022ce47f42eb0","_type":"span","marks":[],"text":"50 for retired Defence Services personnel"}],"level":2,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"d637185a386d","_type":"block","children":[{"_key":"d637185a386d0","_type":"span","marks":[],"text":"Interest is paid on the first working day of the calendar quarter for the previous quarter."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a5f34404ac7a","_type":"block","children":[{"_key":"a5f34404ac7a0","_type":"span","marks":[],"text":"On expiry of the account on completion of 5 years, the account can be closed or extended for another 3 years. After closure a SCSS account can be opened once again, if needed."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"abe1ecf15ee8","_type":"block","children":[{"_key":"abe1ecf15ee80","_type":"span","marks":[],"text":"The SCSS is closest in its method of operation to Fixed Deposits. You can place money in an account only once, after which it keeps paying you interest every quarter. The rate of interest is determined on the day you open an account and remains unchanged during the period the account is live, unlike a PPF account where the updated interest rates are applicable on the entire balance in the account."}],"markDefs":[],"style":"normal"},{"_key":"0ae10159eda8","_type":"block","children":[{"_key":"0ae10159eda80","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"96f0fc165ad2","_type":"block","children":[{"_key":"96f0fc165ad20","_type":"span","marks":[],"text":"It should be considered by everyone who is eligible. The account can be opened at Post Offices and designated commercial banks."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-22T18:30:00.000Z","slug":{"_type":"slug","current":"2023-09-01-senior-citizen-saving-scheme"},"title":"Senior Citizen Saving Scheme (SCSS)"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-4', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-4","_rev":"Wh8G8yB47gE3dM8t7PKyLt","_system":{"base":{"id":"article-4","rev":"Wh8G8yB47gE3dM8t7PKtLf"}},"_type":"post","_updatedAt":"2026-07-22T18:26:19Z","body":[{"_key":"e5bc70d8075b","_type":"block","children":[{"_key":"e5bc70d8075b0","_type":"span","marks":[],"text":"We are accustomed to using money as a stable store of value over short horizons. We have a tendency of evaluating portfolio outcomes and risk in nominal terms rather than in real terms which is what really matters over long horizons."}],"markDefs":[],"style":"normal"},{"_key":"821b4e3537e0","_type":"block","children":[{"_key":"821b4e3537e00","_type":"span","marks":[],"text":"What do we mean by “nominal terms?” What is “real terms?”"}],"markDefs":[],"style":"normal"},{"_key":"45a3a6c56ce8","_type":"block","children":[{"_key":"45a3a6c56ce80","_type":"span","marks":[],"text":"Let us take an example."}],"markDefs":[],"style":"normal"},{"_key":"62f87c425926","_type":"block","children":[{"_key":"62f87c4259260","_type":"span","marks":[],"text":"You have an investment that delivers a return of 7% per year. The ₹ 1,000 you invested at 7% on 1st January 2021 gave you an additional ₹ 70 on 1st January 2022. You spend the ₹ 70 and invest the ₹ 1,000 once again at 7% on 1st January 2022 which gives you an additional ₹ 70 on 1st January 2023 leaving the ₹ 1,000 intact. If the return remains unchanged you will get an another ₹ 70 on 1st January, 2024. And so on."}],"markDefs":[],"style":"normal"},{"_key":"379c71492c08","_type":"block","children":[{"_key":"379c71492c080","_type":"span","marks":[],"text":"The price of a masala dosa at your favourite Udupi restaurant on 1st January, 2022 is ₹ 70. You received the ₹ 70- return from your investment and spent it on the dosa on 1st January, 2022."}],"markDefs":[],"style":"normal"},{"_key":"3da3df81a4ec","_type":"block","children":[{"_key":"3da3df81a4ec0","_type":"span","marks":[],"text":"You want to eat a masala dosa at your favourite Udupi restaurant once again on 1st January,2023 when you receive the ₹ 70 return from the investment. You walk in with a swagger and order your favourite dosa and devour it hungrily. When you ask for the bill, you get a shock when you realize you have to pay ₹ 77. You protest and speak to the owner who expresses his inability to reduce the price as the cost of input materials like flour and potatoes has gone up. You end up paying ₹ 77. Not only have you paid the earned interest but also an additional ₹ 7 leaving you with lesser to invest for the future."}],"markDefs":[],"style":"normal"},{"_key":"eecef372e4e8","_type":"block","children":[{"_key":"eecef372e4e80","_type":"span","marks":[],"text":"This is the impact of inflation and its relationship with investing."}],"markDefs":[],"style":"normal"},{"_key":"3683bf569872","_type":"block","children":[{"_key":"3683bf5698720","_type":"span","marks":[],"text":"On 1st January, 2023, you have received ₹ 70 in “nominal terms.”"}],"markDefs":[],"style":"normal"},{"_key":"1d09fd2eea9a","_type":"block","children":[{"_key":"1d09fd2eea9a0","_type":"span","marks":[],"text":"However, in “real terms” it is worth less than it was worth on 1st January, 2022."}],"markDefs":[],"style":"normal"},{"_key":"e11c48a8498a","_type":"block","children":[{"_key":"e11c48a8498a0","_type":"span","marks":[],"text":"Why?"}],"markDefs":[],"style":"normal"},{"_key":"1bf5dd6420fc","_type":"block","children":[{"_key":"1bf5dd6420fc0","_type":"span","marks":[],"text":"Because today’s ₹ 70 is not able to buy you the same amount of goods and services that it was able to buy you one year back."}],"markDefs":[],"style":"normal"},{"_key":"e219d1051e89","_type":"block","children":[{"_key":"e219d1051e890","_type":"span","marks":[],"text":"The price of the dosa increasing from ₹ 70 to ₹ 77 is known as inflation."}],"markDefs":[],"style":"normal"},{"_key":"272037213fad","_type":"block","children":[{"_key":"272037213fad0","_type":"span","marks":[],"text":"Inflation can be defined as an increase in prices from one period to another. On the flip side, it could be described as the rate at which the value of money erodes or depreciates or loses its power to purchase. In the context of investment, it is the rate at which one needs to earn from investments to keep the standard of living at the same level. If inflation in 10% and your “nominal” investment return is 7%, your “real” or effective investment return is minus 3%."}],"markDefs":[],"style":"normal"},{"_key":"2dd17976d518","_type":"block","children":[{"_key":"2dd17976d5180","_type":"span","marks":[],"text":"In economic terms, increase in the supply of money relative to the productive output leads to more money chasing fewer goods which results in inflation."}],"markDefs":[],"style":"normal"},{"_key":"0c7401fa2bbc","_type":"block","children":[{"_key":"0c7401fa2bbc0","_type":"span","marks":[],"text":"Inflation, though it seems opposed to the well-being of individuals, is supported by policy makers as it is believed to promote a stable, sustainable and predictable economic environment. However, at low/ moderate levels. When it goes beyond these levels, it can have deleterious economic outcomes."}],"markDefs":[],"style":"normal"},{"_key":"b8d4b7a6d051","_type":"block","children":[{"_key":"b8d4b7a6d0510","_type":"span","marks":[],"text":"If the price of everything were to rise at exactly the same rate, then it would not matter and nothing would change. People would not become richer or poorer as a result of inflation. However, not everything is impacted equally."}],"markDefs":[],"style":"normal"},{"_key":"b8ca34f68ace","_type":"block","children":[{"_key":"b8ca34f68ace0","_type":"span","marks":[],"text":"Among asset classes, the liquid asset classes tend to appreciate at a slower pace as compared to the less liquid asset classes. Hence, a move away from holding liquid assets is recommended as a strategy to counter the impact of inflation over a long-term."}],"markDefs":[],"style":"normal"},{"_key":"e8d4834fe9f0","_type":"block","children":[{"_key":"e8d4834fe9f00","_type":"span","marks":[],"text":"What should individuals strive for?"}],"markDefs":[],"style":"normal"},{"_key":"aaae311b299c","_type":"block","children":[{"_key":"aaae311b299c0","_type":"span","marks":[],"text":"That their investments yield a return which is higher than the rate of inflation."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a48f9a2e33f0","_type":"block","children":[{"_key":"a48f9a2e33f00","_type":"span","marks":[],"text":"That their earnings increase annually at least as much as the rate of inflation."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"624bd8891e6f","_type":"block","children":[{"_key":"624bd8891e6f0","_type":"span","marks":[],"text":"The International Monetary Fund (IMF) reports India’s inflation since 1960 as follows:"}],"markDefs":[],"style":"normal"},{"_key":"f2840d6b46f5","_type":"block","children":[{"_key":"3e96a585bef00","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/dbc721038e5aafd1ae192565f09a51f43ac6ef6c-752x584.png","_key":"05c7d5774fc3","_type":"image"},{"_key":"fdf7563af0f7","_type":"block","children":[{"_key":"1f4060f133880","_type":"span","marks":[],"text":"Source: "},{"_key":"1f4060f133881","_type":"span","marks":["97e0e712a649"],"text":"World Bank"}],"markDefs":[{"_key":"97e0e712a649","_type":"link","href":"https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=IN"}],"style":"normal"},{"_key":"9d40a95a3f64","_type":"block","children":[{"_key":"54cdd4c982e10","_type":"span","marks":[],"text":"We can see that inflation based on consumer prices has hovered at around 5% annually over the last quarter of a century, with a spike towards the end of the first decade. Inflation in the last century has been much higher."}],"markDefs":[],"style":"normal"},{"_key":"2cab0ce5e267","_type":"block","children":[{"_key":"8a25bce8ce1f0","_type":"span","marks":[],"text":"What this means is that the value of what a Rupee could buy has become smaller over time."}],"markDefs":[],"style":"normal"},{"_key":"22cea4a4d734","_type":"block","children":[{"_key":"d0492a9772730","_type":"span","marks":[],"text":"How much smaller?"}],"markDefs":[],"style":"normal"},{"_key":"e048041a4f09","_type":"block","children":[{"_key":"a85f8213a5ce0","_type":"span","marks":[],"text":"IMF tells us how much in the chart below:"}],"markDefs":[],"style":"normal"},{"_key":"8cb68401b57e","_type":"block","children":[{"_key":"273cdd3775690","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/9c9c22d014f8ae75cc57b5868a327e843e91de87-1005x802.png","_key":"64b204f2962c","_type":"image"},{"_key":"922f40a55297","_type":"block","children":[{"_key":"d5b5611bb6a80","_type":"span","marks":[],"text":"Source: "},{"_key":"d5b5611bb6a81","_type":"span","marks":["fc52abed1557"],"text":"World Bank"}],"markDefs":[{"_key":"fc52abed1557","_type":"link","href":"https://data.worldbank.org/indicator/fp.cpi.totl?locations=in"}],"style":"normal"},{"_key":"eb6ecc446999","_type":"block","children":[{"_key":"b8342cf2d0a60","_type":"span","marks":[],"text":"An item that cost ₹2.50 in 1960 cost ₹100 in 2010 and ₹227 in 2024."}],"markDefs":[],"style":"normal"},{"_key":"7cd491f0b5d9","_type":"block","children":[{"_key":"512df404c94c0","_type":"span","marks":[],"text":"According to another calculator provided by "},{"_key":"512df404c94c1","_type":"span","marks":["e0bded3a32d9"],"text":"World Data"},{"_key":"512df404c94c2","_type":"span","marks":[],"text":", if you could buy a certain basket of goods and services for ₹ 1,000 in 1961, in 2022, 61 years later, you need ₹ 78,071 to buy it."}],"markDefs":[{"_key":"e0bded3a32d9","_type":"link","href":"https://www.worlddata.info/asia/india/inflation-rates.php"}],"style":"normal"},{"_key":"b6dc13cd3516","_type":"block","children":[{"_key":"ea3804a0139a0","_type":"span","marks":[],"text":"Another way of looking at the decline in the value of Rupee over time is its value against the US dollar, as shown in the chart below, produced by "},{"_key":"ea3804a0139a1","_type":"span","marks":["afe5d10d92eb"],"text":"XE.com"},{"_key":"ea3804a0139a2","_type":"span","marks":[],"text":"."}],"markDefs":[{"_key":"afe5d10d92eb","_type":"link","href":"https://www.xe.com/currencycharts/?from=USD&to=INR&view=10Y"}],"style":"normal"},{"_key":"1f363bb2e35a","_type":"block","children":[{"_key":"ae2f660329520","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/99c632ed54a5f410966874d3845e44f9df1440d6-1488x552.png","_key":"857b6ab40687","_type":"image"},{"_key":"2c4027612a12","_type":"block","children":[{"_key":"8b095d447d2f0","_type":"span","marks":[],"text":"Source: "},{"_key":"8b095d447d2f1","_type":"span","marks":["9aff816985b2"],"text":"XE.com"}],"markDefs":[{"_key":"9aff816985b2","_type":"link","href":"https://www.xe.com/currencycharts/?from=USD&to=INR&view=10Y"}],"style":"normal"},{"_key":"d44598712e67","_type":"block","children":[{"_key":"6a8e1aef1c680","_type":"span","marks":[],"text":"In June 2016, one could buy one dollar with ₹67. In June 2026, one needs more than ₹96 to buy the same one dollar."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-03-25T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-25-inflation-real-value-and-the-money-illusion"},"title":"Inflation, Real Value and the Money Illusion"}');
