INSERT INTO `sanity_homePage` (`id`, `data`) VALUES ('homeSingleton', '{"_createdAt":"2026-07-15T07:09:54Z","_id":"homeSingleton","_rev":"s2wDSUpWBbCAmLaTqQeWIY","_system":{"base":{"id":"homeSingleton","rev":"8VyNrOEo8uWkcWBKVWpWBn"}},"_type":"homePage","_updatedAt":"2026-07-16T16:06:37Z","audienceParagraphs":["The resources on this website will be of help to anyone interested in investing. However, the primary focus of the content is individual investors who have limited time, resources and expertise to devote to investment research and analyses.","Every individual can also get some simple guidance to have a pretty good solution without knowing or learning too much about this, but everyone should learn a little bit."],"audienceTitle":"Who is it for?","ctaButtonLink":"/consulting-waitlist","ctaButtonText":"I would like a personalised consulting session","ctaText":"The philosophy, strategy and suggestions shared on these pages are of universal relevance and should deliver value to every investor. Should you wish to seek a confidential, one-on-one, paid consulting with one of our experts, kindly click the button below. Personalised consulting is expected to be launched in the future. At this time you will be joining a wait-list. We will reach out when the service comes on-stream and a slot becomes available to arrange a session at a mutually convenient time.","ctaTitle":"Personalised Consulting","expectations":[{"_key":"ex1","desc":"Creation of a better match between your goals, circumstances and preferences and your investments.","heading":"Better Strategy"},{"_key":"ex2","desc":"Reduced investing complexity and better understanding of investment choices.","heading":"Reduced Complexity"},{"_key":"ex3","desc":"Improved returns — a little.","heading":"Improved Returns"},{"_key":"ex4","desc":"Reduced risk — a little.","heading":"Reduced Risk"}],"expectationsTitle":"What you can expect","focusPills":["Simple investment strategies that have a logic and can be implemented","Reducing the clutter of options to a few good ones, saving you time and effort"],"heroSubtitle":"It is difficult for large institutions, and it is even more difficult for individuals because they have less knowledge and resources. You can make it easier by evaluating our suggestions and if you are convinced, implement them.","heroTitle":"Investing is Difficult","notExpectations":[{"_key":"nex1","desc":"Substantial improvement in returns.","heading":"Exponential Returns"},{"_key":"nex2","desc":"Elimination, or substantial reduction of the risk of loss.","heading":"Elimination of Risk"},{"_key":"nex3","desc":"Reduced stress in investing.","heading":"Reduced Stress"}],"notExpectationsTitle":"What you should not expect","scopeText":"The current scope covers financial assets such as mutual funds, government sponsored financial instruments and fixed deposits.","scopeTitle":"Scope","startingPoints":[{"_key":"sp1","desc":"Quick actions with no downside to improve your investment outcomes immediately.","icon":"🏆","label":"Easy Wins","to":"/easy-wins"},{"_key":"sp2","desc":"A straightforward approach to building a portfolio that works.","icon":"⚡","label":"Simple Investment Strategy","to":"/simple-investment-strategy"},{"_key":"sp3","desc":"Core principles behind every sound investment decision.","icon":"◆","label":"Investment Philosophy","to":"/investment-philosophy"},{"_key":"sp4","desc":"Follow the key steps in our investing strategy, starting with the evaluation of debt.","icon":"📈","label":"Steps to Success","to":"/steps-to-investing-success"}]}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-21', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-21","_rev":"8VyNrOEo8uWkcWBKVY1VWJ","_system":{"base":{"id":"article-21","rev":"VvoTrv03okwDAu5fbFlP0Y"}},"_type":"post","_updatedAt":"2026-07-17T14:59:08Z","body":[{"_key":"f7222a8732a8","_type":"block","children":[{"_key":"f7222a8732a80","_type":"span","marks":[],"text":"A Government Bond is a debt instrument issued by the Central or a State government for the purpose of mobilizing public money, usually for the purpose of financing infrastructure projects. The authority issuing the Bonds is responsible for redeeming them, or paying the interest and maturity proceeds of the instrument. As the purpose usually is to finance infrastructure development, the maturity periods can be long, usually between 5 and 40 years."}],"markDefs":[],"style":"normal"},{"_key":"cb7ed7a896a6","_type":"block","children":[{"_key":"cb7ed7a896a60","_type":"span","marks":[],"text":"They are also known as government securities (G-Secs) and GILTs. Individual investors can directly invest in these instruments, subject to the stipulations and requirements of each issue."}],"markDefs":[],"style":"normal"},{"_key":"affeb0efbad8","_type":"block","children":[{"_key":"affeb0efbad80","_type":"span","marks":[],"text":"They are investments that are guaranteed by the issuing government authority and could be considered as one of the safest forms of investment. Hence, they are ideal investments for risk-averse investors."}],"markDefs":[],"style":"normal"},{"_key":"1d07467bc99f","_type":"block","children":[{"_key":"1d07467bc99f0","_type":"span","marks":[],"text":"Types of Bonds"}],"markDefs":[],"style":"h2"},{"_key":"c8d0b719badf","_type":"block","children":[{"_key":"c8d0b719badf0","_type":"span","marks":[],"text":"Both the central and state governments can issue bonds of different types:"}],"markDefs":[],"style":"normal"},{"_key":"0a935d060e81","_type":"block","children":[{"_key":"0a935d060e810","_type":"span","marks":[],"text":"Fixed-rate bonds"}],"markDefs":[],"style":"h3"},{"_key":"44f4726ee677","_type":"block","children":[{"_key":"44f4726ee6770","_type":"span","marks":[],"text":"This is the most common type. The rate remains fixed during the period of existence of the bonds. The interest rate is known as the coupon rate."}],"markDefs":[],"style":"normal"},{"_key":"b74ae3602c67","_type":"block","children":[{"_key":"b74ae3602c670","_type":"span","marks":[],"text":"For investors buying and selling Bonds in the secondary market, the value can change based on market conditions. During inflationary conditions, if interest rates for competing investments rise, the face value of the bonds will decline to a level where the coupon rate, which is fixed, becomes competitive. And vice versa."}],"markDefs":[],"style":"normal"},{"_key":"58dee77da3cd","_type":"block","children":[{"_key":"58dee77da3cd0","_type":"span","marks":[],"text":"Floating Rate Bonds (FRBs)"}],"markDefs":[],"style":"h3"},{"_key":"4398e4245c8b","_type":"block","children":[{"_key":"4398e4245c8b0","_type":"span","marks":[],"text":"The rate is not fixed for the entire tenure but keeps changing based on a pre-determined formula as well as the intervals at which the change would be effective."}],"markDefs":[],"style":"normal"},{"_key":"7288675bcd36","_type":"block","children":[{"_key":"7288675bcd360","_type":"span","marks":[],"text":"Sovereign Gold Bonds (SGBs)"}],"markDefs":[],"style":"h3"},{"_key":"99ff47c24f47","_type":"block","children":[{"_key":"99ff47c24f470","_type":"span","marks":[],"text":"These bonds are a method of attracting investments from the public that would normally go into physical gold or gold assets such as jewellery, as has been the tradition in India. These bonds are pegged to the value of gold and also pay a small interest on the investment."}],"markDefs":[],"style":"normal"},{"_key":"d39421b1f353","_type":"block","children":[{"_key":"d39421b1f3530","_type":"span","marks":[],"text":"Hence, investors will not only get value on maturity based on the appreciation (or depreciation) in gold prices, which they would be subject to even if they had invested in physical gold. In addition, they will also receive interest, which they would not in case of physical gold. These are also exempt from capital gains tax in the hands of individuals."}],"markDefs":[],"style":"normal"},{"_key":"d4bdc90dfd6d","_type":"block","children":[{"_key":"d4bdc90dfd6d0","_type":"span","marks":[],"text":"Inflation-Indexed Bonds"}],"markDefs":[],"style":"h3"},{"_key":"c010cf50dd23","_type":"block","children":[{"_key":"c010cf50dd230","_type":"span","marks":[],"text":"These are specifically meant for retail investors and seek to deliver a return that compensates them for the rise in prices during the currency of the bond. Mostly indexed to the Consumer Price Index (CPI), the purpose is to provide a constant return to investors, taking inflation into account."}],"markDefs":[],"style":"normal"},{"_key":"a9acb05ee81e","_type":"block","children":[{"_key":"a9acb05ee81e0","_type":"span","marks":[],"text":"Treasury Bills (T-Bills)"}],"markDefs":[],"style":"h3"},{"_key":"531e17965087","_type":"block","children":[{"_key":"531e179650870","_type":"span","marks":[],"text":"Bonds issued for under a year are known as T-Bills."}],"markDefs":[],"style":"normal"},{"_key":"6f81ffeb6c07","_type":"block","children":[{"_key":"6f81ffeb6c070","_type":"span","marks":[],"text":"7.75% GOI Savings Bond"}],"markDefs":[],"style":"h3"},{"_key":"a9f47ec419ce","_type":"block","children":[{"_key":"a9f47ec419ce0","_type":"span","marks":[],"text":"Designed as a high-return Bond as compared to several others in existence, this instrument is reserved for investment by resident individuals. Interest earnings from such bonds are taxable under the Income Tax Act 1961 as per the investors’ applicable income tax slab. The minimum amount at which these bonds are issued is Rs. 1000 and in multiples of Rs. 1000 thereof."}],"markDefs":[],"style":"normal"},{"_key":"d19cac2ec948","_type":"block","children":[{"_key":"d19cac2ec9480","_type":"span","marks":[],"text":"Tax free Bonds"}],"markDefs":[],"style":"h3"},{"_key":"058cd2367d24","_type":"block","children":[{"_key":"058cd2367d240","_type":"span","marks":[],"text":"Certain public sector entities get permission to issue tax-free bonds, for raising money for projects of particular importance. These are attractive investments for people with large taxable incomes as it gives them one source that is not taxable."}],"markDefs":[],"style":"normal"},{"_key":"173fb03f0a88","_type":"block","children":[{"_key":"173fb03f0a880","_type":"span","marks":[],"text":"Zero coupon Bonds"}],"markDefs":[],"style":"h3"},{"_key":"2e0e292e3572","_type":"block","children":[{"_key":"2e0e292e35720","_type":"span","marks":[],"text":"These are issued at a discount, without any attached coupons. The face value is paid to the investor on redemption at maturity. The difference between the buying and selling prices becomes the earning for the investor."}],"markDefs":[],"style":"normal"},{"_key":"fb3055af7e6b","_type":"block","children":[{"_key":"fb3055af7e6b0","_type":"span","marks":[],"text":"Advantages and disadvantages of investing in Government Bonds?"}],"markDefs":[],"style":"h3"},{"_key":"0b80250c8e05","_type":"block","children":[{"_key":"0b80250c8e050","_type":"span","marks":[],"text":"Government Bonds are virtually risk-free as they are issued by the Central and State governments."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"544b46c8263e","_type":"block","children":[{"_key":"544b46c8263e0","_type":"span","marks":[],"text":"Interest earned on Bonds are disbursed to holders at regular intervals, as specified in the terms of issuance usually 6 months. This becomes a source of regular income for investors without exposure to market-related movements."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f3c12ccfd12a","_type":"block","children":[{"_key":"f3c12ccfd12a0","_type":"span","marks":[],"text":"Liquid investment. It is a tradeable security and can be sold at prevailing prices without delay and without penalty."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"c12e6acd09a2","_type":"block","children":[{"_key":"c12e6acd09a20","_type":"span","marks":[],"text":"Bonds are subject to rate fluctuations."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f873cece87a9","_type":"block","children":[{"_key":"f873cece87a90","_type":"span","marks":[],"text":"How can individuals buy and sell Government Bonds?"}],"markDefs":[],"style":"h3"},{"_key":"79e55484db37","_type":"block","children":[{"_key":"79e55484db370","_type":"span","marks":[],"text":"Individuals can invest in Bonds through multiple channels."}],"markDefs":[],"style":"normal"},{"_key":"5f44cea69bfd","_type":"block","children":[{"_key":"5f44cea69bfd0","_type":"span","marks":[],"text":"Direct Investment"}],"markDefs":[],"style":"h4"},{"_key":"0855493d7598","_type":"block","children":[{"_key":"0855493d75980","_type":"span","marks":[],"text":"As Bonds are market securities, they can be bought and sold on the marketplace, similar to buying and selling stocks."}],"markDefs":[],"style":"normal"},{"_key":"713e9b3331e1","_type":"block","children":[{"_key":"713e9b3331e10","_type":"span","marks":[],"text":"While traditionally buying and selling of securities was conducted through brokers, with online trading gaining ground, interested individuals can open a trading account and a demat account (where the bought security will be deposited) through a broking house and conduct purchase and sale of Bonds."}],"markDefs":[],"style":"normal"},{"_key":"04c60a42c78b","_type":"block","children":[{"_key":"04c60a42c78b0","_type":"span","marks":[],"text":"Directly through the NSE goBID bidding process"}],"markDefs":[],"style":"h4"},{"_key":"aeff7e9804d4","_type":"block","children":[{"_key":"aeff7e9804d40","_type":"span","marks":[],"text":"Individuals can participate in the non-competitive bidding (NCB) process through which bids can be placed online at the time of fresh issuance of Bonds. This is akin to investing in share IPOs. This can be done through the goBID web portal of the NSE. The government determines the yield based on the bids received. You will need to register/ create an account for this bidding."}],"markDefs":[],"style":"normal"},{"_key":"17fe47f8fbf6","_type":"block","children":[{"_key":"17fe47f8fbf60","_type":"span","marks":[],"text":"RBI Retail Direct"}],"markDefs":[],"style":"h4"},{"_key":"d3270defbe9e","_type":"block","children":[{"_key":"d3270defbe9e0","_type":"span","marks":[],"text":"Since November 2021, individuals can invest in G-Secs through the Retail Direct Gilt (RDG) process of RBI, which allows you to participate in primary issuance."}],"markDefs":[],"style":"normal"},{"_key":"9fbdaa03cb2b","_type":"block","children":[{"_key":"9fbdaa03cb2b0","_type":"span","marks":[],"text":"Focused Mutual Funds"}],"markDefs":[],"style":"h4"},{"_key":"437ce03a3a92","_type":"block","children":[{"_key":"437ce03a3a920","_type":"span","marks":[],"text":"Investment in Government Bonds can also be made through Mutual Funds that focus on this investment product. Though an indirect channel, this has gained popularity amongst individuals, just like Equity MFs have gained traction with individuals, against direct investment. These MFs are also referred to as GILT-edged MFs."}],"markDefs":[],"style":"normal"},{"_key":"daa7f0645140","_type":"block","children":[{"_key":"daa7f06451400","_type":"span","marks":[],"text":"Historical returns"}],"markDefs":[],"style":"h3"},{"_key":"143ad0e94630","_type":"block","children":[{"_key":"143ad0e946300","_type":"span","marks":[],"text":"Returns delivered by a few of the large GILT mutual funds as available on the "},{"_key":"143ad0e946301","_type":"span","marks":["f31eb787a3ed"],"text":"moneycontrol.com"},{"_key":"143ad0e946302","_type":"span","marks":[],"text":" website, as on 11th July, 2025:"}],"markDefs":[{"_key":"f31eb787a3ed","_type":"link","href":"https://www.moneycontrol.com/mutual-funds/"}],"style":"normal"},{"_key":"392c0a91df01","_type":"table","rows":[{"_key":"ynexomx","_type":"tableRow","cells":["Scheme Name","AuM (Cr.)","1Y","5Y","10Y"]},{"_key":"ciye3pd","_type":"tableRow","cells":["SBI Magnum Gilt Fund - Direct Plan - Growth","12,148.74","8.66%","6.52%","8.65%"]},{"_key":"qmu0roh","_type":"tableRow","cells":["ICICI Prudential Gilt Fund - Direct Plan - Growth","7,275.51","10.21%","6.89%","8.82%"]},{"_key":"9wrbm08","_type":"tableRow","cells":["Kotak Gilt - Investment - PF and Trust - Direct Plan - Growth","3,809.82","7.99%","6.35%","8.44%"]},{"_key":"ggksp5g","_type":"tableRow","cells":["Kotak Gilt - Investment - Direct Plan - Growth","3,809.82","7.99%","6.35%","8.41%"]},{"_key":"9cgkauu","_type":"tableRow","cells":["Bandhan Government Securities Fund - Investment Plan - Direct Plan - Growth","3,123.96","7.45%","5.91%","8.48%"]},{"_key":"b27yziu","_type":"tableRow","cells":["HDFC Gilt Fund - Direct Plan - Growth","3,045.35","9.40%","5.80%","7.45%"]},{"_key":"uer4ecd","_type":"tableRow","cells":["Aditya Birla Sun Life Government Securities Fund - Direct Plan - Growth","2,463.18","8.03%","6.09%","8.53%"]},{"_key":"r85kzl4","_type":"tableRow","cells":["Nippon India Gilt Fund- Direct Plan - Growth","2,063.18","8.67%","5.93%","8.83%"]},{"_key":"mjvghfp","_type":"tableRow","cells":["Nippon India Gilt Fund- Direct Plan - Automatic Capital App","2,063.18","8.67%","5.93%","8.83%"]},{"_key":"e6egh0b","_type":"tableRow","cells":["DSP Gilt Fund - Direct Plan - Growth","1,852.40","8.61%","6.48%","8.56%"]}]},{"_key":"e267e29e01b0","_type":"block","children":[{"_key":"e267e29e01b00","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"2674c82d6832","_type":"block","children":[{"_key":"2674c82d68320","_type":"span","marks":[],"text":"Government Bonds are a part of the Fixed Income type of investments that earn on the basis of pre-determined rates or formulae and are not dependent on market conditions. Hence, the usual suspects will be:"}],"markDefs":[],"style":"normal"},{"_key":"3b1b6f445967","_type":"block","children":[{"_key":"3b1b6f4459670","_type":"span","marks":[],"text":"Government schemes such as PPF and SCSS"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"bffd94b4f680","_type":"block","children":[{"_key":"bffd94b4f6800","_type":"span","marks":[],"text":"Bank Fixed Deposits"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"9e2a66b020e0","_type":"block","children":[{"_key":"9e2a66b020e00","_type":"span","marks":[],"text":"Corporate debentures"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1a197b2f64ed","_type":"block","children":[{"_key":"1a197b2f64ed0","_type":"span","marks":[],"text":"Government Bonds are a good investment for a portion of the investible amount of individuals, where risk-avoidance is a primary condition."}],"markDefs":[],"style":"normal"},{"_key":"775cb18f18b3","_type":"block","children":[{"_key":"775cb18f18b30","_type":"span","marks":[],"text":"The Indian government has made it progressively simpler for individuals to invest through online channels in primary issues, as well as a robust secondary market through trading and demat accounts."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-12T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-22-government-bonds"},"title":"Government Bonds"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-25', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-25","_rev":"s2wDSUpWBbCAmLaTqSKXed","_system":{"base":{"id":"article-25","rev":"gvb15rYHBFgFq42eS6o9sU"}},"_type":"post","_updatedAt":"2026-07-17T14:57:08Z","body":[{"_key":"4b370d34a586","_type":"block","children":[{"_key":"4b370d34a5860","_type":"span","marks":[],"text":"A sum of money placed with a bank for a defined period of time is known as a Fixed Deposit (FD). A Fixed Deposit is easy to use as it can be transacted at any commercial bank. Most people will have at least one banking relationship. For them, an FD has been a first-choice investment as and when they have had money that they could be put away."}],"markDefs":[],"style":"normal"},{"_key":"126848ce1f9e","_type":"block","children":[{"_key":"126848ce1f9e0","_type":"span","marks":[],"text":"Banks have promoted FDs as it provides them greater certainty of funds at a relatively low rate. It is now also possible to open and close FDs through the online service offered by banks which could, earlier, only be done through bank branches."}],"markDefs":[],"style":"normal"},{"_key":"67f4a74bd0f7","_type":"block","children":[{"_key":"67f4a74bd0f70","_type":"span","marks":[],"text":"A bank FD is considered to be a baseline investment in India. Hence, all other investment options can be considered as competition. In any case, a Bank FD competes with Bank FDs offered by all other banks. Anyone (including NRIs, with certain specific conditions) can open an FD with any commercial bank in India."}],"markDefs":[],"style":"normal"},{"_key":"d05a6b6d8a40","_type":"block","children":[{"_key":"d05a6b6d8a400","_type":"span","marks":[],"text":"Interest rate"}],"markDefs":[],"style":"h2"},{"_key":"e849080db39f","_type":"block","children":[{"_key":"e849080db39f0","_type":"span","marks":[],"text":"The rate of interest offered by banks keeps changing with changes in market conditions and their own liquidity needs. That being said, rates offered by most banks are generally aligned at most times."}],"markDefs":[],"style":"normal"},{"_key":"bfe4d0779d2e","_type":"block","children":[{"_key":"bfe4d0779d2e0","_type":"span","marks":[],"text":"FD rates offered by State Bank of India, the nation’s largest bank, in July 2025 are presented below as a sample and can be accessed through "},{"_key":"bfe4d0779d2e1","_type":"span","marks":["62e04f0aeb0b"],"text":"this link"},{"_key":"bfe4d0779d2e2","_type":"span","marks":[],"text":":"}],"markDefs":[{"_key":"62e04f0aeb0b","_type":"link","href":"https://sbi.co.in/web/interest-rates/deposit-rates/retail-domestic-term-deposits"}],"style":"normal"},{"_key":"179662f316f6","_type":"block","children":[{"_key":"179662f316f60","_type":"span","marks":["strong"],"text":"Table: State Bank of India FD interest rates as on 4th June, 2026"}],"markDefs":[],"style":"normal"},{"_key":"4824adccf058","_type":"block","children":[{"_key":"4824adccf0580","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/4b7d0448f6827efc01a6584e5c0bd8e7df00b6cb-772x601.png","_key":"d32127745dcb","_type":"image"},{"_key":"1de60a451ebf","_type":"block","children":[{"_key":"1de60a451ebf0","_type":"span","marks":[],"text":"Most banks offer 0.50% higher interest to senior citizens."}],"markDefs":[],"style":"normal"},{"_key":"fdb1259e33b1","_type":"block","children":[{"_key":"fdb1259e33b10","_type":"span","marks":[],"text":"Risk"}],"markDefs":[],"style":"h2"},{"_key":"6bb9da56c0b7","_type":"block","children":[{"_key":"6bb9da56c0b70","_type":"span","marks":[],"text":"Deposits in all commercial banks (including foreign bank branches in India) and cooperative banks are insured up to ₹ 5 lakh per depositor per bank by the Depositor Insurance and Credit Guarantee Corporation (DICGC)."}],"markDefs":[],"style":"normal"},{"_key":"b842508872fe","_type":"block","children":[{"_key":"b842508872fe0","_type":"span","marks":[],"text":"While there have been failures of private banks and cooperative banks, no scheduled commercial bank has failed in India in the last 50 years."}],"markDefs":[],"style":"normal"},{"_key":"d61fbc7cb366","_type":"block","children":[{"_key":"d61fbc7cb3660","_type":"span","marks":[],"text":"You can learn more about deposit insurance on the "},{"_key":"d61fbc7cb3661","_type":"span","marks":["4c12d713c85b"],"text":"DICGC website"},{"_key":"d61fbc7cb3662","_type":"span","marks":[],"text":" and ensure that your bank is on the covered list before you place a deposit with them."}],"markDefs":[{"_key":"4c12d713c85b","_type":"link","href":"https://www.dicgc.org.in/guide-to-deposit-insurance"}],"style":"normal"},{"_key":"d6b32d2b737c","_type":"block","children":[{"_key":"d6b32d2b737c0","_type":"span","marks":[],"text":"Liquidity"}],"markDefs":[],"style":"h2"},{"_key":"5122a8d8d884","_type":"block","children":[{"_key":"5122a8d8d8840","_type":"span","marks":[],"text":"Fixed Deposits are considered liquid, as they are permitted to be withdrawn prematurely. The general rule followed by most banks is that of a 1% penalty. In other words, the interest paid on premature withdrawal will be 1% lower than the rate applicable for the period for which the FD has run, as offered on the date of placement. In general, as higher rates tend to be offered for longer tenures, premature withdrawal mostly results in a 1% deduction from a rate that islikely to be lower than the contracted rate."}],"markDefs":[],"style":"normal"},{"_key":"36ae28428581","_type":"block","children":[{"_key":"36ae284285810","_type":"span","marks":[],"text":"Some banks link the FD to a savings account. Any shortfall in funds in the savings account is replenished by uplifting a portion of the linked FD. This, in a way, means that the depositor earns FD rates while having the flexibility of withdrawal as per a savings account."}],"markDefs":[],"style":"normal"},{"_key":"b3430453a11e","_type":"block","children":[{"_key":"b3430453a11e0","_type":"span","marks":[],"text":"Pros and Cons"}],"markDefs":[],"style":"h2"},{"_key":"81d5760d3d4a","_type":"block","children":[{"_key":"81d5760d3d4a0","_type":"span","marks":[],"text":"+ Easy to deposit and withdraw"}],"markDefs":[],"style":"normal"},{"_key":"6316625937bb","_type":"block","children":[{"_key":"6316625937bb0","_type":"span","marks":[],"text":"+ Rate is slightly lower than government schemes, but competitive"}],"markDefs":[],"style":"normal"},{"_key":"3553d5367088","_type":"block","children":[{"_key":"3553d53670880","_type":"span","marks":[],"text":"+ No amount limitation; any amount can be deposited"}],"markDefs":[],"style":"normal"},{"_key":"f0640a0b43b7","_type":"block","children":[{"_key":"f0640a0b43b70","_type":"span","marks":[],"text":"~ Income is fully taxable, at the slab rate applicable to the depositor"}],"markDefs":[],"style":"normal"},{"_key":"33f62e1c61f8","_type":"block","children":[{"_key":"33f62e1c61f80","_type":"span","marks":[],"text":"~ Commercial organization risk with insurance only up to ₹5 lacs"}],"markDefs":[],"style":"normal"},{"_key":"8754867bdbe6","_type":"block","children":[{"_key":"8754867bdbe60","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"052abb550be5","_type":"block","children":[{"_key":"052abb550be50","_type":"span","marks":[],"text":"Limit investment to insured limit and check for insurance coverage."}],"markDefs":[],"style":"normal"},{"_key":"80be52bcd7a7","_type":"block","children":[{"_key":"80be52bcd7a70","_type":"span","marks":[],"text":"Bank with established banking organizations or with government-owned banks."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-11T18:30:00.000Z","slug":{"_type":"slug","current":"2023-10-02-bank-fixed-deposits"},"title":"Bank Fixed Deposits"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-2', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-2","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"e4fe707b9d7e","_type":"block","children":[{"_key":"e4fe707b9d7e0","_type":"span","marks":[],"text":"The basic rule in managing a portfolio is to follow the classic advice “Do not put all your eggs in one basket.” Things can go wrong and you do not want to get badly hurt with any particular future outcome. Generally, diversification is one of the few free lunches in investing. By diversifying, you reduce risk and do not reduce expected return."}],"markDefs":[],"style":"normal"},{"_key":"692c4ad1cdb7","_type":"block","children":[{"_key":"692c4ad1cdb70","_type":"span","marks":[],"text":"Recognizing that the future is uncertain, investors need to take investment decisions that take into account the fact that their investments may not turn out the way they thought it would at the time of making the investment. This is applicable even to investors who have an appetite for bearing high levels of risk. You don’t want freak accidents and events wiping out your future."}],"markDefs":[],"style":"normal"},{"_key":"cf71dc6fad59","_type":"block","children":[{"_key":"cf71dc6fad590","_type":"span","marks":[],"text":"You believe you have identified the perfect stock to invest in. You expect it to deliver handsome returns over a long period of time."}],"markDefs":[],"style":"normal"},{"_key":"01bd61d3ae95","_type":"block","children":[{"_key":"01bd61d3ae950","_type":"span","marks":[],"text":"You have a choice. You could invest all your available money into it, or you could invest a part and the remaining in some other stock."}],"markDefs":[],"style":"normal"},{"_key":"21f23a45a8ab","_type":"block","children":[{"_key":"21f23a45a8ab0","_type":"span","marks":[],"text":"By investing all in that one stock you are giving yourself the best chance of a good return. However, you are also exposing yourself to a high level of risk as it is an individual stock exposed to events, circumstances, cycles and other vagaries. By not investing the entire amount in this single stock, you are probably going to earn lower returns, but you are protecting yourself against the risk of a total wipeout in the event of a freak incident derailing that one investment."}],"markDefs":[],"style":"normal"},{"_key":"ae2e7b48cd69","_type":"block","children":[{"_key":"ae2e7b48cd690","_type":"span","marks":[],"text":"Diversification can be done at many levels."}],"markDefs":[],"style":"normal"},{"_key":"ae53a402a21b","_type":"block","children":[{"_key":"ae53a402a21b0","_type":"span","marks":[],"text":"You could invest in the stock of another company in the same industry."}],"markDefs":[],"style":"normal"},{"_key":"3e67812f8074","_type":"block","children":[{"_key":"3e67812f80740","_type":"span","marks":[],"text":"You could invest in the stock of a company in a different industry, giving you additional protection against a freak incident impacting the original industry."}],"markDefs":[],"style":"normal"},{"_key":"5b0a768433e6","_type":"block","children":[{"_key":"5b0a768433e60","_type":"span","marks":[],"text":"You could invest the remaining amount in a mutual fund, gaining greater protection with exposure to a basket and not individual stocks."}],"markDefs":[],"style":"normal"},{"_key":"90ad9af4809f","_type":"block","children":[{"_key":"90ad9af4809f0","_type":"span","marks":[],"text":"You could invest the balance in fixed income securities such as bonds, gaining further protection against the vagaries of a single market, the stock market."}],"markDefs":[],"style":"normal"},{"_key":"ca89061b0401","_type":"block","children":[{"_key":"ca89061b04010","_type":"span","marks":[],"text":"And so on."}],"markDefs":[],"style":"normal"},{"_key":"a9c92f046565","_type":"block","children":[{"_key":"a9c92f0465650","_type":"span","marks":[],"text":"The risk of investing in risk-prone products such as individual stocks can be substantially reduced by investing in a diversified portfolio of individual stocks."}],"markDefs":[],"style":"normal"},{"_key":"5307b247632f","_type":"block","children":[{"_key":"5307b247632f0","_type":"span","marks":[],"text":"If diversification is so important, why do we prefer a single index fund for equity rather than diversifying among a number of funds?"}],"markDefs":[],"style":"normal"},{"_key":"ab4154e9f4b3","_type":"block","children":[{"_key":"ab4154e9f4b30","_type":"span","marks":[],"text":"We suggest that your asset allocation strategy looks to determine the amount of equity risk that is a good match for you and then use the funds to get exposure to the desired level of equity risk."}],"markDefs":[],"style":"normal"},{"_key":"f0b67176b974","_type":"block","children":[{"_key":"f0b67176b9740","_type":"span","marks":[],"text":"A good broad index fund gets you exposure to a diversified basket of stocks. In comparison, while a number of equity funds will give you more diversity than a single fund, they all have exposure to a list of stocks. If you calculate the list of stocks that you have through the many funds, you will come up with a list which is diversified but probably not much more diversified than a single index fund."}],"markDefs":[],"style":"normal"},{"_key":"03f9ecba1b16","_type":"block","children":[{"_key":"03f9ecba1b160","_type":"span","marks":[],"text":"There is often a lot of overlap among different funds and the underlying exposures may get to a similar level of diversity than a single index fund. Our favourite equity index fund where possible is the one that invests in the global stock market and invests in every public company in proportion to the amount of free float market value of the equity outstanding. It is hard to get more diversified equity exposure than this single index fund, no matter how many equity funds you buy. As you buy more funds, the diversification will ensure that your returns before fees get closer to the market. The overall diversification will be worse or equal to the index fund. The costs of active funds are much higher than index funds and in the long run, your after-tax returns are likely to be lower unless the mutual funds outperform as a group. If you are actually picking active funds, it is better to stick to a small list rather than a large number of funds."}],"markDefs":[],"style":"normal"},{"_key":"506727fc4af0","_type":"block","children":[{"_key":"506727fc4af00","_type":"span","marks":[],"text":"There are many articles and resources that talk about diversification. You can learn more about diversification here: "},{"_key":"506727fc4af01","_type":"span","marks":["ebe946552f5d"],"text":"https://www.investopedia.com/investing/importance-diversification/"}],"markDefs":[{"_key":"ebe946552f5d","_type":"link","href":"https://www.investopedia.com/investing/importance-diversification/"}],"style":"normal"}],"publishedAt":"2025-11-28T18:30:00.000Z","slug":{"_type":"slug","current":"2023-04-09-diversification-reduces-risk"},"title":"Diversification reduces risk"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-5', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-5","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"2ed75211d086","_type":"block","children":[{"_key":"2ed75211d0860","_type":"span","marks":[],"text":"Despite the very large number of securities available to investors, it turns out that investment results are dominated by asset allocation more than individual security selection – because individual security impact gets reduced through portfolio effect of diversification."}],"markDefs":[],"style":"normal"},{"_key":"64e800ea284d","_type":"block","children":[{"_key":"64e800ea284d0","_type":"span","marks":[],"text":"Getting the asset allocation to match one’s objectives and risk preferences becomes a very important part of the investment process."}],"markDefs":[],"style":"normal"},{"_key":"f94090d8fd74","_type":"block","children":[{"_key":"f94090d8fd740","_type":"span","marks":[],"text":"What is asset allocation?"}],"markDefs":[],"style":"h2"},{"_key":"f25e42784c13","_type":"block","children":[{"_key":"f25e42784c130","_type":"span","marks":[],"text":"Asset allocation is the process of determining the level of exposure you wish to have to various asset classes. At the highest level, it is a division between exposure to equity and exposure to debt or fixed income investments. This is the level at which we will refer to asset allocation in our articles and recommendations. Of course, one could choose to drill down further and sub-divide each into various sub-classes. One could also bring alternative asset classes into the purview of asset allocation."}],"markDefs":[],"style":"normal"},{"_key":"a366ef9a1ad4","_type":"block","children":[{"_key":"a366ef9a1ad40","_type":"span","marks":[],"text":"The purpose is to ensure that investments are made in an informed manner that lead to meeting your investment goals, and not in a haphazard manner. It enables you to avoid the pitfalls of some asset classes dominating your portfolio and creating concentration risks, as well as investing in a manner that does not lead to your goals."}],"markDefs":[],"style":"normal"},{"_key":"3877a84db184","_type":"block","children":[{"_key":"3877a84db1840","_type":"span","marks":[],"text":"It is generally recommended that you could choose a higher exposure to equity at a young age. It gives you the opportunity of earning higher returns over a long period, and giving you the opportunity of recovering from setbacks in a more volatile equity market as compared to debt. With advancing age, it is recommended to lower the equity exposure and increasing that of debt."}],"markDefs":[],"style":"normal"},{"_key":"c38758cd3621","_type":"block","children":[{"_key":"c38758cd36210","_type":"span","marks":[],"text":"Asset Allocation is primarily a function of age of client and spouse. Recommended Asset Allocation and Existing Asset Allocation results in recommended asset allocation shifts. After asset allocation is determined, pick from ranked investment list till available amounts are filled within each asset category.\\n"}],"markDefs":[],"style":"normal"},{"_key":"1ad99dae3a7d","_type":"block","children":[{"_key":"1ad99dae3a7d0","_type":"span","marks":[],"text":"What is the right asset allocation for you?"}],"markDefs":[],"style":"h2"},{"_key":"6426d3f9845e","_type":"block","children":[{"_key":"6426d3f9845e0","_type":"span","marks":[],"text":"Not easy to answer but there are reasonable starting points."}],"markDefs":[],"style":"normal"},{"_key":"021582e8ec4a","_type":"block","children":[{"_key":"021582e8ec4a0","_type":"span","marks":[],"text":"One way of doing it is to start with the assumption of 100 being your target age, with exposure to equity being 100 – present age. If you are 30, your equity exposure could be 70% of your portfolio. By 70, it should have reduced to 30%."}],"markDefs":[],"style":"normal"},{"_key":"2325aed188f5","_type":"block","children":[{"_key":"2325aed188f50","_type":"span","marks":[],"text":"This should be adjusted based on personal situation and preferences. The table below depicts recommended allocation levels based on variables such as age, professional stability and income and assets:"}],"markDefs":[],"style":"normal"},{"_key":"b1c5e9c04b5d","_type":"table","rows":[{"_key":"la5f3zc","_type":"tableRow","cells":["Variable","Higher","Lower"]},{"_key":"ht0aq6u","_type":"tableRow","cells":["Equity exposure"]},{"_key":"myvtxs7","_type":"tableRow","cells":["Age","L","H"]},{"_key":"rm170yd","_type":"tableRow","cells":["Job/ professional stability","H","L"]},{"_key":"85tt63o","_type":"tableRow","cells":["Income and assets","H","L"]},{"_key":"sfqg29i","_type":"tableRow","cells":["Responsibilities/ dependents","L","H"]},{"_key":"bvoxaqq","_type":"tableRow","cells":["Ability to handle risk and uncertainty","H","L"]}]},{"_key":"9dcd1c6ef873","_type":"block","children":[{"_key":"9dcd1c6ef8730","_type":"span","marks":[],"text":"A sample allocation model based on risk-taking ability:"}],"markDefs":[],"style":"normal"},{"_key":"6621cb2e9f4e","_type":"table","rows":[{"_key":"6dhfzf9","_type":"tableRow","cells":["Risk Level","Equity","Debt"]},{"_key":"umfe6bd","_type":"tableRow","cells":["Aggressive","90%","10%"]},{"_key":"wan4a3m","_type":"tableRow","cells":["Moderate","60%","40%"]},{"_key":"n959std","_type":"tableRow","cells":["Conservative","30%","70%"]}]},{"_key":"c5ec70ead55a","_type":"block","children":[{"_key":"c5ec70ead55a0","_type":"span","marks":[],"text":"What some well-known investment management firms say"}],"markDefs":[],"style":"h2"},{"_key":"aa8537b0b76c","_type":"block","children":[{"_key":"aa8537b0b76c0","_type":"span","marks":[],"text":"But this is just one view."}],"markDefs":[],"style":"normal"},{"_key":"755e8c755970","_type":"block","children":[{"_key":"755e8c7559700","_type":"span","marks":[],"text":"Everyone has a view on asset allocation, and most follow the principle of starting with a high allocation to equity and gradually bringing it down as you age."}],"markDefs":[],"style":"normal"},{"_key":"f02911c01e42","_type":"block","children":[{"_key":"f02911c01e420","_type":"span","marks":[],"text":"You should also look at the allocation recommendations of some of the most established names in investing and retirement planning."}],"markDefs":[],"style":"normal"},{"_key":"481a67eec83c","_type":"block","children":[{"_key":"481a67eec83c0","_type":"span","marks":[],"text":"Here are links to some of their recommendations with regard to asset allocation:"}],"markDefs":[],"style":"normal"},{"_key":"d5910f71c8fa","_type":"block","children":[{"_key":"d5910f71c8fa0","_type":"span","marks":["4eda9e1b247e"],"text":"Vanguard"}],"markDefs":[{"_key":"4eda9e1b247e","_type":"link","href":"https://investor.vanguard.com/investor-resources-education/education/model-portfolio-allocation?msockid=2a850f82837f6961160318e08279682e"}],"style":"normal"},{"_key":"f72db968ae50","_type":"block","children":[{"_key":"f72db968ae500","_type":"span","marks":["31ab3d008745"],"text":"Blackrock"}],"markDefs":[{"_key":"31ab3d008745","_type":"link","href":"https://www.blackrock.com/us/financial-professionals/investments/products/lifepath/lifepath-index-funds"}],"style":"normal"},{"_key":"f3a19240782c","_type":"block","children":[{"_key":"f3a19240782c0","_type":"span","marks":["0abdb000cd34"],"text":"JP Morgan"}],"markDefs":[{"_key":"0abdb000cd34","_type":"link","href":"https://am.jpmorgan.com/us/en/asset-management/adv/investment-strategies/retirement-solutions/target-date-strategies/"}],"style":"normal"},{"_key":"84381d140043","_type":"block","children":[{"_key":"84381d1400430","_type":"span","marks":["47b0bbb964c9"],"text":"Morning Star"}],"markDefs":[{"_key":"47b0bbb964c9","_type":"link","href":"https://www.morningstar.com/funds/target-date-funds-retirement-income-closer-look"}],"style":"normal"},{"_key":"62b6fc82d54d","_type":"block","children":[{"_key":"62b6fc82d54d0","_type":"span","marks":[],"text":"These are all good places to start. One can check out their model portfolios, look at the simple 100- age heuristic and see what may be the best fit given one''s circumstances."}],"markDefs":[],"style":"normal"},{"_key":"654d93818a93","_type":"block","children":[{"_key":"654d93818a930","_type":"span","marks":[],"text":"It is good to think about how one is different from the average and why these providers recommend what they do. This can help you arrive at the best match for one''s circumstances and preferences."}],"markDefs":[],"style":"normal"},{"_key":"f12021e33d59","_type":"block","children":[{"_key":"f12021e33d590","_type":"span","marks":[],"text":"Target date fund"}],"markDefs":[],"style":"h2"},{"_key":"fdaab2a13a2e","_type":"block","children":[{"_key":"fdaab2a13a2e0","_type":"span","marks":[],"text":"A simple solution that could be suitable for many investors is to pick a low-cost target date fund (TDF) that corresponds to one’s retirement horizon."}],"markDefs":[],"style":"normal"},{"_key":"02231c7f5550","_type":"block","children":[{"_key":"02231c7f55500","_type":"span","marks":[],"text":"It is a type of "},{"_key":"02231c7f55501","_type":"span","marks":["strong"],"text":"mutual fund or retirement fund"},{"_key":"02231c7f55502","_type":"span","marks":[],"text":" that seeks to optimize returns with a defined target (future) date in mind which (target date) is also included in its name. To achieve this objective, it automatically adjusts its "},{"_key":"02231c7f55503","_type":"span","marks":["strong"],"text":"asset allocation"},{"_key":"02231c7f55504","_type":"span","marks":[],"text":" based on its target date, typically moving from high-risk equities in its earlier years towards lower-risk debt as the target date approached."}],"markDefs":[],"style":"normal"},{"_key":"feb2d92b30e7","_type":"block","children":[{"_key":"feb2d92b30e70","_type":"span","marks":[],"text":"As an investor, you can choose a fund that is closest to your target or retirement date, and one that has an investment strategy that is aligned with your goals. Thereafter, you will not need to keep rebalancing by shifting from equity to debt as you age, the fund will do it for you."}],"markDefs":[],"style":"normal"},{"_key":"b8c4fb254c33","_type":"block","children":[{"_key":"b8c4fb254c330","_type":"span","marks":[],"text":"This is one of the under-appreciated benefits of modern financial solutions. A simple, easy to understand low-cost solution that will beat most solutions offered and currently used."}],"markDefs":[],"style":"normal"},{"_key":"f71eb4fe57a8","_type":"block","children":[{"_key":"f71eb4fe57a80","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"a4634a5ddcd5","_type":"block","children":[{"_key":"a4634a5ddcd50","_type":"span","marks":[],"text":"No matter how one looks to manage a portfolio, seeing and managing one’s asset allocation is an important decision with long-term impact."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-03-26T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-05-asset-allocation"},"title":"Asset Allocation"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-10', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-10","_rev":"gvb15rYHBFgFq42eS6o9sU","_type":"post","_updatedAt":"2026-07-15T03:33:07Z","body":[{"_key":"674bd526ff25","_type":"block","children":[{"_key":"674bd526ff250","_type":"span","marks":[],"text":"Passive Investing"}],"markDefs":[],"style":"h2"},{"_key":"76b6ca967ea4","_type":"block","children":[{"_key":"76b6ca967ea40","_type":"span","marks":[],"text":"A passive investment strategy is based on the belief that the market is efficient and it is difficult to outperform consistently through active management."}],"markDefs":[],"style":"normal"},{"_key":"ffd5ff231c74","_type":"block","children":[{"_key":"ffd5ff231c740","_type":"span","marks":[],"text":"Instead of trying to beat the market, passive managers try to match the performance of an index by holding all (or a representative sample) of the securities in the index. The most common form of passive investment is through index funds or exchange-traded funds (ETFs)."}],"markDefs":[],"style":"normal"},{"_key":"19ef75bb7d44","_type":"block","children":[{"_key":"19ef75bb7d440","_type":"span","marks":[],"text":"Passive investing generally involves lower costs because of fewer transactions and lower management fees. It’s a long-term strategy and doesn’t aim to profit from short-term market fluctuations."}],"markDefs":[],"style":"normal"},{"_key":"f7b88d5c0731","_type":"block","children":[{"_key":"f7b88d5c07310","_type":"span","marks":[],"text":"Active Investing"}],"markDefs":[],"style":"h2"},{"_key":"d32481f8a2f2","_type":"block","children":[{"_key":"d32481f8a2f20","_type":"span","marks":[],"text":"Active investing involves a hands-on approach and requires a portfolio manager or a team of managers to make decisions about how to invest a fund’s money. The goal of active management is to beat the market average, such as the S&P 500 index, or Nifty 50, and provide investors with a higher return."}],"markDefs":[],"style":"normal"},{"_key":"554916ed4b73","_type":"block","children":[{"_key":"554916ed4b730","_type":"span","marks":[],"text":"Active managers try to do this thorough research and analysis, making forecasts, and using their own judgment to make decisions about what securities to buy, sell, and hold. They may also look to adjust the portfolio in response to market changes or economic trends. This strategy often involves higher transaction costs due to frequent trading and also higher management fees for the expertise provided."}],"markDefs":[],"style":"normal"},{"_key":"9831fb5ae484","_type":"block","children":[{"_key":"9831fb5ae4840","_type":"span","marks":[],"text":"Comparison of Active and Passive Investment Strategies"}],"markDefs":[],"style":"h2"},{"_key":"84dd60fdcca3","_type":"block","children":[{"_key":"84dd60fdcca30","_type":"span","marks":[],"text":"Active Investing is a Zero-Sum game and on average active strategies will underperform the market."}],"markDefs":[],"style":"normal"},{"_key":"0b9d49c6c546","_type":"block","children":[{"_key":"0b9d49c6c5460","_type":"span","marks":[],"text":"Passive strategies will give you market returns. In aggregate, the market will give you market returns. Since the Market Returns = Average Active Returns + Average Passive Returns, it follows that on average, Active Returns also equal market returns less the costs incurred. Therefore, if some active strategies outperform, there must be some other active strategies that underperform."}],"markDefs":[],"style":"normal"},{"_key":"841a117cffbd","_type":"block","children":[{"_key":"841a117cffbd0","_type":"span","marks":[],"text":"Most Active Strategies have historically failed to keep up with their benchmark indices. This is true in the US, India, and other parts of the world."}],"markDefs":[],"style":"normal"},{"_key":"32f9e2a94fba","_type":"block","children":[{"_key":"32f9e2a94fba0","_type":"span","marks":[],"text":"SPIVA Scorecards"}],"markDefs":[],"style":"h3"},{"_key":"297001118b0b","_type":"block","children":[{"_key":"297001118b0b0","_type":"span","marks":[],"text":"S&P Dow Jones Indices is one of the largest providers of investment indices. They have been doing a comparison of the performance of active versus index or passive strategies for the past twenty years called the "},{"_key":"297001118b0b1","_type":"span","marks":["3ba056cd55db"],"text":"S&P Indices versus Active (SPIVA)"},{"_key":"297001118b0b2","_type":"span","marks":[],"text":" scorecards, which are “semi-annual reports published by S&P Dow Jones Indices that compare the performance of active equity and fixed income mutual funds against their benchmarks over different time horizons.”"}],"markDefs":[{"_key":"3ba056cd55db","_type":"link","href":"https://www.spglobal.com/spdji/en/education/article/spiva-scorecards-an-overview"}],"style":"normal"},{"_key":"c2c4ffbdac99","_type":"block","children":[{"_key":"c2c4ffbdac990","_type":"span","marks":[],"text":"Key takeaways as articulated in "},{"_key":"c2c4ffbdac991","_type":"span","marks":["48dc646d36f3"],"text":"Talking Points"},{"_key":"c2c4ffbdac992","_type":"span","marks":[],"text":", a publication of S&P Dow Jones Indices:"}],"markDefs":[{"_key":"48dc646d36f3","_type":"link","href":"https://www.spglobal.com/spdji/en/documents/education/talking-points-assessing-the-impact-of-20-years-of-spiva.pdf"}],"style":"normal"},{"_key":"473ee9c7e5a5","_type":"block","children":[{"_key":"473ee9c7e5a50","_type":"span","marks":[],"text":"Most active managers underperform most of the time."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f2db48ad4936","_type":"block","children":[{"_key":"f2db48ad49360","_type":"span","marks":[],"text":"The tendency for underperformance typically rises as the observation period lengthens. In the US, 79% of active managers underperform against the S&P500 over one year. This goes up to 89% over 5 years and 90% over 15 years."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"585d37040606","_type":"block","children":[{"_key":"585d370406060","_type":"span","marks":[],"text":"These conclusions are robust across geographies. The infographic below demonstrates the consistent and significant underperformance across markets over 5 years."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"911a297b9a93","_type":"block","children":[{"_key":"911a297b9a930","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/bb2f755f529730f2cd6fb9ec5b6fc5898440bd33-1333x841.png","_key":"f96bb8270f79","_type":"image"},{"_key":"9c6ae92c02e4","_type":"block","children":[{"_key":"9c6ae92c02e40","_type":"span","marks":[],"text":"Source: "},{"_key":"9c6ae92c02e41","_type":"span","marks":["286ae61e1a76"],"text":"SPGlobal"}],"markDefs":[{"_key":"286ae61e1a76","_type":"link","href":"https://www.spglobal.com/spdji/en/documents/spiva/spiva-infographic.pdf"}],"style":"normal"},{"_key":"e9d108c162f9","_type":"block","children":[{"_key":"e9d108c162f90","_type":"span","marks":[],"text":"When good performance does occur, it tends not to persist, indicating the presence of “luck” in such outperformance. Above-average past performance does not predict above-average future performance. According to their "},{"_key":"e9d108c162f91","_type":"span","marks":["d1a400e76424"],"text":"persistence scorecard for the US"},{"_key":"e9d108c162f92","_type":"span","marks":[],"text":" which includes data for 2024, “persistence of outperformance was fleeting, with a small fraction of actively managed equity funds able to maintain consistent outperformance relative to their peers over the three- or five-year periods ending in December 2024.” Key findings:"}],"markDefs":[{"_key":"d1a400e76424","_type":"link","href":"https://www.spglobal.com/spdji/en/documents/spiva/persistence-scorecard-year-end-2024.pdf"}],"style":"normal"},{"_key":"bb6de591162c","_type":"block","children":[{"_key":"bb6de591162c0","_type":"span","marks":[],"text":"None of the top-quartile large-cap funds from 2022 maintained their position in the top quartile for the subsequent two years."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"84925be13a85","_type":"block","children":[{"_key":"84925be13a850","_type":"span","marks":[],"text":"Only 9% of the above-median large-cap active equity funds in calendar year 2022 remained above median in each of the two succeeding years. If outperformance were entirely random, we would expect a repeat rate of approximately 25%."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"dd24769b3c07","_type":"block","children":[{"_key":"dd24769b3c070","_type":"span","marks":[],"text":"Alpha persistence was fleeting, with a cross-category average of only 8.3% of active equity funds that surpassed the benchmark in 2022 able to consistently outperform their respective benchmarks over the subsequent two-year period."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f96dc2836cf2","_type":"block","children":[{"_key":"f96dc2836cf20","_type":"span","marks":[],"text":"SPIVA trends in India equities"}],"markDefs":[],"style":"h3"},{"_key":"5783c9ea23e6","_type":"block","children":[{"_key":"5783c9ea23e60","_type":"span","marks":[],"text":"The SPIVA India Scorecard measures the performance of Indian actively managed funds against their respective benchmarks over various time horizons. Highlights for year-end 2025:"}],"markDefs":[],"style":"normal"},{"_key":"6b4fb2ef6a04","_type":"block","children":[{"_key":"6b4fb2ef6a040","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/4fdfe749c4dea32858141a780f3f2100de7f1f64-899x278.png","_key":"d7ca22e5eb53","_type":"image"},{"_key":"f69ee8864249","_type":"block","children":[{"_key":"f69ee88642490","_type":"span","marks":[],"text":"Source: "},{"_key":"f69ee88642491","_type":"span","marks":["c8ce111ee0cc"],"text":"SPGlobal"}],"markDefs":[{"_key":"c8ce111ee0cc","_type":"link","href":"https://www.spglobal.com/spdji/en/spiva/article/spiva-india/"}],"style":"normal"},{"_key":"5eb75909bba3","_type":"block","children":[{"_key":"5eb75909bba30","_type":"span","marks":["strong"],"text":"Indian Equity Large-Cap Funds"},{"_key":"5eb75909bba31","_type":"span","marks":[],"text":" – The underperformance rate hit 75.0% over the 1-year period, compared to 74.2%, 84.4% and 76.3% over the 3-, 5- and 10-year horizons, respectively."}],"markDefs":[],"style":"normal"},{"_key":"ec05a3ac0f16","_type":"block","children":[{"_key":"ec05a3ac0f160","_type":"span","marks":["strong"],"text":"Indian ELSS Funds "},{"_key":"ec05a3ac0f161","_type":"span","marks":[],"text":"– Underperformance rates were 55.0%, 58.5% and 82.9% over the 3-, 5- and 10-year horizons, respectively."}],"markDefs":[],"style":"normal"},{"_key":"4d5e54c94c24","_type":"block","children":[{"_key":"4d5e54c94c240","_type":"span","marks":["strong"],"text":"Indian Equity Mid-/Small-Cap Funds "},{"_key":"4d5e54c94c241","_type":"span","marks":[],"text":"– The underperformance rate was just 12.1% over the 1-year period and reached 41.5%, 46.0% and 79.0% over the 3-, 5- and 10-year horizons, respectively."}],"markDefs":[],"style":"normal"},{"_key":"05ae091cf4ef","_type":"block","children":[{"_key":"05ae091cf4ef0","_type":"span","marks":[],"text":"SEBI Analysis"}],"markDefs":[],"style":"h3"},{"_key":"2f3d8a9311bb","_type":"block","children":[{"_key":"2f3d8a9311bb0","_type":"span","marks":[],"text":"A SEBI initiated study of "},{"_key":"2f3d8a9311bb1","_type":"span","marks":["3b50e9f1e488"],"text":"Profit and Loss of Individual Traders dealing in Equity F&O Segment"},{"_key":"2f3d8a9311bb2","_type":"span","marks":[],"text":" done by the Department of Economic and Policy Analysis to analyse the trading by individual investors between FY 2019 and FY 2022 threw up sobering data as well. The study found that “89% of the individual traders (i.e. 9 out of 10 individual traders) in equity F&O segment incurred losses with an average loss of ₹ 1.1 lakh during FY22, whereas, 90% of the active traders incurred average losses of ₹ 1.25 lakh during the same period.”"}],"markDefs":[{"_key":"3b50e9f1e488","_type":"link","href":"https://www.sebi.gov.in/reports-and-statistics/research/jan-2023/study-analysis-of-profit-and-loss-of-individual-traders-dealing-in-equity-fando-segment_67525.html"}],"style":"normal"},{"_key":"48811e981a29","_type":"block","children":[{"_key":"48811e981a290","_type":"span","marks":[],"text":"Other considerations"}],"markDefs":[],"style":"h2"},{"_key":"9bc1f2d78db1","_type":"block","children":[{"_key":"9bc1f2d78db10","_type":"span","marks":[],"text":"Q. If more people employ passive strategies, will it not become easier for active managers to outperform since passive strategies just follow simple rules to track the market and do not concern themselves with issues such as valuation and investment flows?"}],"markDefs":[],"style":"normal"},{"_key":"554784263ccf","_type":"block","children":[{"_key":"554784263ccf0","_type":"span","marks":[],"text":"A. If the passive strategies truly reflect the market properly, then no. This is because properly constructed passive strategies will reflect market performance. The smaller active share will remain a zero-sum game and every active winner needs to find an active loser."}],"markDefs":[],"style":"normal"},{"_key":"9387c5a34816","_type":"block","children":[{"_key":"9387c5a348160","_type":"span","marks":[],"text":"There are some inefficiencies in the way indices track the market, particularly around rebalancing which creates advantages for sophisticated active managers at the expense of the passive strategies. These however are small in aggregate in relation to the size and return of passive investments."}],"markDefs":[],"style":"normal"},{"_key":"faf62a825efa","_type":"block","children":[{"_key":"faf62a825efa0","_type":"span","marks":[],"text":"Q. Who are the losers in active investment strategies for other active managers to outperform?"}],"markDefs":[],"style":"normal"},{"_key":"5bb8b0baa30a","_type":"block","children":[{"_key":"5bb8b0baa30a0","_type":"span","marks":[],"text":"A. Retail investors have been shown to underperform the markets. They are one natural group that professional active investors may be able to outperform and some successfully do so. However, as a group, professional investors have been underperforming the market, so this is not enough to sustain professional active strategies as a group. A lot of retail participation is through other professional active investors such as mutual funds and remaining retail active underperformance is not enough given its small size to provide for outperformance of professional active investors as a group."}],"markDefs":[],"style":"normal"},{"_key":"dba97ccdfe39","_type":"block","children":[{"_key":"dba97ccdfe390","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"d276b0596ec4","_type":"block","children":[{"_key":"d276b0596ec40","_type":"span","marks":[],"text":"For retail investors, passive investing is recommended. Index investing is a tried and trusted method of passive investing. Read our article on "},{"_key":"d276b0596ec41","_type":"span","marks":["8e39c57411e3"],"text":"Index Investing Strategy"},{"_key":"d276b0596ec42","_type":"span","marks":[],"text":"."}],"markDefs":[{"_key":"8e39c57411e3","_type":"link","href":"/2023/08/11/index-funds/"}],"style":"normal"}],"publishedAt":"2026-03-31T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-10-active-and-passive-investment-management"},"title":"Active and Passive Investment Management"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-12', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-12","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"73ba235ec656","_type":"block","children":[{"_key":"73ba235ec6560","_type":"span","marks":[],"text":"Financial markets are very competitive. There are many smart well-resourced players looking to find undervalued securities to buy and overvalued securities to sell. When people find an undervalued security, they buy it and that takes the price higher and when they find an overvalued security, they sell it taking the price lower. A lot of the players are very large institutions with a lot of resources and there are many of them. With lots of people competing furiously to find the mispriced securities, the result is that securities tend to be reasonably efficiently priced. As a result, it is very hard to beat the market."}],"markDefs":[],"style":"normal"},{"_key":"b56f07952e70","_type":"block","children":[{"_key":"b56f07952e700","_type":"span","marks":[],"text":"Historical evidence in the largest market with the most research on historical outcomes, which is the US market, shows that even most professional investors fail to beat the market after costs and fees. If large well-resourced institutions with teams trying to outperform the market have a hard time being successful, it is reasonable to expect that individuals who have much less time, training and resources are likely to fall short. The evidence shows this to be the case. If one accepts this premise that the very competitive nature of markets makes it hard to beat the “market”, the natural implication is that one should not invest a lot of time and resources in picking stocks, picking mutual funds or timing the market because outperforming on any of these dimensions means that one is winning the competitive game to beat most of the other people playing this game. And that, we know, is extremely difficult."}],"markDefs":[],"style":"normal"},{"_key":"7fb70a232b51","_type":"block","children":[{"_key":"7fb70a232b510","_type":"span","marks":[],"text":"The Evidence"}],"markDefs":[],"style":"h2"},{"_key":"affbc3bede8b","_type":"block","children":[{"_key":"affbc3bede8b0","_type":"span","marks":[],"text":"Most institutional investors fall short of properly constructed benchmarks. Here is the evidence from US public Pension funds that manage billions of dollars with the benefit of large professional teams and the ability to hire almost any professional money manager or invest directly. "},{"_key":"affbc3bede8b1","_type":"span","marks":["540d969f690e"],"text":"An article by Richard M. Ennis"},{"_key":"affbc3bede8b2","_type":"span","marks":[],"text":" examines the cost, performance, and benchmark bias of public pension funds in the United States."}],"markDefs":[{"_key":"540d969f690e","_type":"link","href":"https://papers.ssrn.com/sol3/papers.cfm?abstract_id=3883370"}],"style":"normal"},{"_key":"55e2a6d3af8e","_type":"block","children":[{"_key":"55e2a6d3af8e0","_type":"span","marks":[],"text":"In its Abstract, the study states: “I estimate that statewide pension funds in the United States incur annual investment expenses averaging 1.3% of asset value. A sample of 24 of them underperformed passive investment during the past decade by an average of 1.4% a year. And yet, those same funds report that they outperformed benchmarks of their own devising by an average of +0.3% a year for the same period. This sharp disconnect raises questions about the usefulness of the funds’ performance reporting, as well as their heavy reliance on expensive active management.”"}],"markDefs":[],"style":"normal"},{"_key":"96b03bb0c1bc","_type":"block","children":[{"_key":"96b03bb0c1bc0","_type":"span","marks":[],"text":"Most mutual funds fail to keep up with their benchmark indices. This is true in the US and is true in India."}],"markDefs":[],"style":"normal"},{"_key":"ac174a1bdd05","_type":"block","children":[{"_key":"ac174a1bdd050","_type":"span","marks":[],"text":"Independent investment research firm Dalbar Inc., an independent research firm, publishes an annual "},{"_key":"ac174a1bdd051","_type":"span","marks":["3538d10be8b0"],"text":"Quantitative Analysis of Investor Behavior report"},{"_key":"ac174a1bdd052","_type":"span","marks":[],"text":", or QAIB, for retail investors in the US."}],"markDefs":[{"_key":"3538d10be8b0","_type":"link","href":"https://www.ifa.com/articles/understanding-investor-behavior-portfolio-performance"}],"style":"normal"},{"_key":"d2042fa5b4ad","_type":"block","children":[{"_key":"d2042fa5b4ad0","_type":"span","marks":[],"text":"It consistently shows that people are “more often than not their own worst enemies when it comes to investing, often succumbing to short-term strategies such as market timing or performance chasing.” It concludes that retail investors perform poorly when compared to market benchmarks or index funds tracking the market."}],"markDefs":[],"style":"normal"},{"_key":"3e161563e9d8","_type":"block","children":[{"_key":"3e161563e9d80","_type":"span","marks":[],"text":"More details from the report can be accessed in our article: "},{"_key":"3e161563e9d81","_type":"span","marks":["3b76ef0474db"],"text":"Index investing Strategy"},{"_key":"3e161563e9d82","_type":"span","marks":[],"text":".”"}],"markDefs":[{"_key":"3b76ef0474db","_type":"link","href":"/2023/08/11/index-funds/"}],"style":"normal"},{"_key":"e4b06d6a39d2","_type":"block","children":[{"_key":"e4b06d6a39d20","_type":"span","marks":[],"text":"Individual or Institution – who you are changes investment choices"}],"markDefs":[],"style":"h2"},{"_key":"641d47bfd865","_type":"block","children":[{"_key":"641d47bfd8650","_type":"span","marks":[],"text":"If a stock is seen as a good investment opportunity, it is good for you whether you are an individual or an institutional investor. If it goes up, as forecast, all investors benefit. But there are some differences in investment strategies depending on which of these categories you fall into."}],"markDefs":[],"style":"normal"},{"_key":"6baad97ff314","_type":"block","children":[{"_key":"6baad97ff3140","_type":"span","marks":[],"text":"Institutions have scale and access to resources often much larger than available to individuals. Their scale can justify an investment in research designed to yield superior returns. It is like an investment in a business activity. By doing so, the investing institution acts like an investment firm that invests others’ money."}],"markDefs":[],"style":"normal"},{"_key":"e3bb94ad11d3","_type":"block","children":[{"_key":"e3bb94ad11d30","_type":"span","marks":[],"text":"Most individuals have limited scale. That scale will only yield limited upsides and downsides, regardless of the amount of time and effort invested in research. For an investment pool of, say ₹ 10 lakh, how many stocks or MFs can you really analyse? If the standard return from an index fund is 10%, you will earn ₹ 1 lakh. A 2% improvement over the market will yield ₹ 20,000 more over a year. You have to ask yourself the question, “Is it worth my while trying to unravel investing mysteries on my own, across thousands of stocks, MFs, Bonds, etc. for that gain? What is my cost of doing that research?”"}],"markDefs":[],"style":"normal"},{"_key":"e9df288a7907","_type":"block","children":[{"_key":"e9df288a79070","_type":"span","marks":[],"text":"Individuals should remember that there are many institutions, with access to deep talent pools and resources, with a lot money at stake, trying to do the same thing – generating market-beating returns. They do it as a business. Is it really worth your while trying to outperform the market on your own steam? An institution with a ₹ 100 crore investment pool can hope to generate an extra ₹ 2 crores from the same research, hence might still find it somewhat worthwhile."}],"markDefs":[],"style":"normal"},{"_key":"04204bec7a45","_type":"block","children":[{"_key":"04204bec7a450","_type":"span","marks":[],"text":"On the other hand, individuals have access to a plethora of opportunities that institutions do not. For example, the Indian government offers several savings schemes only for individuals. Strategies for individual investors should almost always look to leverage those opportunities for investors that are better than those available to institutions."}],"markDefs":[],"style":"normal"},{"_key":"43a003c9179a","_type":"block","children":[{"_key":"43a003c9179a0","_type":"span","marks":[],"text":"Implications for individual investors"}],"markDefs":[],"style":"h2"},{"_key":"18712c9c6934","_type":"block","children":[{"_key":"18712c9c69340","_type":"span","marks":[],"text":"Individual investors should not spend a lot of effort in"}],"markDefs":[],"style":"normal"},{"_key":"32961b015718","_type":"block","children":[{"_key":"32961b0157180","_type":"span","marks":[],"text":"Picking individual securities and funds in an effort to outperform the market"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f881004db59d","_type":"block","children":[{"_key":"f881004db59d0","_type":"span","marks":[],"text":"Timing the market in an effort to outperform the average market performance"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"d6c03ef2b826","_type":"block","children":[{"_key":"d6c03ef2b8260","_type":"span","marks":[],"text":"Financial markets are very competitive. There are many smart, well-resourced players looking to find undervalued securities to buy and overvalued securities to sell. When people find an undervalued security, they buy it and that takes the price higher and when they find an overvalued security, they sell it taking the price lower. A lot of the players are very large institutions with a lot of resources and there are many of them. With lots of people competing furiously to find the mispriced securities, the result is that securities tend to be reasonably efficiently priced. As a result, it is very hard to beat the market. The historical evidence in the largest market with the most research on historical outcomes, which is the US market, shows that even most professional investors fail to beat the market after costs and fees. If large well-resourced institutions with teams trying to outperform the market have a hard time being successful, it is reasonable to expect that individuals who have much less time, training and resources are likely to fall short."}],"markDefs":[],"style":"normal"},{"_key":"961ccc63c5a9","_type":"block","children":[{"_key":"961ccc63c5a90","_type":"span","marks":[],"text":"It can be done without thinking. All you need to do is either match the composition of the index in your stock picks or buy a fund that does the same."}],"markDefs":[],"style":"normal"},{"_key":"4717aac10cf8","_type":"block","children":[{"_key":"4717aac10cf80","_type":"span","marks":[],"text":"Another way of looking at it is that a team of experts, who have access to more information than we as individuals will ever have, are taking decisions on the composition of the index. Why don’t we put their combined knowledge and skill to work for our own investments? Especially if our ability to bear risk is limited."}],"markDefs":[],"style":"normal"},{"_key":"400bfcce65a6","_type":"block","children":[{"_key":"400bfcce65a60","_type":"span","marks":[],"text":"Between the Bombay Stock Exchange and the National Stock Exchange, a variety of indices are tracked, with different areas of focus. A variation of the strategy could be to choose one of the other indices and not the primary BSE Sensex."}],"markDefs":[],"style":"normal"},{"_key":"0e1669355f50","_type":"block","children":[{"_key":"0e1669355f500","_type":"span","marks":[],"text":"Of course, it does not mean that the future performance is guaranteed."}],"markDefs":[],"style":"normal"},{"_key":"cafdf0ae7695","_type":"block","children":[{"_key":"cafdf0ae76950","_type":"span","marks":[],"text":"The conclusion"}],"markDefs":[],"style":"h2"},{"_key":"2cff54876272","_type":"block","children":[{"_key":"2cff548762720","_type":"span","marks":[],"text":"If the large institutions are unable to keep up with the market, what should one expect for retail investors as a group?"}],"markDefs":[],"style":"normal"},{"_key":"eaf90d829951","_type":"block","children":[{"_key":"eaf90d8299510","_type":"span","marks":[],"text":"As an individual investor, do not spend time and resources trying to outperform the market by trying to actively pick individual securities like stocks and bonds or even actively managed mutual funds or time the market, hoping to outperform the average market returns. Instead focus on keeping up and not failing behind average market returns."}],"markDefs":[],"style":"normal"},{"_key":"2e9de6cec572","_type":"block","children":[{"_key":"2e9de6cec5720","_type":"span","marks":[],"text":"Index Strategies do this very well and very efficiently at low cost. Make an exception to the above general strategy only when there are specific situations explicitly giving an advantage to individual investors that are not available to large investors and institutions – small government savings schemes and special tax advantages for individual investors."}],"markDefs":[],"style":"normal"},{"_key":"7d0e98d6043e","_type":"block","children":[{"_key":"7d0e98d6043e0","_type":"span","marks":[],"text":"If one thinks that one truly can do better than the average market outcomes, then rather than just adding value to one’s personal investment situation, one should really focus on getting a professional position in the investment management industry. The number of people who outperform the average after costs is truly small as has been pointed out in the evidence above. If you truly can be in this small group, you should be able to add a lot of value to professional investors and get paid very well for those results."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-02T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-10-competitive-financial-markets-and-the-implications-for-investment-strategy"},"title":"Competitive Financial Markets and the implications for investment strategy"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-18', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-18","_rev":"8VyNrOEo8uWkcWBKVY0zwZ","_system":{"base":{"id":"article-18","rev":"gvb15rYHBFgFq42eS6o9sU"}},"_type":"post","_updatedAt":"2026-07-17T14:45:09Z","body":[{"_key":"896f7488a0b6","_type":"block","children":[{"_key":"896f7488a0b60","_type":"span","marks":[],"text":"While the individual investor will have a broad understanding of what a Mutual Fund is, he/ she may not be aware of the range."}],"markDefs":[],"style":"normal"},{"_key":"83fb373ac9b1","_type":"block","children":[{"_key":"83fb373ac9b10","_type":"span","marks":[],"text":"What is a liquid fund?"}],"markDefs":[],"style":"h2"},{"_key":"d08995d48a4c","_type":"block","children":[{"_key":"d08995d48a4c0","_type":"span","marks":[],"text":"A liquid fund or Liquid Mutual Fund, as the name suggests, invests in highly liquid, short tenure instruments in the money market."}],"markDefs":[],"style":"normal"},{"_key":"04d9557148c1","_type":"block","children":[{"_key":"04d9557148c10","_type":"span","marks":[],"text":"Treasury bills, Certificate of Deposits (CDs), term deposits, commercial papers are some examples of the instruments it could invest in. The objective is to optimize returns while maintaining liquidity and security of the money invested. Redemption requests are normally processed within one working day, highlighting their sensitivity to investor liquidity needs."}],"markDefs":[],"style":"normal"},{"_key":"f183b278074d","_type":"block","children":[{"_key":"f183b278074d0","_type":"span","marks":[],"text":"Generating high returns is not the primary goal of these funds, which is generally reserved for equity funds. Liquid funds are categorized under debt funds. They park their funds in liquid investments that have a high credit rating and hence a low probability of default. They focus on disciplined investing, which includes ensuring that expenses are kept low while providing liquidity and capital protection to investors."}],"markDefs":[],"style":"normal"},{"_key":"dba9afb33640","_type":"block","children":[{"_key":"dba9afb336400","_type":"span","marks":[],"text":"Benefits of a liquid fund"}],"markDefs":[],"style":"h2"},{"_key":"38dc20cc6b02","_type":"block","children":[{"_key":"38dc20cc6b020","_type":"span","marks":[],"text":"Liquid funds are known to offer better returns than a regular savings account."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a5dd0bf9e521","_type":"block","children":[{"_key":"a5dd0bf9e5210","_type":"span","marks":[],"text":"They are good for parking surplus money from a few days to a few months, and for keeping your emergency funds in, as they can be released at short notice without having to worry about the present state of the markets."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"2a040eb5a8cb","_type":"block","children":[{"_key":"2a040eb5a8cb0","_type":"span","marks":[],"text":"Liquid funds provide better post-tax returns compared to keeping money in a savings account and is almost as liquid, except for the overnight redemption period."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"9f44aee7e72b","_type":"block","children":[{"_key":"9f44aee7e72b0","_type":"span","marks":[],"text":"The money is invested in a number of securities as per the mandate of the fund, making it a low-risk investment. Money in a bank account is covered along with other deposit accounts by the standard insurance limit of ₹ 5 lakh."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"8bdf2b659e56","_type":"block","children":[{"_key":"8bdf2b659e560","_type":"span","marks":[],"text":"Liquid funds are useful when one needs a parking place for funds while a longer-term decision is being processed. It could be when a large sum has been received, such as sale proceeds of a property, or any other similar sudden inflow."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"747b08aadd31","_type":"block","children":[{"_key":"747b08aadd310","_type":"span","marks":[],"text":"Investors also use liquid funds while they scout for opportunities in equities and are waiting for a dip to invest."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"54174a1f4562","_type":"block","children":[{"_key":"54174a1f45620","_type":"span","marks":[],"text":"Liquid funds can be used for investing in a staggered manner, like an SIP, in an equity fund."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"02b68277beba","_type":"block","children":[{"_key":"02b68277beba0","_type":"span","marks":[],"text":"Liquid funds do not charge an exit load."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"aee6c87c4752","_type":"block","children":[{"_key":"aee6c87c47520","_type":"span","marks":[],"text":"With investments and redemptions going online, it has become progressively easier to invest in them and exit when you deem fit."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"42550d63799b","_type":"block","children":[{"_key":"42550d63799b0","_type":"span","marks":[],"text":"Comparison of returns delivered by liquid funds and savings accounts"}],"markDefs":[],"style":"h2"},{"_key":"6c9786f1f02b","_type":"block","children":[{"_key":"6c9786f1f02b0","_type":"span","marks":[],"text":"One can check out the trailing performance of liquid MFs on "},{"_key":"6c9786f1f02b1","_type":"span","marks":["9d44a177d0ac"],"text":"Moneycontrol.com"},{"_key":"6c9786f1f02b2","_type":"span","marks":[],"text":". A snapshot of the returns delivered by the largest (by AUM) liquid funds is given in the table below:"}],"markDefs":[{"_key":"9d44a177d0ac","_type":"link","href":"https://www.moneycontrol.com/mutual-funds/"}],"style":"normal"},{"_sanityAsset":"image@file://./images/20317fa74fd2bbf29148624cc673003de938f4a8-1577x595.png","_key":"d533d4b1466b","_type":"image"},{"_key":"f44263e98b82","_type":"block","children":[{"_key":"f44263e98b820","_type":"span","marks":[],"text":"Using State Bank of India as the reference point once again, we note that the current interest rate on savings accounts is 2.5% p.a. The maximum rate offered by SBI between 2000 and 2019, as displayed on their "},{"_key":"f44263e98b821","_type":"span","marks":["c9d5ff7cacd4"],"text":"website"},{"_key":"f44263e98b822","_type":"span","marks":[],"text":", was 4% p.a."}],"markDefs":[{"_key":"c9d5ff7cacd4","_type":"link","href":"https://sbi.bank.in/documents/26242/65574/211022-SAV+INT+HIST.pdf/d898ad9a-28b3-b74a-77e9-b0b5d6907bfa?t=1666333463298"}],"style":"normal"},{"_key":"62a40bfbd4b4","_type":"block","children":[{"_key":"62a40bfbd4b40","_type":"span","marks":[],"text":"Thus, liquid MFs are a better option for investors looking for safe returns for a short period of time."}],"markDefs":[],"style":"normal"},{"_key":"9af14273a6a0","_type":"block","children":[{"_key":"9af14273a6a00","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"9c38af3bad0c","_type":"block","children":[{"_key":"9c38af3bad0c0","_type":"span","marks":[],"text":"Move excess funds from a bank savings account into a liquid mutual fund."}],"markDefs":[],"style":"normal"},{"_key":"20ab1fead77f","_type":"block","children":[{"_key":"20ab1fead77f0","_type":"span","marks":[],"text":"Choose a Direct Liquid Fund offered by one out of the following biggest providers – SBI, HDFC, ICICI, UTI and LIC. The benefit in choosing a big fund is that the expenses get absorbed over a larger corpus, reducing the dilution of return for each investor."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-09T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-19-why-keeping-money-in-a-liquid-mutual-fund-is-better-for-short-term-needs-than-keeping-it-in-a-savings-account"},"title":"A liquid mutual fund is better for short-term needs than a bank savings account"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-7', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-7","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"2aeed849b94c","_type":"block","children":[{"_key":"2aeed849b94c0","_type":"span","marks":[],"text":"When are you investing for?"}],"markDefs":[],"style":"normal"},{"_key":"b9157f594409","_type":"block","children":[{"_key":"b9157f5944090","_type":"span","marks":[],"text":"Putting away money for the future is a smart thing to do, but not having it available when you need it, is not."}],"markDefs":[],"style":"normal"},{"_key":"845e5448a4c1","_type":"block","children":[{"_key":"845e5448a4c10","_type":"span","marks":[],"text":"In America, the concept of retirement and saving for retirement gained traction in the 1930s with the introduction of social security. While there is no single retirement age, 65, when social security payments could be encashed, has been considered as that number."}],"markDefs":[],"style":"normal"},{"_key":"c0bb8407b640","_type":"block","children":[{"_key":"c0bb8407b6400","_type":"span","marks":[],"text":"in 1900, the 65+ group had only 3 million members, reflecting a nation with a young population, a mere 4 percent in a population size of 76 million."}],"markDefs":[],"style":"normal"},{"_key":"d682e2aabbde","_type":"block","children":[{"_key":"d682e2aabbde0","_type":"span","marks":[],"text":"Life expectancy crossed 65 in 1944. Therefore, till 1944, the probability of the retired adult enjoying the fruits of his savings was low, since the average person did not live beyond 65."}],"markDefs":[],"style":"normal"},{"_key":"6d54fbcbeef6","_type":"block","children":[{"_key":"6d54fbcbeef60","_type":"span","marks":[],"text":"It crossed 70 in 1964. Even in 1964, only 5 years of post-retirement expenses were needed by most people. Creating a fund over 40 years of working life for a retirement period of 5 years did not create too many cases of distress."}],"markDefs":[],"style":"normal"},{"_key":"db8e8c618bcd","_type":"block","children":[{"_key":"db8e8c618bcd0","_type":"span","marks":[],"text":"However, with rising life expectancy, it is close to 80 now, the requirement has kept increasing, along with which has gone up the need to save a larger part of earnings during working years."}],"markDefs":[],"style":"normal"},{"_key":"c87808c06457","_type":"block","children":[{"_key":"c87808c064570","_type":"span","marks":[],"text":"The same is the situation in India, with rising life expectancy. It is important to be able to project your likely lifespan in order that finances can be handled better. While it is not an exact science, the Actuaries Longevity Illustrator (“ALI”) helps you get an idea."}],"markDefs":[],"style":"normal"},{"_key":"6beb6e8d3025","_type":"block","children":[{"_key":"6beb6e8d30250","_type":"span","marks":[],"text":"You can access it here: "},{"_key":"6beb6e8d30251","_type":"span","marks":["b9fea2aa8faa"],"text":"https://www.longevityillustrator.org/"}],"markDefs":[{"_key":"b9fea2aa8faa","_type":"link","href":"https://www.longevityillustrator.org/"}],"style":"normal"},{"_key":"b05e53b952d0","_type":"block","children":[{"_key":"b05e53b952d00","_type":"span","marks":[],"text":"While life expectancy tables will tell you how long an individual of your age, gender, and health would be anticipated, on average, to live. And therein lies the catch. What you need to plan for is not how long the average person will live but how long YOU will live."}],"markDefs":[],"style":"normal"},{"_key":"e679ac37a486","_type":"block","children":[{"_key":"e679ac37a4860","_type":"span","marks":[],"text":"If you plan for the average and live less than it, you may be adequately funded for old age but may need to live a more penurious life when young than needed. On the other hand, if you plan for the average and live longer, you may run out of money in old age. It is a very personal choice but being aware of the consequences, hopefully, leads to more informed decision-making. There are other considerations as well. For instance, the funding provided may be to cover the old age of two people. In that case, the longevity assessment becomes even more complex."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-03-28T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-07-defining-your-investment-horizon-can-lead-to-better-planning"},"title":"Defining your investment horizon can lead to better planning"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-11', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-11","_rev":"gvb15rYHBFgFq42eS6o9sU","_type":"post","_updatedAt":"2026-07-15T03:33:07Z","body":[{"_key":"7a3334df2dcc","_type":"block","children":[{"_key":"7a3334df2dcc0","_type":"span","marks":[],"text":"This is not a discussion on the merits of investing in mutual funds versus that of investing directly in individual stocks. This discussion is about the benefit of investing in Index Funds over investment in other, more specific or targeted funds."}],"markDefs":[],"style":"normal"},{"_key":"6fd9c461bd4e","_type":"block","children":[{"_key":"6fd9c461bd4e0","_type":"span","marks":[],"text":"An Index Fund is a Mutual Fund that tries to mirror the composition of a stock market index. It is based on the assumption that the requisite due diligence has been done while selecting the stocks that will comprise the index, including the weightage of the stocks, and that further efforts in improving it might only result in marginal games that may not even offset the higher cost of the effort. The major effort is in keeping the fund aligned with the index as they change either the composition or weightage of stocks."}],"markDefs":[],"style":"normal"},{"_key":"76e27c4d860b","_type":"block","children":[{"_key":"76e27c4d860b0","_type":"span","marks":[],"text":"This way, index funds are able to engage in ‘passive’ investing at a lower cost than ‘active’ funds, with the benefits being passed on to, or shared with, their investors. This leads to the fund generating a return that is almost identical to the returns generated by the index."}],"markDefs":[],"style":"normal"},{"_key":"b10c4d2f5f88","_type":"block","children":[{"_key":"b10c4d2f5f880","_type":"span","marks":[],"text":"Performance comparison"}],"markDefs":[],"style":"h2"},{"_key":"106d1533e8ca","_type":"block","children":[{"_key":"106d1533e8ca0","_type":"span","marks":[],"text":"Actively picking securities and funds is a very complex problem and competitive market dynamics have made the rewards to this activity low even for the most sophisticated institutions. Identifying who is going to beat the market is also a very complex exercise. Individuals should stay away from active security selection and finding managers who can beat the markets, and use index funds instead. This simplifies the investment problem by an enormous factor and frees up time and cognitive resources to focus on the factors that can really improve the plan and outcomes."}],"markDefs":[],"style":"normal"},{"_key":"1690e9ddf7ca","_type":"block","children":[{"_key":"1690e9ddf7ca0","_type":"span","marks":[],"text":"There is evidence that retail investors underperform the market."}],"markDefs":[],"style":"normal"},{"_key":"18514ecbc262","_type":"block","children":[{"_key":"18514ecbc2620","_type":"span","marks":[],"text":"DALBAR Study"}],"markDefs":[],"style":"h3"},{"_key":"a304df935071","_type":"block","children":[{"_key":"a304df9350710","_type":"span","marks":[],"text":"Independent investment research firm Dalbar Inc., an independent research firm, publishes an annual Quantitative Analysis of Investor Behavior report, or QAIB, for retail investors in the US. The study consistently shows that people are “more often than not their own worst enemies when it comes to investing, often succumbing to short-term strategies such as market timing or performance chasing.”"}],"markDefs":[],"style":"normal"},{"_key":"35fa8f711e2f","_type":"block","children":[{"_key":"35fa8f711e2f0","_type":"span","marks":[],"text":"A "},{"_key":"35fa8f711e2f1","_type":"span","marks":["ca335fe8ade1"],"text":"summary of its findings"},{"_key":"35fa8f711e2f2","_type":"span","marks":[],"text":" published by Dalbar reveals that “the Average Equity Investor earned just 16.54% in 2024, compared to the S&P 500’s 25.02% return. The 848 basis point lag represents the second-largest investor performance gap of the past decade.”"}],"markDefs":[{"_key":"ca335fe8ade1","_type":"link","href":"https://www.dalbar.com/PressReleases/doc/2025QAIBPressRelease.pdf"}],"style":"normal"},{"_key":"6db0aca1bc07","_type":"block","children":[{"_key":"6db0aca1bc070","_type":"span","marks":[],"text":"Index Fund Advisors (IFA) provide a peek into the study through a bar chart which shows “the difference in performance as well as the growth of $100,000 between the average equity investor and the S&P 500 Index for the past 20 years (through 2024). It also compares the average annualized return of such an initial investment to the rate of inflation and a short-term bond index over that same period.”"}],"markDefs":[],"style":"normal"},{"_key":"222df1fabf09","_type":"block","children":[{"_key":"222df1fabf090","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/e07f09fa873eec489c63fd7afb7b0adc4f8dd360-937x601.png","_key":"24ee571b0516","_type":"image"},{"_key":"a9c3c650c1f3","_type":"block","children":[{"_key":"a9c3c650c1f30","_type":"span","marks":[],"text":"Source: "},{"_key":"a9c3c650c1f31","_type":"span","marks":["c06cc8d165a9"],"text":"Index Fund Advisors (IFA)"}],"markDefs":[{"_key":"c06cc8d165a9","_type":"link","href":"https://www.ifa.com/articles/understanding-investor-behavior-portfolio-performance"}],"style":"normal"},{"_key":"23bffd89e664","_type":"block","children":[{"_key":"23bffd89e6640","_type":"span","marks":[],"text":"The bottom line: retail investors perform poorly when compared to market benchmarks or index funds tracking the market. A simple strategy of investing in the S&P 500 Index would have yielded better results."}],"markDefs":[],"style":"normal"},{"_key":"f16902804fca","_type":"block","children":[{"_key":"f16902804fca0","_type":"span","marks":[],"text":"BSE Sensex"}],"markDefs":[],"style":"h3"},{"_key":"19e970481e07","_type":"block","children":[{"_key":"19e970481e070","_type":"span","marks":[],"text":"The BSE Sensex is the benchmark index of the Bombay Stock Exchange, Asia’s oldest bourse. It is made up of 30 of the most actively traded and financially sound stocks and serves as a reflection of the economy. The composition is reviewed every 6 months."}],"markDefs":[],"style":"normal"},{"_key":"d4c500a45fe8","_type":"block","children":[{"_key":"d4c500a45fe80","_type":"span","marks":[],"text":"Since its base date of 1 April 1979, the BSE Sensex has compounded at approximately 15–16% annually, generating an increase of more than 800 times over about 47 years. The CAGR will be higher if dividends were to be included."}],"markDefs":[],"style":"normal"},{"_key":"50ab3e9f685f","_type":"block","children":[{"_key":"50ab3e9f685f0","_type":"span","marks":[],"text":"On January 1, 2026, the Sensex completed 40 years as the benchmark index. Over its four decades of existence, the index has generated a CAGR of 13.4%."}],"markDefs":[],"style":"normal"},{"_key":"ecfcc4a3bb44","_type":"block","children":[{"_key":"ecfcc4a3bb440","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/a2957d6d19b92c064eff3cef2d728ca14e0ca574-931x509.png","_key":"11fc46b25544","_type":"image"},{"_key":"fb0beff89e17","_type":"block","children":[{"_key":"fb0beff89e170","_type":"span","marks":[],"text":"Source: "},{"_key":"fb0beff89e171","_type":"span","marks":["4e8f4ccddc21"],"text":"Fortune India"}],"markDefs":[{"_key":"4e8f4ccddc21","_type":"link","href":"https://www.fortuneindia.com/business-news/sensex40-13-return-generated-every-year-from-1986-to-2025/129137"}],"style":"normal"},{"_key":"e9494209b191","_type":"block","children":[{"_key":"e9494209b1910","_type":"span","marks":[],"text":"This is better than one would have earned on most forms of financial investments such as bank deposits, corporate deposits and bonds in the same period."}],"markDefs":[],"style":"normal"},{"_key":"49b69c58daeb","_type":"block","children":[{"_key":"49b69c58daeb0","_type":"span","marks":[],"text":"Benefits of investing in index funds"}],"markDefs":[],"style":"h2"},{"_key":"78a5b5bd7a66","_type":"block","children":[{"_key":"78a5b5bd7a660","_type":"span","marks":[],"text":"There are several benefits for individuals."}],"markDefs":[],"style":"normal"},{"_key":"4fbcb9ab5d2f","_type":"block","children":[{"_key":"4fbcb9ab5d2f0","_type":"span","marks":[],"text":"Portfolio selected by experts"}],"markDefs":[],"style":"h3"},{"_key":"40d4ca227081","_type":"block","children":[{"_key":"40d4ca2270810","_type":"span","marks":[],"text":"The goal of every fund is to deliver the best returns, within the flexibility allowed by its mandate. Much of the effort of fund managers is towards research in the target securities, for the same purpose, delivering the best returns."}],"markDefs":[],"style":"normal"},{"_key":"304b6553792c","_type":"block","children":[{"_key":"304b6553792c0","_type":"span","marks":[],"text":"With an index fund, the portfolio comes pre-selected, that too by a team of experts appointed by the exchange to determine the composition of its index, or the different indices that it might be monitoring. Whether it is the BSE Sensex, the NSE Nifty50 or any other index, the composition is a process that involves scientific techniques, including back-testing."}],"markDefs":[],"style":"normal"},{"_key":"afed4e5eb670","_type":"block","children":[{"_key":"afed4e5eb6700","_type":"span","marks":[],"text":"The investor can either mirror the chosen index through stock selection on his/ her own, or simply invest the money with a mutual fund that does the same. In both cases, the return will closely mirror the return delivered by the stocks in the index. Doing it individually will deliver a marginally better return, but with the added effort, and possibly cost, of tracking and making changes from time to time."}],"markDefs":[],"style":"normal"},{"_key":"40420f0fd1b7","_type":"block","children":[{"_key":"40420f0fd1b70","_type":"span","marks":[],"text":"Lower cost"}],"markDefs":[],"style":"h3"},{"_key":"ad7f49dfae22","_type":"block","children":[{"_key":"ad7f49dfae220","_type":"span","marks":[],"text":"On account if its nature as a ‘passive’ investment, fund managers do not have to invest much time or effort in researching. This lower cost translates into higher returns for investors."}],"markDefs":[],"style":"normal"},{"_key":"af99043cbeaa","_type":"block","children":[{"_key":"af99043cbeaa0","_type":"span","marks":[],"text":"The following comparison between two funds of the same company, one index based and the other equity growth based, illustrates:"}],"markDefs":[],"style":"normal"},{"_key":"39767a48e3b4","_type":"table","rows":[{"_key":"o02fm6h","_type":"tableRow","cells":["Fund Name","Expense Ratio"]},{"_key":"r8yv288","_type":"tableRow","cells":["SBI Nifty Index Fund Direct Growth","0.18%"]},{"_key":"g871r5o","_type":"tableRow","cells":["SBI Long Term Equity Fund Direct Growth","1.07%"]},{"_key":"2aflf76","_type":"tableRow","cells":["HDFC Nifty 100 Index Fund Direct Growth","0.30%"]},{"_key":"b16e78t","_type":"tableRow","cells":["HDFC Large and Midcap Fund Direct Growth","1.06%"]},{"_key":"jziywyj","_type":"tableRow","cells":["",""]}]},{"_key":"721807f38c70","_type":"block","children":[{"_key":"721807f38c700","_type":"span","marks":[],"text":"Diversification"}],"markDefs":[],"style":"h3"},{"_key":"b5aeb453c3de","_type":"block","children":[{"_key":"b5aeb453c3de0","_type":"span","marks":[],"text":"Diversification is an integral strategy in most investing decisions. Investment in an index fund provides the benefit of natural diversification as the index is made up of a variety of assets depending on the index being tracked. Thus, the risk associated with individual stocks is neutralized by the mere act of investing in an index fund."}],"markDefs":[],"style":"normal"},{"_key":"c386cbe6b3bc","_type":"block","children":[{"_key":"c386cbe6b3bc0","_type":"span","marks":[],"text":"It must be remembered, however, that the risk mitigation is at the level of the index which the fund tracks. If you invest in a fund that tracks the banking index, cross-industry exposure will not be covered."}],"markDefs":[],"style":"normal"},{"_key":"80fe519c4963","_type":"block","children":[{"_key":"80fe519c49630","_type":"span","marks":[],"text":"Good returns"}],"markDefs":[],"style":"h3"},{"_key":"0b94cde702a0","_type":"block","children":[{"_key":"0b94cde702a00","_type":"span","marks":[],"text":"Finally, the proof of the pudding is in the eating. In other words, how do index funds compare with other types of mutual funds in terms of returns on the money invested."}],"markDefs":[],"style":"normal"},{"_key":"715f8e0433a9","_type":"block","children":[{"_key":"715f8e0433a90","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"080e4482b7a5","_type":"block","children":[{"_key":"080e4482b7a50","_type":"span","marks":[],"text":"Index investing is the approach recommended for individual investors. They can invest directly in stocks based on the index composition and keep on adjusting with changes in the index or their own portfolio composition over time. Alternatively, they can follow the strategy by investing in index funds."}],"markDefs":[],"style":"normal"},{"_key":"f202e0e76faf","_type":"block","children":[{"_key":"f202e0e76faf0","_type":"span","marks":[],"text":"Index funds are the recommended approach for individual investors. Sector-agnostic investors could opt for the overall index funds such as the BSE 100 or Nifty 50, while those who have a preference for some specific type of asset could choose a fund tracking that asset or industry, say banking, or consumer goods."}],"markDefs":[],"style":"normal"},{"_key":"78b7a99d763d","_type":"block","children":[{"_key":"78b7a99d763d0","_type":"span","marks":[],"text":"Index funds investment is not a completely passive investment. You would need to choose one among the many types of index-based funds which itself becomes an active choice. The fund needs to be active in ensuring that liquidity requirements are met while maximising returns."}],"markDefs":[],"style":"normal"},{"_key":"143579271b0f","_type":"block","children":[{"_key":"143579271b0f0","_type":"span","marks":[],"text":"There is often a tracking lag; the delay with which a fund responds to changes in the index composition. Though funds tracking the same index should deliver the same returns over a period of time, this delay could cause some variation in returns."}],"markDefs":[],"style":"normal"},{"_key":"b810d737ec33","_type":"block","children":[{"_key":"b810d737ec330","_type":"span","marks":[],"text":"As is the case in any investing, while they minimise the risk for an investor, index funds are not risk-free. They are exposed to the broad industry movements. For example, in case of an economic downturn when economic activity decreases and all stock stake a beating, index-based funds will also reflect the same behaviour."}],"markDefs":[],"style":"normal"},{"_key":"e915a656f396","_type":"block","children":[{"_key":"e915a656f3960","_type":"span","marks":[],"text":"Index funds carry tax implications in line with equity-funds. Dividends are included in the taxable income of the investor while income earned at the time of selling the fund is subject to capital gains tax based on the period of holding."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-01T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-11-index-funds"},"title":"Index Investing Strategy"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-16', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-16","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"f5a53b58a3fc","_type":"block","children":[{"_key":"f5a53b58a3fc0","_type":"span","marks":[],"text":"“Nothing is certain but death and taxes” goes the proverb."}],"markDefs":[],"style":"normal"},{"_key":"4cac026284e0","_type":"block","children":[{"_key":"4cac026284e00","_type":"span","marks":[],"text":"Investments are no exception. In most cases the returns earned on investments are treated as income of the investor and taxed one way or another. Hence, the correct way of evaluating returns from an investment is after accounting for taxation. It is not what one earns that matters, but what one gets to keep after taxes."}],"markDefs":[],"style":"normal"},{"_key":"4e4509bd5cb6","_type":"block","children":[{"_key":"4e4509bd5cb60","_type":"span","marks":[],"text":"You may have earned a 10% return, but if you need to pay 30% taxes on the return, what you are left with is only a 7% return, after taking out 30% of 10 which is 3. Holding on to and maximizing gains requires being tax aware."}],"markDefs":[],"style":"normal"},{"_key":"e5f7f9ed8877","_type":"block","children":[{"_key":"e5f7f9ed88770","_type":"span","marks":[],"text":"Tax implications based on type of earning"}],"markDefs":[],"style":"h2"},{"_key":"6e685a5c4ff1","_type":"block","children":[{"_key":"6e685a5c4ff10","_type":"span","marks":[],"text":"Interest income – could be added to your income and taxed at the slab rate applicable"}],"markDefs":[],"style":"normal"},{"_key":"f0b94cc34039","_type":"block","children":[{"_key":"f0b94cc340390","_type":"span","marks":[],"text":"Dividends income – currently added to income and taxed at the slab rate applicable. A few years back it was taxed in the hands of the company declaring the dividend with no additional tax liability on shareholders."}],"markDefs":[],"style":"normal"},{"_key":"76576f62fe33","_type":"block","children":[{"_key":"76576f62fe330","_type":"span","marks":[],"text":"Capital gains – such as from shares and mutual funds attract short-term or long-term capital gains tax, based on the holding period"}],"markDefs":[],"style":"normal"},{"_key":"a559ae75f8a0","_type":"block","children":[{"_key":"a559ae75f8a00","_type":"span","marks":[],"text":"Taxability of different investment instruments"}],"markDefs":[],"style":"h2"},{"_key":"d3634207fff3","_type":"table","rows":[{"_key":"7q14z3w","_type":"tableRow","cells":["Instrument","Tax Treatment"]},{"_key":"ue3531s","_type":"tableRow","cells":["Fixed Deposits","Interest taxed at slab rate"]},{"_key":"gexq3y4","_type":"tableRow","cells":["Equity Mutual Funds","STCG: 15%; LTCG: 10% above ₹1 lakh/year"]},{"_key":"wwq2ste","_type":"tableRow","cells":["Debt Mutual Funds","STCG: slab rate; LTCG: 20% with indexation (till 2023 changes)"]},{"_key":"2efwo05","_type":"tableRow","cells":["PPF","Tax-free"]},{"_key":"kiciqwm","_type":"tableRow","cells":["NPS","Partial withdrawal tax-free; annuity taxed"]},{"_key":"iv4ki5v","_type":"tableRow","cells":["ULIPs","Tax-free under Section 10(10D) if premium conditions met"]}]},{"_key":"79507306b5da","_type":"block","children":[{"_key":"79507306b5da0","_type":"span","marks":[],"text":"The above are tax implications based on income earned. In addition, certain investments are allowed as deduction from income at the time the investment is made, lowering the income due for income tax, lowering the tax liability. This is mostly the case with what is known as the “old” tax regime. The new tax regime has tried to reduce/ remove the various allowable deductions in order to simplify the tax code."}],"markDefs":[],"style":"normal"},{"_key":"1bb3fdcd8668","_type":"block","children":[{"_key":"1bb3fdcd86680","_type":"span","marks":[],"text":"Factoring taxes into investment decisions"}],"markDefs":[],"style":"h2"},{"_key":"5e21cbb31832","_type":"block","children":[{"_key":"5e21cbb318320","_type":"span","marks":[],"text":"It enables you to"}],"markDefs":[],"style":"h3"},{"_key":"f3f909c8cc04","_type":"block","children":[{"_key":"f3f909c8cc040","_type":"span","marks":[],"text":"Compare returns accurately – For example, if you are in the 30% tax slab, a tax-free bond offering a 6% return is better than a taxable bond with a return of 7.5%."}],"markDefs":[],"style":"normal"},{"_key":"51401eab406d","_type":"block","children":[{"_key":"51401eab406d0","_type":"span","marks":[],"text":"Optimize asset location in the family – For example, instruments offering a deduction for investing through the Section 80C route could be purchased by the family member in a higher tax bracket while the lower tax-bracket could purchase other instruments that do not offer this benefit but are needed for meeting allocation and investment goals."}],"markDefs":[],"style":"normal"},{"_key":"d5db717f62d6","_type":"block","children":[{"_key":"d5db717f62d60","_type":"span","marks":[],"text":"Choose the right Instrument – For example, if you are open to taking equity risk, which is recommended especially at younger ages, you may find that the tax benefits offered by the ELSS mutual funds outweigh the returns from a fixed deposit in a bank."}],"markDefs":[],"style":"normal"},{"_key":"4e08bb1ffa8d","_type":"block","children":[{"_key":"4e08bb1ffa8d0","_type":"span","marks":[],"text":"Quick and simple strategies"}],"markDefs":[],"style":"h3"},{"_key":"54d9069742fc","_type":"block","children":[{"_key":"54d9069742fc0","_type":"span","marks":[],"text":"PPF, NPS and ELSS are some readily available instruments that provide tax benefits and also enable you to get exposure to equity or debt, based on your allocation and goals."}],"markDefs":[],"style":"normal"},{"_key":"f1bffbbbabfc","_type":"block","children":[{"_key":"f1bffbbbabfc0","_type":"span","marks":[],"text":"Capital losses can be used to offset gains in equity portfolios."}],"markDefs":[],"style":"normal"},{"_key":"95ccb629237a","_type":"block","children":[{"_key":"95ccb629237a0","_type":"span","marks":[],"text":"Individuals in higher tax slabs should avoid withdrawals from equity schemes in which the slab rate will be applied on gains. Capital gains taxation rate is lower than the income tax rate in the higher slabs."}],"markDefs":[],"style":"normal"},{"_key":"0661c1cb0b0f","_type":"block","children":[{"_key":"0661c1cb0b0f0","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"4cc0c5da81da","_type":"block","children":[{"_key":"4cc0c5da81da0","_type":"span","marks":[],"text":"When people think about investing, they often focus on returns, risk, or diversification. But there’s one factor that significantly impacts your overall wealth and is frequently overlooked: taxes. The difference between a good investment and a great one can come down to how much tax you pay on your gains. Taxes are real, you cannot wish them away. By incorporating taxes into your planning process, you are ensuring greater accuracy in planning and giving yourself a better chance of meeting your investment goals."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-07T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-17-taxes-and-investment-outcomes"},"title":"Taxes and their impact on investment outcomes"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-17', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-17","_rev":"gvb15rYHBFgFq42eS6o9sU","_type":"post","_updatedAt":"2026-07-15T03:33:07Z","body":[{"_key":"382edaeb5421","_type":"block","children":[{"_key":"382edaeb54210","_type":"span","marks":[],"text":"We know that a mutual fund is a pooled investment account that is managed through professional fund managers for the purpose of earning better returns than what individuals may be able to earn on their own. There can be various investment targets for mutual funds depending on their investment objectives. One MF may be focused on the banking sector while another’s goal might be to invest in the technology sector."}],"markDefs":[],"style":"normal"},{"_key":"7015e6627735","_type":"block","children":[{"_key":"7015e66277350","_type":"span","marks":[],"text":"Investing in an MF"}],"markDefs":[],"style":"h2"},{"_key":"32ee0e012627","_type":"block","children":[{"_key":"32ee0e0126270","_type":"span","marks":[],"text":"Every mutual fund scheme can be invested in directly through the fund house, or through a mutual fund distributor, such as your bank, who is an intermediary."}],"markDefs":[],"style":"normal"},{"_key":"d3d3b43a200c","_type":"block","children":[{"_key":"d3d3b43a200c0","_type":"span","marks":[],"text":"Many investors buy regular mutual funds which are sold through financial intermediaries such as banks. The expense ratio of these funds includes the fees and commissions paid out to these intermediaries for promoting the product. The intermediary provides suggestions to an investor and allows him to choose from a basket of funds that they sell. The investment and disinvestment process is also handled by them."}],"markDefs":[],"style":"normal"},{"_key":"6768f0975839","_type":"block","children":[{"_key":"6768f09758390","_type":"span","marks":[],"text":"The other type of mutual fund investment is a direct investment. This investment is done directly with the fund house once an investor has decided upon the fund he wishes to invest in. He needs to evaluate the various options on his own and may not have an intermediary for guidance."}],"markDefs":[],"style":"normal"},{"_key":"060583001c1b","_type":"block","children":[{"_key":"060583001c1b0","_type":"span","marks":[],"text":"How do you invest directly?"}],"markDefs":[],"style":"normal"},{"_key":"91bb09e87d82","_type":"block","children":[{"_key":"91bb09e87d820","_type":"span","marks":[],"text":"You need to invest through the website of the MF or through branch offices if they have them. Going through a bank or another distributor will get you a regular MF."}],"markDefs":[],"style":"normal"},{"_key":"7a9066fcc85c","_type":"block","children":[{"_key":"7a9066fcc85c0","_type":"span","marks":[],"text":"How will you know whether your MF is direct or regular?"}],"markDefs":[],"style":"h2"},{"_key":"68fa9104191b","_type":"block","children":[{"_key":"68fa9104191b0","_type":"span","marks":[],"text":"Direct funds say so in the name. In your statement, the word ‘Direct’ should be a part of the name of the MF scheme. if they don’t say anything, they are regular which sounds good but really means High Fee Class."}],"markDefs":[],"style":"normal"},{"_key":"8bf1b4bfe00b","_type":"block","children":[{"_key":"8bf1b4bfe00b0","_type":"span","marks":[],"text":"Another way to check is the ‘Advisor’ field on the statement. Direct MFs will display ARN followed by a number."}],"markDefs":[],"style":"normal"},{"_key":"05b7032301b5","_type":"block","children":[{"_key":"05b7032301b50","_type":"span","marks":[],"text":"The difference between the two"}],"markDefs":[],"style":"h2"},{"_key":"8849f8cb825e","_type":"block","children":[{"_key":"8849f8cb825e0","_type":"span","marks":[],"text":"The difference between the two types of investments arises on account of the total expense ratio (TER) which is loaded on to the fund. It is higher in case of a regular fund, since there is an added component of intermediary fees to pay out, thereby reducing the returns available to the investor. Through the principle of compounding, over time, the difference expands. The TER difference between the two will vary based on the type of fund. Expenses for equity funds are higher, as is the difference."}],"markDefs":[],"style":"normal"},{"_key":"aa1ac5457fee","_type":"block","children":[{"_key":"aa1ac5457fee0","_type":"span","marks":[],"text":"On account of a lower cost structure, direct MFs are able to pass on a greater share of the earnings back to the investor. Over a long period of time, this difference compounds into a large margin."}],"markDefs":[],"style":"normal"},{"_key":"dbe0a9347d85","_type":"block","children":[{"_key":"dbe0a9347d850","_type":"span","marks":[],"text":"It must be kept in mind that the intermediaries provide services to investors such as advice and statements, KYC completion from time to time which may be of use to some investors and they may not mind bearing the extra cost."}],"markDefs":[],"style":"normal"},{"_key":"aafc7d299539","_type":"block","children":[{"_key":"aafc7d2995390","_type":"span","marks":[],"text":"To illustrate, the following two tables have been drawn from the Morningstar MF screening tool on the 8th of July, 2025. SBI, one of the largest MF companies in India, reports performance measures for the Direct as well as Regular versions of the same fund."}],"markDefs":[],"style":"normal"},{"_key":"f8de470d9a26","_type":"block","children":[{"_key":"f8de470d9a260","_type":"span","marks":[],"text":"From the first table we can see that the TER is much higher for the Regular MF when compared to its Direct counterpart."}],"markDefs":[],"style":"normal"},{"_key":"60aa9c68107b","_type":"block","children":[{"_key":"60aa9c68107b0","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/e0ef19a721dcae6b23c0dcc12664656ac47e278e-1280x720.png","_key":"ba2bcd682c5f","_type":"image"},{"_key":"20e88cf5dac9","_type":"block","children":[{"_key":"20e88cf5dac90","_type":"span","marks":[],"text":"The annual return delivered by the Regular MF is lower than its Direct counterpart, as shown in the second table."}],"markDefs":[],"style":"normal"},{"_key":"e4353109a81a","_type":"block","children":[{"_key":"e4353109a81a0","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/b11bd2a3b2078b5eccff48092ecae1e30eb93c80-1280x720.png","_key":"eb5eb0a15771","_type":"image"},{"_key":"843c7509b7c2","_type":"block","children":[{"_key":"843c7509b7c20","_type":"span","marks":[],"text":"You could check this out for yourself by comparing the Direct and Regular versions of the same MF for other MF companies."}],"markDefs":[],"style":"normal"},{"_key":"925d046cdbc2","_type":"block","children":[{"_key":"925d046cdbc20","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"f148646f996d","_type":"block","children":[{"_key":"f148646f996d0","_type":"span","marks":[],"text":"If you are invested in regular MFs, make the move to direct MFs today. Your returns will improve as a result. However, please evaluate the implications prior to initiating the move as a move from a regular to a direct MF is likely to qualify as a sale transaction followed by a purchase transaction and attract applicable capital gains tax and other provisions."}],"markDefs":[],"style":"normal"},{"_key":"842d38f22ad3","_type":"block","children":[{"_key":"842d38f22ad30","_type":"span","marks":[],"text":"In addition, some services like advice that you were receiving from the distributor will not be available. You will also need to complete the investment related formalities yourself. The focus of MFs is on generating returns, not so much on customer service. However, they will send you account statements if you are a direct investor."}],"markDefs":[],"style":"normal"},{"_key":"3ee0a7598178","_type":"block","children":[{"_key":"3ee0a75981780","_type":"span","marks":[],"text":"Once you have decided on the type of fund you wish to invest in, look for channels to invest in it as a direct investment."}],"markDefs":[],"style":"normal"},{"_key":"181b08ad5901","_type":"block","children":[{"_key":"181b08ad59010","_type":"span","marks":[],"text":"The following are the website of the some of the largest public sector Mutual Funds for easy reference:"}],"markDefs":[],"style":"normal"},{"_key":"77ef49fb5a11","_type":"block","children":[{"_key":"77ef49fb5a110","_type":"span","marks":["585efbf03d1b"],"text":"https://www.sbimf.com/"},{"_key":"77ef49fb5a111","_type":"span","marks":[],"text":"\\n"},{"_key":"77ef49fb5a112","_type":"span","marks":["ea0b1a29827e"],"text":"https://www.utimf.com/"},{"_key":"77ef49fb5a113","_type":"span","marks":[],"text":"\\n"},{"_key":"77ef49fb5a114","_type":"span","marks":["03011734d8ba"],"text":"https://www.licmf.com/"}],"markDefs":[{"_key":"585efbf03d1b","_type":"link","href":"https://www.sbimf.com/"},{"_key":"ea0b1a29827e","_type":"link","href":"https://www.utimf.com/"},{"_key":"03011734d8ba","_type":"link","href":"https://www.licmf.com/"}],"style":"normal"}],"publishedAt":"2026-04-08T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-18-when-investing-in-a-mutual-fund-choose-a-direct-mf-over-a-regular-mf"},"title":"When investing in a Mutual Fund, choose a Direct MF over a Regular MF"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-24', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-24","_rev":"s2wDSUpWBbCAmLaTqSL7vQ","_system":{"base":{"id":"article-24","rev":"VvoTrv03okwDAu5fbFlP0Y"}},"_type":"post","_updatedAt":"2026-07-17T15:03:43Z","body":[{"_key":"5798a6e02138","_type":"block","children":[{"_key":"5798a6e021380","_type":"span","marks":[],"text":"The "},{"_key":"5798a6e021381","_type":"span","marks":["6f4c759aa6a7"],"text":"Public Provident Fund (PPF)"},{"_key":"5798a6e021382","_type":"span","marks":[],"text":" scheme is a savings scheme conceptualised by the National Savings Institute and offered by the government of India. It provides handsome returns along with tax benefits. However, the new income tax code which seeks to simplify the process, has done away with some of the benefits available on account of investing in specified schemes. Hence, please ascertain the tax implications prior to investing."}],"markDefs":[{"_key":"6f4c759aa6a7","_type":"link","href":"https://www.nsiindia.gov.in/(S(xjuqoye35n3toge4eca1snuu))/InternalPage.aspx?Id_Pk=169"}],"style":"normal"},{"_key":"8f48f7adadce","_type":"block","children":[{"_key":"8f48f7adadce0","_type":"span","marks":[],"text":"The rate of interest is subject to change quarterly; however, the change generally happens annually. Accounts can be opened with the Post Office as well as with public sector and designated private banks."}],"markDefs":[],"style":"normal"},{"_key":"b826512a9a63","_type":"block","children":[{"_key":"b826512a9a630","_type":"span","marks":[],"text":"While pension funds create regular income after retirement, provident funds yield a lumpsum amount at or around the time of retirement. Non-organized workers, including small business owners, do not have access to any organized form of getting such a lumpsum amount except for their own savings."}],"markDefs":[],"style":"normal"},{"_key":"081627b62e4e","_type":"block","children":[{"_key":"081627b62e4e0","_type":"span","marks":[],"text":"The PPF scheme creates a high-yield and tax-efficient scheme where small savings can be accumulated over a period of time and which can provide the account holder with a lumpsum value at a later date."}],"markDefs":[],"style":"normal"},{"_key":"7e0cf4590f37","_type":"block","children":[{"_key":"7e0cf4590f370","_type":"span","marks":[],"text":"Benefits"}],"markDefs":[],"style":"h2"},{"_key":"1990c6854091","_type":"block","children":[{"_key":"1990c68540910","_type":"span","marks":[],"text":"Attractive rate of interest"}],"markDefs":[],"style":"h3"},{"_key":"7588d7ed2c4b","_type":"block","children":[{"_key":"7588d7ed2c4b0","_type":"span","marks":[],"text":"The PPF account offers a handsome rate of interest which is determined every year by the Ministry of Finance – Department of Economic Affairs, along with the rates for all the other National Small Savings Schemes. Since April 2020, the rate of interest has remained unchanged at 7.1%."}],"markDefs":[],"style":"normal"},{"_key":"a95f0f0d9a2b","_type":"block","children":[{"_key":"a95f0f0d9a2b0","_type":"span","marks":[],"text":"Historically, the rate on PPF accounts has been 25 basis points, or more, higher than the yield on Government bonds of similar maturity, with a variety of factors taken into account by the government while determining the rate."}],"markDefs":[],"style":"normal"},{"_key":"317695ed2ba8","_type":"block","children":[{"_key":"317695ed2ba80","_type":"span","marks":["d06ec0e6b4ea"],"text":"Historical rates"},{"_key":"317695ed2ba81","_type":"span","marks":[],"text":" for the past 10 years:"}],"markDefs":[{"_key":"d06ec0e6b4ea","_type":"link","href":"https://www.nsiindia.gov.in/(S(z4mehubxfteorbvg1rm0r0qn))/InternalPage.aspx?Id_Pk=132"}],"style":"normal"},{"_key":"378bb396b347","_type":"table","rows":[{"_key":"ochpo3y","_type":"tableRow","cells":["From","To","Interest Rate"]},{"_key":"f22zv4k","_type":"tableRow","cells":["1 Apr 2013","31 Mar 2016","8.70"]},{"_key":"xavmv9r","_type":"tableRow","cells":["1 Apr 2016","30 Sep 2016","8.10"]},{"_key":"6vl4uj6","_type":"tableRow","cells":["1 Oct 2016","31 Mar 2017","8.00"]},{"_key":"57ojxnj","_type":"tableRow","cells":["1 Apr 2017","30 Jun 2017","7.90"]},{"_key":"be8kb64","_type":"tableRow","cells":["1 Jul 2017","31 Dec 2017","7.80"]},{"_key":"f2gocwe","_type":"tableRow","cells":["1 Jan 2018","30 Sep 2018","7.60"]},{"_key":"t5llf6j","_type":"tableRow","cells":["1 Oct 2018","30 Jun 2019","8.00"]},{"_key":"xk3fd5o","_type":"tableRow","cells":["1 Jun 2019","31 Mar 2020","7.90"]},{"_key":"wwi7s5x","_type":"tableRow","cells":["1 Apr 2020","30 Jun 2026","7.10"]}]},{"_key":"131283615694","_type":"block","children":[{"_key":"1312836156940","_type":"span","marks":[],"text":"PPF rates have, at almost every point in time in the last 10 years, been higher than the highest rates offered on Fixed Deposits by government banks."}],"markDefs":[],"style":"normal"},{"_key":"9763f57a45cc","_type":"block","children":[{"_key":"9763f57a45cc0","_type":"span","marks":[],"text":"It must, however, be noted that the interest applicable is evaluated and declared every quarter by the Ministry of Finance, as is also done for a number of other savings schemes. The declared rate is applicable to the entire balance in the account."}],"markDefs":[],"style":"normal"},{"_key":"5f3c7e85c39a","_type":"block","children":[{"_key":"5f3c7e85c39a0","_type":"span","marks":[],"text":"Tax benefits"}],"markDefs":[],"style":"h3"},{"_key":"104612cf2fea","_type":"block","children":[{"_key":"104612cf2fea0","_type":"span","marks":[],"text":"Deposits into the account qualify for deduction under Sec.80-C of IT Act, a part of the overall ceiling of ₹ 1,50,000. However, the updated IT code, adopted by most filers, does away with this benefit."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"da969362f01e","_type":"block","children":[{"_key":"da969362f01e0","_type":"span","marks":[],"text":"Interest earned on the account is free from Income Tax under Section -10 of the IT Act."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"3aac242bad96","_type":"block","children":[{"_key":"3aac242bad960","_type":"span","marks":[],"text":"Withdrawals from the account are free from any taxation liability."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"4e885de01acc","_type":"block","children":[{"_key":"4e885de01acc0","_type":"span","marks":[],"text":"These make the PPF account extremely tax efficient, and superior to fixed deposits in banks and most other government schemes."}],"markDefs":[],"style":"normal"},{"_key":"446a4b90fc84","_type":"block","children":[{"_key":"446a4b90fc840","_type":"span","marks":[],"text":"Free from attachment"}],"markDefs":[],"style":"h3"},{"_key":"93f09e7ad00f","_type":"block","children":[{"_key":"93f09e7ad00f0","_type":"span","marks":[],"text":"The amount in a PPF account cannot be attached under any court decree or law, making it highly secure for the account holder."}],"markDefs":[],"style":"normal"},{"_key":"04501c08521f","_type":"block","children":[{"_key":"04501c08521f0","_type":"span","marks":[],"text":"Features"}],"markDefs":[],"style":"h2"},{"_key":"fa13ef6e3d5b","_type":"block","children":[{"_key":"fa13ef6e3d5b0","_type":"span","marks":[],"text":"An account can be opened for a minimum value of ₹ 500-. The maximum that can be deposited during a financial year in an account is ₹ 1,50,000-. If, perchance, more does get deposited, it will not earn any interest."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"efcae2ff9b6a","_type":"block","children":[{"_key":"efcae2ff9b6a0","_type":"span","marks":[],"text":"It can only be opened by resident Indian individuals."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"52bf9e1a1d50","_type":"block","children":[{"_key":"52bf9e1a1d500","_type":"span","marks":[],"text":"Interest is calculated on a monthly basis on the minimum balance between the 5th and last day of the month and paid at the end of the year."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5efed760d0f6","_type":"block","children":[{"_key":"5efed760d0f60","_type":"span","marks":[],"text":"A minimum deposit needs to be made every year the account is live."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"87edf0ab3d42","_type":"block","children":[{"_key":"87edf0ab3d420","_type":"span","marks":[],"text":"Loans can be taken against the account from the 3rd year onwards up to the 6th year. From the 6th year, partial withdrawals can be made."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"7f4eecbbade1","_type":"block","children":[{"_key":"7f4eecbbade10","_type":"span","marks":[],"text":"The account can be maintained for a period of 15 years. On maturity after 15 years, it can continue to be extended in blocks of 5 years at a time, for any number of such blocks."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"7d848eb96ce3","_type":"block","children":[{"_key":"7d848eb96ce30","_type":"span","marks":[],"text":"Account holders also have the option of retaining the account after maturity without further transactions, but earning interest on the balance held at maturity, at prevailing rates."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"2a2986089e2c","_type":"block","children":[{"_key":"2a2986089e2c0","_type":"span","marks":[],"text":"Premature closure of the account is possible 5 years after opening, in certain situations such as treatment of life-threatening conditions, higher education and change in residency status. In the event of such a premature closure, the rate of interest will be 1% lower than the rate at which interest credits have been given."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"60f44aa14077","_type":"block","children":[{"_key":"60f44aa140770","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"3ec4aeaffb86","_type":"block","children":[{"_key":"3ec4aeaffb860","_type":"span","marks":[],"text":"Should be subscribed by everyone who is eligible."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-05-22T18:30:00.000Z","slug":{"_type":"slug","current":"2023-10-01-public-provident-fund"},"title":"Public Provident Fund"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-19', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-19","_rev":"gvb15rYHBFgFq42eS6o9sU","_type":"post","_updatedAt":"2026-07-15T03:33:07Z","body":[{"_key":"9010c3b3094c","_type":"block","children":[{"_key":"9010c3b3094c0","_type":"span","marks":[],"text":"The "},{"_key":"9010c3b3094c1","_type":"span","marks":["f6ccd2f766e0"],"text":"National Pension System (NPS)"},{"_key":"9010c3b3094c2","_type":"span","marks":[],"text":" is a pension cum investment scheme launched by the Government of India to provide old age security to citizens of India. The scheme is regulated by the Pension Fund Regulatory and Development Authority (PFRDA). It is a good option for non-organized workers, including small business owners, who do not have access to any organized form of pension through an employer."}],"markDefs":[{"_key":"f6ccd2f766e0","_type":"link","href":"https://npstrust.org.in/"}],"style":"normal"},{"_key":"2d8be84ba65a","_type":"block","children":[{"_key":"2d8be84ba65a0","_type":"span","marks":[],"text":"It is open to all residents, as well as NRIs (with some restrictions) and seeks to provide market-based returns over the period of investment and an annuity from the time the investment period ends. It is a "},{"_key":"2d8be84ba65a1","_type":"span","marks":["730af3cb1539"],"text":"low-cost scheme"},{"_key":"2d8be84ba65a2","_type":"span","marks":[],"text":" that limits the management fee that can be charged by the chosen fund, based on its AUM."}],"markDefs":[{"_key":"730af3cb1539","_type":"link","href":"https://npstrust.org.in/charges-under-nps"}],"style":"normal"},{"_key":"c1a432f87e9a","_type":"block","children":[{"_key":"c1a432f87e9a0","_type":"span","marks":[],"text":"The primary account is called the Tier I account. An optional, and related, Tier II account, also known as an investment account, can also be opened, with some differences."}],"markDefs":[],"style":"normal"},{"_key":"4925b56e20a8","_type":"table","rows":[{"_key":"lhgf1n0","_type":"tableRow","cells":["","Tier 1","Tier 2"]},{"_key":"ouhb6y9","_type":"tableRow","cells":["Mandatory","Yes","No"]},{"_key":"jwk9r0b","_type":"tableRow","cells":["Contribution","Minimum amount per contribution - ₹ 500 Minimum contribution per Financial Year - ₹ 1,000 Minimum number of contributions in a Financial Year – one","Minimum amount per contribution - ₹ 250 Not mandatory to contribute every year"]},{"_key":"l2z3jp3","_type":"tableRow","cells":["Withdrawal","Restricted to death and reaching retirement age","Flexible withdrawal"]}]},{"_key":"6a3dd9489c7e","_type":"block","children":[{"_key":"6a3dd9489c7e0","_type":"span","marks":[],"text":"Further:\\n– There is no additional cost for maintaining a Tier II account\\n– Tier II amounts can be invested in the same manner as Tier I\\n– Tier II can only be maintained along with a Tier I account"}],"markDefs":[],"style":"normal"},{"_key":"082b91ed383c","_type":"block","children":[{"_key":"082b91ed383c0","_type":"span","marks":[],"text":"Investment and Exit are the two distinct parts of the scheme."}],"markDefs":[],"style":"normal"},{"_key":"91c9903ead42","_type":"block","children":[{"_key":"91c9903ead420","_type":"span","marks":[],"text":"Investment"}],"markDefs":[],"style":"h2"},{"_key":"7d7ca9d78956","_type":"block","children":[{"_key":"7d7ca9d789560","_type":"span","marks":[],"text":"Individual savings are pooled in to a pension fund which are invested by PFRDA regulated professional fund managers as per the approved investment guidelines in diversified portfolios comprising Government Bonds, Bills, Corporate Debentures and Shares. These contributions would grow and accumulate over the years, depending on the returns earned on the investment made. Investors can choose the investment scheme and also switch from one manager to another."}],"markDefs":[],"style":"normal"},{"_key":"2cc8774559e8","_type":"block","children":[{"_key":"2cc8774559e80","_type":"span","marks":[],"text":"Pension Fund Manager (PFM) under NPS:"}],"markDefs":[],"style":"h3"},{"_key":"05211f9658a6","_type":"block","children":[{"_key":"05211f9658a60","_type":"span","marks":[],"text":"Subscriber is mandatorily required to choose one PFM from the available PFMs:"}],"markDefs":[],"style":"normal"},{"_key":"e48b1b25bf74","_type":"block","children":[{"_key":"e48b1b25bf740","_type":"span","marks":[],"text":"Aditya Birla Sunlife Pension Management Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"4a76c572552b","_type":"block","children":[{"_key":"4a76c572552b0","_type":"span","marks":[],"text":"Axis Pension Fund Management Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"2804709b0f41","_type":"block","children":[{"_key":"2804709b0f410","_type":"span","marks":[],"text":"HDFC Pension Management Company Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"9d0826741121","_type":"block","children":[{"_key":"9d08267411210","_type":"span","marks":[],"text":"ICICI Prudential Pension Funds Management Company Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"aaf44e4eabb9","_type":"block","children":[{"_key":"aaf44e4eabb90","_type":"span","marks":[],"text":"Kotak Mahindra Pension Fund Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"fff2c050ee23","_type":"block","children":[{"_key":"fff2c050ee230","_type":"span","marks":[],"text":"LIC Pension Fund Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"3063eda91be1","_type":"block","children":[{"_key":"3063eda91be10","_type":"span","marks":[],"text":"SBI Pension Funds Private Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"99d87dacca63","_type":"block","children":[{"_key":"99d87dacca630","_type":"span","marks":[],"text":"Tata Pension Fund Management Pvt. Ltd."}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"65bc10357835","_type":"block","children":[{"_key":"65bc103578350","_type":"span","marks":[],"text":"UTI Retirement Solutions Limited"}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"a1b82bc464ac","_type":"block","children":[{"_key":"a1b82bc464ac0","_type":"span","marks":[],"text":"DSP Fund Managers Pvt. Ltd."}],"level":1,"listItem":"number","markDefs":[],"style":"normal"},{"_key":"51b362149fbc","_type":"block","children":[{"_key":"51b362149fbc0","_type":"span","marks":[],"text":"This list is as in June 2026 and can be changed by the NPS Trust."}],"markDefs":[],"style":"normal"},{"_key":"959a4886c4e1","_type":"block","children":[{"_key":"959a4886c4e10","_type":"span","marks":[],"text":"The contribution remitted in Subscriber’s account is passed on to the PFMs as selected by the Subscriber at the time of registration (or changed subsequently). The PFMs invest the money and declare Net Asset Value (NAV) at the end of each business day. Accordingly, based on the NAV, units are credited in the Subscriber’s account. The present value of the investment is arrived at by multiplying the units held with the NAV."}],"markDefs":[],"style":"normal"},{"_key":"af9b6d0e6847","_type":"block","children":[{"_key":"af9b6d0e68470","_type":"span","marks":[],"text":"The return under NPS is market driven. Hence, there is no guaranteed/defined amount of return. The returns generated through investments are accumulated for the pension corpus and are not distributed by way of dividend or bonus."}],"markDefs":[],"style":"normal"},{"_key":"d259fc6cfc11","_type":"block","children":[{"_key":"d259fc6cfc110","_type":"span","marks":[],"text":"Investment Options"}],"markDefs":[],"style":"h3"},{"_key":"3b3628980a3e","_type":"block","children":[{"_key":"3b3628980a3e0","_type":"span","marks":[],"text":"Investors can choose where funds are invested or opt for the Auto choice, under which funds are automatically allocated amongst asset classes in a pre-defined matrix, based on the age of the subscriber."}],"markDefs":[],"style":"normal"},{"_key":"4b024e4074d4","_type":"block","children":[{"_key":"4b024e4074d40","_type":"span","marks":[],"text":"Asset Classes"}],"markDefs":[],"style":"h4"},{"_key":"66614ed00991","_type":"block","children":[{"_key":"66614ed009910","_type":"span","marks":[],"text":"Investors can choose the asset classes where their funds will be invested and the fund manager to whom they entrust their funds will allocate them in that proportion. These options are:"}],"markDefs":[],"style":"normal"},{"_key":"27b8ef25f00e","_type":"block","children":[{"_key":"27b8ef25f00e0","_type":"span","marks":[],"text":"Equity – Asset Class E"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5aa3d65b5286","_type":"block","children":[{"_key":"5aa3d65b52860","_type":"span","marks":[],"text":"Corporate Debt – Asset Class C"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"856154c85218","_type":"block","children":[{"_key":"856154c852180","_type":"span","marks":[],"text":"Government Securities – Asset Class G"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"e6f3568a4fed","_type":"block","children":[{"_key":"e6f3568a4fed0","_type":"span","marks":[],"text":"Alternative Investment Funds or AIF – Asset Class A"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a02689647cee","_type":"block","children":[{"_key":"a02689647cee0","_type":"span","marks":[],"text":"The following conditions apply:"}],"markDefs":[],"style":"normal"},{"_key":"72e58254e92a","_type":"block","children":[{"_key":"72e58254e92a0","_type":"span","marks":[],"text":"Subscriber can select multiple Asset Class under a single PFM"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"662675f52188","_type":"block","children":[{"_key":"662675f521880","_type":"span","marks":[],"text":"Upto 50 years of age, the maximum permitted Equity Investment is 75% of the total asset allocation."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"262b6f5d154b","_type":"block","children":[{"_key":"262b6f5d154b0","_type":"span","marks":[],"text":"From 51 years and above, maximum permitted Equity Investment will be as per an equity allocation matrix that reduces with age, going to 50% for 60 years and above."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"aea257edf9a0","_type":"block","children":[{"_key":"aea257edf9a00","_type":"span","marks":[],"text":"Percentage contribution value cannot exceed 5% for Alternative Investment Funds."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"c3ac04770d41","_type":"block","children":[{"_key":"c3ac04770d410","_type":"span","marks":[],"text":"The total allocation across E, C, G and A asset classes must be equal to 100%."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"6562e292d699","_type":"block","children":[{"_key":"6562e292d6990","_type":"span","marks":[],"text":"Choices available"}],"markDefs":[],"style":"h4"},{"_key":"ad2b22cf1494","_type":"block","children":[{"_key":"ad2b22cf14940","_type":"span","marks":[],"text":"Investors can allocate their funds in the following ways:"}],"markDefs":[],"style":"normal"},{"_key":"048d3940bc4d","_type":"block","children":[{"_key":"048d3940bc4d0","_type":"span","marks":[],"text":"Active choice"}],"markDefs":[],"style":"h5"},{"_key":"a52621c087a3","_type":"block","children":[{"_key":"a52621c087a30","_type":"span","marks":[],"text":"Unlike traditional investment products, NPS offers you with the flexibility to design your own portfolio. Depending on your risk appetite, you can design your portfolio by allocating Funds amongst available four asset classes."}],"markDefs":[],"style":"normal"},{"_key":"9ad241452cf2","_type":"block","children":[{"_key":"9ad241452cf20","_type":"span","marks":[],"text":"Auto Choice"}],"markDefs":[],"style":"h5"},{"_key":"43f5f140d75a","_type":"block","children":[{"_key":"43f5f140d75a0","_type":"span","marks":[],"text":"At times designing your portfolio can be a little delicate and time consuming. NPS gives you the flexibility to opt for a dynamic and automatic allocation of your portfolio in case you do not want to exercise an Active choice. This option is called the Auto choice."}],"markDefs":[],"style":"normal"},{"_key":"a3cdff726147","_type":"block","children":[{"_key":"a3cdff7261470","_type":"span","marks":[],"text":"In Auto choice, your money will be invested in asset classes E, C and G in defined proportions based on your age. As individual’s age increases, exposure to Equity and Corporate Debt is gradually reduced and that in Government Securities is increased. Depending upon the risk appetite of subscriber, there are three different options available within Auto Choice-Aggressive, Moderate and Conservative."}],"markDefs":[],"style":"normal"},{"_key":"d0162a7abe60","_type":"block","children":[{"_key":"d0162a7abe600","_type":"span","marks":[],"text":"Aggressive (LC-75) – Maximum Equity exposure is 75% up to the age of 35\\nModerate (LC-50) – Maximum Equity exposure is 50% up to the age of 35\\nConservative (LC – 25) – Maximum Equity exposure is 25% up to the age of 35"}],"markDefs":[],"style":"normal"},{"_key":"1db5ee0d8fc3","_type":"block","children":[{"_key":"1db5ee0d8fc30","_type":"span","marks":[],"text":"Performance history"}],"markDefs":[],"style":"h3"},{"_key":"11a51ec1d72b","_type":"block","children":[{"_key":"11a51ec1d72b0","_type":"span","marks":[],"text":"10-year trailing returns (% p.a.) delivered by various Pension Fund Managers for the E (Equity) Scheme over a 10-year period ending on 11th July, 2025, as published by the, are shown below:"}],"markDefs":[],"style":"normal"},{"_key":"982fd61f7567","_type":"block","children":[{"_key":"982fd61f75670","_type":"span","marks":[],"text":""}],"markDefs":[],"style":"normal"},{"_sanityAsset":"image@file://./images/894ff1bf02ba62078c10f97cf761ce0be7f31572-1603x493.png","_key":"2ba71bf1fc60","_type":"image"},{"_key":"7455253a756a","_type":"block","children":[{"_key":"7455253a756a0","_type":"span","marks":[],"text":"The scheme has added a few more providers during this period who have yet to complete 10 years."}],"markDefs":[],"style":"normal"},{"_key":"b8a0e5193ea8","_type":"block","children":[{"_key":"b8a0e5193ea80","_type":"span","marks":[],"text":"Trailing 7-year returns from the NPS Trust website under the 4 fund options offered by NPS are also summarized below:"}],"markDefs":[],"style":"normal"},{"_key":"25e86c687f99","_type":"table","rows":[{"_key":"25n9bd1","_type":"tableRow","cells":["Scheme -->","E","C","G","A"]},{"_key":"fst1f9y","_type":"tableRow","cells":["HDFC Pension Fund Management Ltd.","14.80%","8.98%","8.60%","9.46%"]},{"_key":"8w49z63","_type":"tableRow","cells":["ICICI Pru. Pension Fund Mgmt Co. Ltd.","15.03%","8.62%","8.54%","8.37%"]},{"_key":"7y9oqos","_type":"tableRow","cells":["Kotak Mahindra Pension Fund Ltd.","15.39%","8.06%","8.58%","8.22%"]},{"_key":"k5giqb8","_type":"tableRow","cells":["LIC Pension Fund Ltd.","14.35%","8.62%","9.18%","8.20%"]},{"_key":"qdpg81d","_type":"tableRow","cells":["SBI Pension Funds Pvt. Ltd","13.12%","8.68%","8.67%","9.89%"]},{"_key":"e52brz0","_type":"tableRow","cells":["UTI Pension Fund Ltd.","14.80%","8.32%","8.40%","7.89%"]},{"_key":"nowkep2","_type":"tableRow","cells":["Benchmark","15.18%","8.96%","8.78%","NA"]}]},{"_key":"a94720dba331","_type":"block","children":[{"_key":"a94720dba3310","_type":"span","marks":[],"text":"Risk"}],"markDefs":[],"style":"h3"},{"_key":"21a5c9a6325e","_type":"block","children":[{"_key":"21a5c9a6325e0","_type":"span","marks":[],"text":"The investment can be considered as a very-low-risk investment as it is offered by a government agency, which equates to sovereign risk. However, certain asset classes such as equity could result in sub-optimal outcomes as they are market dependent and not committed returns."}],"markDefs":[],"style":"normal"},{"_key":"df2d68c03312","_type":"block","children":[{"_key":"df2d68c033120","_type":"span","marks":[],"text":"Exit"}],"markDefs":[],"style":"h3"},{"_key":"165d49238003","_type":"block","children":[{"_key":"165d492380030","_type":"span","marks":[],"text":"On retirement or exit from the scheme, the Corpus is made available to the subscriber with\\nthe mandate that some portion of the Corpus must be invested in an annuity to provide a\\nmonthly pension post-retirement or exit from the scheme. At least 40% of Tier I balance\\nshould be so invested. The balance can be withdrawn as a lump sum without tax implication.\\nIt can also be invested in the annuity purchase along with the mandatory 40%."}],"markDefs":[],"style":"normal"},{"_key":"fed7d6df98b1","_type":"block","children":[{"_key":"fed7d6df98b10","_type":"span","marks":[],"text":"Tier II balance can be fully withdrawn. It can also be transferred to Tier I account at any point\\nduring the currency of the account or at the time of exit, without incurring any exit load."}],"markDefs":[],"style":"normal"},{"_key":"3998bb8667de","_type":"block","children":[{"_key":"3998bb8667de0","_type":"span","marks":[],"text":"Annuity purchase"}],"markDefs":[],"style":"h3"},{"_key":"4c6ba0d62a3a","_type":"block","children":[{"_key":"4c6ba0d62a3a0","_type":"span","marks":[],"text":"Annuity purchase at the time of exit can be done out of a set of choices offered by the PFMs.\\nOnce purchased, providers cannot be changed once the free look-in period is over. Annuity\\nreturns can vary from one provider to another. The choices available:"}],"markDefs":[],"style":"normal"},{"_key":"87e5bd57c619","_type":"block","children":[{"_key":"87e5bd57c6190","_type":"span","marks":[],"text":"Annuity for Life with Return of Purchase Price"}],"markDefs":[],"style":"h4"},{"_key":"85d0fc40f978","_type":"block","children":[{"_key":"85d0fc40f9780","_type":"span","marks":[],"text":"Subscriber will get annuity for life time and on death of the Subscriber, payment of annuity\\nceases & 100% of the purchase price will be returned to the nominee(s)."}],"markDefs":[],"style":"normal"},{"_key":"89f2c880416d","_type":"block","children":[{"_key":"89f2c880416d0","_type":"span","marks":[],"text":"Annuity for Life without Return of Purchase Price"}],"markDefs":[],"style":"h4"},{"_key":"fde88be4d180","_type":"block","children":[{"_key":"fde88be4d1800","_type":"span","marks":[],"text":"Subscriber will get annuity for life time and on death of the Subscriber, payment of annuity\\nceases and no further amount will be payable."}],"markDefs":[],"style":"normal"},{"_key":"c4c94e181315","_type":"block","children":[{"_key":"c4c94e1813150","_type":"span","marks":[],"text":"Joint Life Annuity with Return of Purchase Price"}],"markDefs":[],"style":"h4"},{"_key":"e9040deda4f8","_type":"block","children":[{"_key":"e9040deda4f80","_type":"span","marks":[],"text":"Subscriber will get annuity for life time and on death of the Subscriber, annuity will be\\npayable to Spouse for life time. On death of the Spouse, payment of annuity ceases and\\n100% of the purchase price will be returned to the nominee(s)."}],"markDefs":[],"style":"normal"},{"_key":"d1340de8a9be","_type":"block","children":[{"_key":"d1340de8a9be0","_type":"span","marks":[],"text":"Joint Life Annuity without Return of Purchase Price"}],"markDefs":[],"style":"h4"},{"_key":"a484582183a4","_type":"block","children":[{"_key":"a484582183a40","_type":"span","marks":[],"text":"Subscriber will get annuity for life time and on death of the Subscriber, annuity will be\\npayable to Spouse for life time. On death of the Spouse, payment of annuity ceases and no\\nfurther amount will be payable."}],"markDefs":[],"style":"normal"},{"_key":"e1ec87f1bb24","_type":"block","children":[{"_key":"e1ec87f1bb240","_type":"span","marks":[],"text":"Family Income Option with Return of Purchase Price"}],"markDefs":[],"style":"h4"},{"_key":"204801e0c097","_type":"block","children":[{"_key":"204801e0c0970","_type":"span","marks":[],"text":"Subscriber will get annuity for life time and on death of the Subscriber, annuity will be\\npayable to spouse of the Subscriber (if any) for life time. On death of Spouse, to dependent\\nmother and then to dependent father of the Subscriber. On death of the last annuitant, payment of annuity ceases and 100% of the purchase price will be returned to the surviving children of the Subscriber and in absence of children, the legal heirs of the subscriber as applicable."}],"markDefs":[],"style":"normal"},{"_key":"d26c9d6dcff6","_type":"block","children":[{"_key":"d26c9d6dcff60","_type":"span","marks":[],"text":"Tax implications"}],"markDefs":[],"style":"h3"},{"_key":"4d2964886692","_type":"block","children":[{"_key":"4d29648866920","_type":"span","marks":[],"text":"(Available only for contributions to Tier I accounts)"}],"markDefs":[],"style":"normal"},{"_key":"63bf46787a3a","_type":"block","children":[{"_key":"63bf46787a3a0","_type":"span","marks":[],"text":"Contributions eligible for tax benefit under Sec 80 CCD (1) with in the overall ceiling of ₹ 1.5 lakh under Sec 80C."}],"markDefs":[],"style":"normal"},{"_key":"7ecf0150db2c","_type":"block","children":[{"_key":"7ecf0150db2c0","_type":"span","marks":[],"text":"An additional deduction for investment up to ₹ 50,000 in NPS (Tier I account) is available exclusively to NPS subscribers under subsection 80CCD (1B)."}],"markDefs":[],"style":"normal"},{"_key":"cc97f48cfa22","_type":"block","children":[{"_key":"cc97f48cfa220","_type":"span","marks":["strong"],"text":"Note: This deduction continues to be provided in the new tax regime."}],"markDefs":[],"style":"normal"},{"_key":"65f070639199","_type":"block","children":[{"_key":"65f0706391990","_type":"span","marks":[],"text":"Subscriber can partially withdraw from NPS Tier I account for specified purposes. Amount received from partial withdrawal are tax exempt u/s 10 (12B) of Income Tax Act."}],"markDefs":[],"style":"normal"},{"_key":"d502c59c9279","_type":"block","children":[{"_key":"d502c59c92790","_type":"span","marks":[],"text":"Amount invested in purchase of Annuity, is fully exempt from tax. However, annuity income that you receive in the subsequent years will be subject to income tax."}],"markDefs":[],"style":"normal"},{"_key":"0e99683d06ba","_type":"block","children":[{"_key":"0e99683d06ba0","_type":"span","marks":[],"text":"Up to 60% of the total corpus withdrawn in lump sum at the time of exit is exempt from tax."}],"markDefs":[],"style":"normal"},{"_key":"cb2666dd7545","_type":"block","children":[{"_key":"cb2666dd75450","_type":"span","marks":["strong"],"text":"Note: These provisions on withdrawal of funds from the scheme continue to be applicable in the new tax regime."}],"markDefs":[],"style":"normal"},{"_key":"bf06a7c11dac","_type":"block","children":[{"_key":"bf06a7c11dac0","_type":"span","marks":[],"text":"Example"}],"markDefs":[],"style":"h4"},{"_key":"eb3c5b64b784","_type":"block","children":[{"_key":"eb3c5b64b7840","_type":"span","marks":[],"text":"If total corpus at exit is 10 lakhs, then 60% of the total corpus i.e. 6 lakhs, you can withdraw without paying any tax. So, if you use 60% of NPS corpus for lump sum withdrawal and remaining 40% for annuity purchase, you do not pay any tax at that time. Only the annuity income that you receive in the subsequent years will be subject to income tax as per the applicable tax slab."}],"markDefs":[],"style":"normal"},{"_key":"58264618fb4e","_type":"block","children":[{"_key":"58264618fb4e0","_type":"span","marks":[],"text":"Liquidity"}],"markDefs":[],"style":"h3"},{"_key":"7db7b34ffd16","_type":"block","children":[{"_key":"7db7b34ffd160","_type":"span","marks":[],"text":"Subscribers can withdraw certain parts of the investment starting 3 years after joining. No penalty on withdrawal."}],"markDefs":[],"style":"normal"},{"_key":"d9af50ab5547","_type":"block","children":[{"_key":"d9af50ab55470","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"a2329598de4e","_type":"block","children":[{"_key":"a2329598de4e0","_type":"span","marks":[],"text":"Should be subscribed by everyone who is eligible."}],"markDefs":[],"style":"normal"},{"_key":"3f89fc04699f","_type":"block","children":[{"_key":"3f89fc04699f0","_type":"span","marks":[],"text":"Investment options as well as Annuity options made available under the NPS scheme, are also available through the same, and other, private players without going through the scheme."}],"markDefs":[],"style":"normal"},{"_key":"751e230ab3bf","_type":"block","children":[{"_key":"751e230ab3bf0","_type":"span","marks":[],"text":"The benefit of NPS over private players on the investing side is that the expense ratio of these funds is lower than privately managed (outside the NPS) funds."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-10T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-20-national-pension-system-nps"},"title":"National Pension System (NPS)"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-3', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-3","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"1e946886ef76","_type":"block","children":[{"_key":"1e946886ef760","_type":"span","marks":[],"text":"Compound interest is an exponential growth phenomenon"}],"markDefs":[],"style":"h2"},{"_key":"7d3483798d79","_type":"block","children":[{"_key":"7d3483798d790","_type":"span","marks":[],"text":"We are generally used to thinking in linear terms and not very good at understanding the accumulated effect of small differences in growth rates over long periods of time. The tables below give us the impact of different rates of return over different time horizons, and the difference between simple and compound interest."}],"markDefs":[],"style":"normal"},{"_key":"fe9619aff19c","_type":"block","children":[{"_key":"fe9619aff19c0","_type":"span","marks":[],"text":"Simple interest effect over different periods of time"}],"markDefs":[],"style":"h3"},{"_key":"ad70e5f5c4c1","_type":"table","rows":[{"_key":"a3z9g0c","_type":"tableRow","cells":["Interest rate \\\\ Years 🡪","1","2","3","5","10","25","50","100"]},{"_key":"klfjuyz","_type":"tableRow","cells":["1%","1.01","1.02","1.03","1.05","1.10","1.25","1.50","2.00"]},{"_key":"ry69yvg","_type":"tableRow","cells":["5%","1.05","1.10","1.15","1.25","1.50","2.25","3.50","6.00"]},{"_key":"r79nqot","_type":"tableRow","cells":["10%","1.10","1.20","1.30","1.50","2.00","3.50","6.00","11.00"]},{"_key":"9apiphg","_type":"tableRow","cells":["25%","1.25","1.50","1.75","2.25","3.50","7.25","13.50","26.00"]}]},{"_key":"d2082a50ff89","_type":"block","children":[{"_key":"d2082a50ff890","_type":"span","marks":[],"text":"At a return of 1% simple interest p.a., an amount becomes 1.5 times the initial amount in 50 years and twice the original amount in 100 years.\\nAt a 5% simple interest return, an amount becomes 3.5 times the initial amount in 50 years and six times the original amount in 100 years."}],"markDefs":[],"style":"normal"},{"_key":"8238a0459ac9","_type":"block","children":[{"_key":"8238a0459ac90","_type":"span","marks":[],"text":"Compound interest effect over different periods of time"}],"markDefs":[],"style":"h3"},{"_key":"a1b4b50f7f57","_type":"table","rows":[{"_key":"72vhhun","_type":"tableRow","cells":["Interest rate \\\\ Years 🡪","1","2","3","5","10","25","50","100"]},{"_key":"emygvyg","_type":"tableRow","cells":["1%","1.01","1.02","1.03","1.05","1.10","1.28","1.64","2.70"]},{"_key":"wtobfff","_type":"tableRow","cells":["5%","1.05","1.10","1.16","1.28","1.63","3.39","11.5","131.5"]},{"_key":"sqs20yg","_type":"tableRow","cells":["10%","1.10","1.21","1.33","1.61","2.59","10.83","117","13,781"]},{"_key":"dp3nu16","_type":"tableRow","cells":["25%","1.25","1.56","1.95","3.05","9.31","264.70","70,065","4,90,90,93,465"]}]},{"_key":"4af3f59d7f6e","_type":"block","children":[{"_key":"4af3f59d7f6e0","_type":"span","marks":[],"text":"At a return of 1% compound interest p.a., an amount becomes 1.64 times the initial amount in 50 years and 2.7 times the original amount in 100 years.\\nAt a 5% compound interest return, an amount becomes 11.5 times the initial amount in 50 years and 131.5 times the original amount in 100 years."}],"markDefs":[],"style":"normal"},{"_key":"ea37985be0ce","_type":"block","children":[{"_key":"ea37985be0ce0","_type":"span","marks":[],"text":"What do we see?"}],"markDefs":[],"style":"normal"},{"_key":"a2ee9502af60","_type":"block","children":[{"_key":"a2ee9502af600","_type":"span","marks":[],"text":"Money invested on compounding terms amounts to a whole lot more than the money invested on simple interest."}],"markDefs":[],"style":"normal"},{"_key":"f276338d9c12","_type":"block","children":[{"_key":"f276338d9c120","_type":"span","marks":[],"text":"Why does this happen when the rate is the same?"}],"markDefs":[],"style":"normal"},{"_key":"3ff7ce3640f4","_type":"block","children":[{"_key":"3ff7ce3640f40","_type":"span","marks":[],"text":"The primary reason is that simple interest, once earned, does not get reinvested. It is probably drawn out for expenditure. When invested on compounding basis, the earnings get ploughed back into the investment and generate returns in addition to the returns generated by the principal. In a few years, the interest starts becoming bigger than the principal and generating a whole lot more money."}],"markDefs":[],"style":"normal"},{"_key":"6b4157bec673","_type":"block","children":[{"_key":"6b4157bec6730","_type":"span","marks":[],"text":"There are two variables on which this works:\\n– The duration; the longer the investment period the greater the benefit\\n– The rate of return; the higher the rate the greater the benefit"}],"markDefs":[],"style":"normal"},{"_key":"5f917ba6ee15","_type":"block","children":[{"_key":"5f917ba6ee150","_type":"span","marks":[],"text":"In our example, at the rate of 1% per annum, the amount is almost the same after 10 years, a little higher at the end of 100 years.\\nWhen invested at 10% p.a., the difference starts becoming visible earlier. After 5 years, ₹ 1 amounts to ₹ 1.50 using simple interest and ₹ 1.61 using compound interest. From here onwards, compound interest keeps pulling away. After 50 years, simple interest yields ₹ 6 while compound interest yields ₹ 11.74."}],"markDefs":[],"style":"normal"},{"_key":"c92ff915cdc2","_type":"block","children":[{"_key":"c92ff915cdc20","_type":"span","marks":[],"text":"As the rate and amount increase, the difference expands."}],"markDefs":[],"style":"normal"},{"_key":"b04b65f47d57","_type":"block","children":[{"_key":"b04b65f47d570","_type":"span","marks":[],"text":"Recommendation"}],"markDefs":[],"style":"h2"},{"_key":"a1bdb65cf3f8","_type":"block","children":[{"_key":"a1bdb65cf3f80","_type":"span","marks":[],"text":"Start investing early and give your money a chance to grow. Allow the earnings, as they accrue, to generate returns as well."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-03-24T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-03-compound-interest-and-exponential-growth"},"title":"Compounding can deliver exponential growth"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-22', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-22","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"54c0f37da1f0","_type":"block","children":[{"_key":"54c0f37da1f00","_type":"span","marks":[],"text":"The government offers a number of investment options for the individual investor. On account of a lack of awareness about these schemes (many money managers may not suggest these schemes as they do not receive a commission) as well as hesitation in dealing with a machinery that is considered bureaucratic and slow, many eligible people do not invest in them."}],"markDefs":[],"style":"normal"},{"_key":"b6aa3347b75a","_type":"block","children":[{"_key":"b6aa3347b75a0","_type":"span","marks":[],"text":"The loss is their own as these schemes offer great returns, better than fixed income schemes like fixed deposits and bonds, the highest level of security, and tax benefits as well. With online access to account opening and closing gradually expanding, it is also becoming easier to invest in these schemes."}],"markDefs":[],"style":"normal"},{"_key":"bf3d289045ce","_type":"block","children":[{"_key":"bf3d289045ce0","_type":"span","marks":[],"text":"A short list of schemes that you should consider, along with their key features, as currently applicable, are shared below. We hope this will encourage more of you to consider investing in government schemes. The returns, tax implications and features are subject to change. As always, please read the scheme documents to ensure that they are beneficial for your situation."}],"markDefs":[],"style":"normal"},{"_key":"f69a04550044","_type":"block","children":[{"_key":"f69a045500440","_type":"span","marks":["strong"],"text":"Table: Government savings schemes for individuals"}],"markDefs":[],"style":"normal"},{"_key":"c59ff897008e","_type":"table","rows":[{"_key":"h6q1cr9","_type":"tableRow","cells":["Scheme","Target Group","Returns (Indicative)","Tenure"]},{"_key":"h6abugr","_type":"tableRow","cells":["Public Provident Fund (PPF)","All individuals. Account can be opened till the age of 75.","7.1% (compounded yearly)","15 years"]},{"_key":"81vbyfm","_type":"tableRow","cells":["National Savings Certificate (NSC)","All individuals","7.7%","5 years"]},{"_key":"zvj7f2b","_type":"tableRow","cells":["Sukanya Samriddhi Yojana (SSY)","Girl child (age <10)","8.2%","Till age 21 or marriage at 18"]},{"_key":"dfbask2","_type":"tableRow","cells":["Senior Citizens Savings Scheme (SCSS)","Age 60+ (or 55+ retired)","8.2% (paid out quarterly)","5 years (extendable)"]},{"_key":"da8yq6l","_type":"tableRow","cells":["Kisan Vikas Patra (KVP)","All individuals","7.5% (principal doubles on maturity)","115 months"]},{"_key":"wudjskw","_type":"tableRow","cells":["National Pension System (NPS)","All Indian citizens (18–70)","Market-linked","Purchase annuity on attaining the age of 60, or delay it."]},{"_key":"no7aihc","_type":"tableRow","cells":["RBI Floating Rate Savings Bonds","All individuals","~8.05% (Jul–Dec 2025)","7 years"]}]},{"_key":"b0f4014c7d0b","_type":"block","children":[{"_key":"b0f4014c7d0b0","_type":"span","marks":[],"text":"The "},{"_key":"b0f4014c7d0b1","_type":"span","marks":["8357d23f77e7"],"text":"National Savings Institute"},{"_key":"b0f4014c7d0b2","_type":"span","marks":[],"text":" publishes the applicable rates for different schemes on its website.\\nAn overview of the schemes is also available "},{"_key":"b0f4014c7d0b3","_type":"span","marks":["e5780424937a"],"text":"here"},{"_key":"b0f4014c7d0b4","_type":"span","marks":[],"text":"."}],"markDefs":[{"_key":"8357d23f77e7","_type":"link","href":"https://www.nsiindia.gov.in/(S(gnfsjb45ru0l0pra3kz4vt45))/InternalPage.aspx?Id_Pk=132"},{"_key":"e5780424937a","_type":"link","href":"https://www.nsiindia.gov.in/(S(zlus4x55qtazutywewljk0fl))/InternalPage.aspx?Id_Pk=188"}],"style":"normal"},{"_key":"8f5d837dbaa9","_type":"block","children":[{"_key":"8f5d837dbaa90","_type":"span","marks":[],"text":"With this list, you can pick the one with the highest rates subject to your liquidity preferences and taxability, till you get to the maximum and then move to the next option."}],"markDefs":[],"style":"normal"},{"_key":"58b53dccd7c6","_type":"block","children":[{"_key":"58b53dccd7c60","_type":"span","marks":[],"text":"Details of the "},{"_key":"58b53dccd7c61","_type":"span","marks":["6d5019fb1829"],"text":"National Pension System (NPS)"},{"_key":"58b53dccd7c62","_type":"span","marks":[],"text":", "},{"_key":"58b53dccd7c63","_type":"span","marks":["d341ea2e7851"],"text":"Public Provident Fund (PPF)"},{"_key":"58b53dccd7c64","_type":"span","marks":[],"text":", and "},{"_key":"58b53dccd7c65","_type":"span","marks":["5bf66152e2fc"],"text":"Senior Citizens’ Saving Scheme (SCSS)"},{"_key":"58b53dccd7c66","_type":"span","marks":[],"text":" can be accessed on this website by clicking on the names of these schemes here."}],"markDefs":[{"_key":"6d5019fb1829","_type":"link","href":"/2023/08/20/national-pension-system-nps/"},{"_key":"d341ea2e7851","_type":"link","href":"/2023/10/01/public-provident-fund/"},{"_key":"5bf66152e2fc","_type":"link","href":"/2023/09/01/senior-citizen-saving-scheme/"}],"style":"normal"},{"_key":"0cdb2656a07f","_type":"block","children":[{"_key":"0cdb2656a07f0","_type":"span","marks":[],"text":"Things to note"}],"markDefs":[],"style":"h2"},{"_key":"a3e9702cedf7","_type":"block","children":[{"_key":"a3e9702cedf70","_type":"span","marks":[],"text":"While it is recommended that you go through the scheme details to ensure it suits your requirements, the following are a quick reckoner which apply to most:"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"3937e87303b0","_type":"block","children":[{"_key":"3937e87303b00","_type":"span","marks":[],"text":"Extremely low or negligible risk as offered by the government of India"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"b484016cbb23","_type":"block","children":[{"_key":"b484016cbb230","_type":"span","marks":[],"text":"Available through Post Offices, public sector banks and designated private banks"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1e786956692c","_type":"block","children":[{"_key":"1e786956692c0","_type":"span","marks":[],"text":"Age and other restrictions may apply to account opening as well as to withdrawal and closure"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"13265b1fbb9e","_type":"block","children":[{"_key":"13265b1fbb9e0","_type":"span","marks":[],"text":"Minimum and maximum annual investment amounts are applicable to most"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"60ec590a6778","_type":"block","children":[{"_key":"60ec590a67780","_type":"span","marks":[],"text":"Check for tax benefits available on the amount invested and the interest earned, especially under the old income tax system"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5f6172f8ef9f","_type":"block","children":[{"_key":"5f6172f8ef9f0","_type":"span","marks":[],"text":"Interest rates are subject to change on a quarterly or annual basis"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}],"publishedAt":"2026-04-13T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-23-government-savings-schemes"},"title":"Government Savings Schemes"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-15', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-15","_rev":"VvoTrv03okwDAu5fbFlP0Y","_type":"post","_updatedAt":"2026-07-15T03:33:04Z","body":[{"_key":"b7ade1599c5d","_type":"block","children":[{"_key":"b7ade1599c5d0","_type":"span","marks":[],"text":"Putting money to work is a task."}],"markDefs":[],"style":"normal"},{"_key":"8bea83fa4029","_type":"block","children":[{"_key":"8bea83fa40290","_type":"span","marks":[],"text":"Just like you need to make choices between various investment options available, so do the people and institutions you entrust your money to. They have to put the money to work in order that they are able to generate a return from it and share it with you. If they just sit on the money, it will be a loss-making proposition for them."}],"markDefs":[],"style":"normal"},{"_key":"f93f16697de9","_type":"block","children":[{"_key":"f93f16697de90","_type":"span","marks":[],"text":"Putting money to work involves cost"}],"markDefs":[],"style":"h2"},{"_key":"385026f5d5fc","_type":"block","children":[{"_key":"385026f5d5fc0","_type":"span","marks":[],"text":"When you deposit money with a bank, they need to lend it out to companies and individuals who will be charged interest which becomes their return, a part of which gets shared with you based on agreed terms. The cost of this effort is factored into the interest rate promised on the deposit."}],"markDefs":[],"style":"normal"},{"_key":"82d21ad67d42","_type":"block","children":[{"_key":"82d21ad67d420","_type":"span","marks":[],"text":"When you deposit money with a fund, they need to research markets, move money around and make choices in line with the objective of the fund. Many funds charge a management fee to their investors on an annual basis in order to pay for these costs."}],"markDefs":[],"style":"normal"},{"_key":"c009b8e54d43","_type":"block","children":[{"_key":"c009b8e54d430","_type":"span","marks":[],"text":"Financial advisors also cost money."}],"markDefs":[],"style":"normal"},{"_key":"f4720060d22f","_type":"block","children":[{"_key":"f4720060d22f0","_type":"span","marks":[],"text":"Most people have a long investment horizon, from the time they start working, till the time they retire from active work. Annual and other fees over a long horizon become substantial."}],"markDefs":[],"style":"normal"},{"_key":"c57c640baae3","_type":"block","children":[{"_key":"c57c640baae30","_type":"span","marks":[],"text":"Hence, keeping the investment cost low can itself deliver a huge benefit over several decades."}],"markDefs":[],"style":"normal"},{"_key":"47289bef7113","_type":"block","children":[{"_key":"47289bef71130","_type":"span","marks":[],"text":"The impact of lower cost investing"}],"markDefs":[],"style":"h2"},{"_key":"94cb9266e311","_type":"block","children":[{"_key":"94cb9266e3110","_type":"span","marks":[],"text":"Let us take an example of two funds, A and B, that deliver the same return year after year. The management fee charged by one is substantially lower than the other. How does it impact an investor over a period of time?"}],"markDefs":[],"style":"normal"},{"_key":"fb3af4ce16cf","_type":"block","children":[{"_key":"fb3af4ce16cf0","_type":"span","marks":["strong"],"text":"Table: Comparative earnings difference between funds with different costs"}],"markDefs":[],"style":"normal"},{"_key":"50ac94dd31b8","_type":"table","rows":[{"_key":"nyllyxi","_type":"tableRow","cells":["","Fund A","Fund B"]},{"_key":"32nne0b","_type":"tableRow","cells":["Gross return p.a.","10%","10%"]},{"_key":"u7dcx8x","_type":"tableRow","cells":["Management fee p.a.","1.25%","0.25%"]},{"_key":"nr775k5","_type":"tableRow","cells":["Net return to investor p.a.","8.75%","9.75%"]},{"_key":"vuexo3e","_type":"tableRow","cells":["In 10 years, an initial investment of ₹ 10,000 will amount to","₹ 23,136","₹ 25,354"]},{"_key":"a05juwf","_type":"tableRow","cells":["Investor earnings over 10 years","₹ 13,136","₹ 15,354"]}]},{"_key":"902837ed8083","_type":"block","children":[{"_key":"902837ed80830","_type":"span","marks":[],"text":"Here is another illustration over a longer period of 50 years which demonstrates the additional value created by a fund which costs 1% lower than another similar fund. The initial investment is ₹ 10,000 and the cost difference between the two funds is 1%."}],"markDefs":[],"style":"normal"},{"_key":"9941cf2a8141","_type":"block","children":[{"_key":"9941cf2a81410","_type":"span","marks":["strong"],"text":"Table: Incremental value created over time"}],"markDefs":[],"style":"normal"},{"_key":"95ec59c3df84","_type":"table","rows":[{"_key":"y7eb8i8","_type":"tableRow","cells":["Initial Investment","₹ 10,000"]},{"_key":"vcgu736","_type":"tableRow","cells":["Investment Period in Years","50"]},{"_key":"mnt5lox","_type":"tableRow","cells":["Investment Return Direct Fund","10.00%"]},{"_key":"fbyftpp","_type":"tableRow","cells":["Additional Fees of Regular Fund","1.00%"]},{"_key":"xvl7k02","_type":"tableRow","cells":["Investment Return Regular Fund","9.00%"]},{"_key":"ks9rs3p","_type":"tableRow","cells":["Final Value Direct Fund","₹ 11,73,909"]},{"_key":"eikyvke","_type":"tableRow","cells":["Final Value Regular Fund","₹ 7,43,575"]},{"_key":"r1hc08q","_type":"tableRow","cells":["Additional Value","₹ 4,30,333"]}]},{"_key":"7c834f7a6c8f","_type":"block","children":[{"_key":"7c834f7a6c8f0","_type":"span","marks":[],"text":"What do we see?"}],"markDefs":[],"style":"normal"},{"_key":"b47d29d288e8","_type":"block","children":[{"_key":"b47d29d288e80","_type":"span","marks":[],"text":"Taking the higher-cost fund (Regular Fund) as the base case, the lower-cost fund (Direct Fund) has delivered 57% more in terms of gross earnings (₹ 4,30,333 as a percentage of ₹ 7,43,575) to the investor over a 50-year period."}],"markDefs":[],"style":"normal"},{"_key":"08ce7daf5633","_type":"block","children":[{"_key":"08ce7daf56330","_type":"span","marks":[],"text":"The following table illustrates how the additional value changes over time."}],"markDefs":[],"style":"normal"},{"_key":"b9fce7e6e7cb","_type":"block","children":[{"_key":"b9fce7e6e7cb0","_type":"span","marks":["strong"],"text":"Table: Additional value created over different time horizons"}],"markDefs":[],"style":"normal"},{"_key":"f49e9d01f545","_type":"table","rows":[{"_key":"151s51r","_type":"tableRow","cells":["Investment Period in Years","Additional Value (₹)"]},{"_key":"5eti5qj","_type":"tableRow","cells":["1","100"]},{"_key":"g5yyyfl","_type":"tableRow","cells":["2","219"]},{"_key":"tss3mb0","_type":"tableRow","cells":["3","360"]},{"_key":"8o3lj00","_type":"tableRow","cells":["5","719"]},{"_key":"aif29uv","_type":"tableRow","cells":["10","2,264"]},{"_key":"dfyt9cx","_type":"tableRow","cells":["15","5,348"]},{"_key":"io3vybh","_type":"tableRow","cells":["20","11,231"]},{"_key":"jyidc1o","_type":"tableRow","cells":["25","22,116"]},{"_key":"cq8pw2q","_type":"tableRow","cells":["30","41,817"]},{"_key":"eg3fdke","_type":"tableRow","cells":["40","1,38,498"]},{"_key":"oh42v1w","_type":"tableRow","cells":["50","4,30,333"]}]},{"_key":"75242c12c1f8","_type":"block","children":[{"_key":"75242c12c1f80","_type":"span","marks":[],"text":"How to do low-cost investing"}],"markDefs":[],"style":"h2"},{"_key":"6b2efeaab021","_type":"block","children":[{"_key":"6b2efeaab0210","_type":"span","marks":[],"text":"Here are some strategies for low-cost investing:"}],"markDefs":[],"style":"normal"},{"_key":"4359235523be","_type":"block","children":[{"_key":"4359235523be0","_type":"span","marks":[],"text":"Choose low-cost index funds"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"535215c64242","_type":"block","children":[{"_key":"535215c642420","_type":"span","marks":[],"text":"Choose inactive over active funds"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"791b83b31dae","_type":"block","children":[{"_key":"791b83b31dae0","_type":"span","marks":[],"text":"Choose Direct over Regular funds"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1b0ba1f0e671","_type":"block","children":[{"_key":"1b0ba1f0e6710","_type":"span","marks":[],"text":"Choose funds with a large corpus so that the management cost is more widely shared and each investor’s share is low"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"52c023380fcb","_type":"block","children":[{"_key":"52c023380fcb0","_type":"span","marks":[],"text":"Avoid frequent trading – each time you trade a transaction cost is incurred"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"bef75fd9d95e","_type":"block","children":[{"_key":"bef75fd9d95e0","_type":"span","marks":[],"text":"Choose funds with a history of low management fees"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"e7b79878342c","_type":"block","children":[{"_key":"e7b79878342c0","_type":"span","marks":[],"text":"If you trade directly, use discount brokerages, which typically operate online"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a8b1574bc9ff","_type":"block","children":[{"_key":"a8b1574bc9ff0","_type":"span","marks":[],"text":"Stay away from high-cost, structured or exotic products"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f0d740eb1f7c","_type":"block","children":[{"_key":"f0d740eb1f7c0","_type":"span","marks":[],"text":"Maximize post-tax returns through leveraging tax-saving instruments"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1501bcf2e663","_type":"block","children":[{"_key":"1501bcf2e6630","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"24a041af1916","_type":"block","children":[{"_key":"24a041af19160","_type":"span","marks":[],"text":"The objective is not to say that one should ignore high-cost investments even if they are delivering great returns. The objective is to sensitize investors about the material impact on returns that the cost passed on to investors by a fund can have. Hence, it should be part of the variable-set to be evaluated before choosing a fund."}],"markDefs":[],"style":"normal"}],"publishedAt":"2026-04-06T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-16-keep-the-cost-of-investing-low"},"title":"Keep the cost of investing low"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-26', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-26","_rev":"8VyNrOEo8uWkcWBKVY22oB","_system":{"base":{"id":"article-26","rev":"VvoTrv03okwDAu5fbFlP0Y"}},"_type":"post","_updatedAt":"2026-07-17T15:07:56Z","body":[{"_key":"3563e33469b6","_type":"block","children":[{"_key":"3563e33469b60","_type":"span","marks":[],"text":"It is a type of mutual fund scheme primarily investing in equity and equity-related instruments, and it offers tax benefits under Section 80C of the Income Tax Act, 1961."}],"markDefs":[],"style":"normal"},{"_key":"c609765e92b7","_type":"block","children":[{"_key":"c609765e92b70","_type":"span","marks":[],"text":"Features"}],"markDefs":[],"style":"h2"},{"_key":"bd429298e53f","_type":"block","children":[{"_key":"bd429298e53f0","_type":"span","marks":[],"text":"A minimum of 80% of the total investible corpus is invested in equity and equity-related instruments"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"792e1f93229c","_type":"block","children":[{"_key":"792e1f93229c0","_type":"span","marks":[],"text":"The fund invested in equity in a diversified manner – across different market capitalization, themes and sectors."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f2103c60cefa","_type":"block","children":[{"_key":"f2103c60cefa0","_type":"span","marks":[],"text":"There is no maximum tenure of investment. However, there is a lock-in period of 3 years."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a64adf6d57e0","_type":"block","children":[{"_key":"a64adf6d57e00","_type":"span","marks":[],"text":"Tax exemption on the invested amount available under section 80C upto ₹ 1.5 lakh."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"a68d26caeb00","_type":"block","children":[{"_key":"a68d26caeb000","_type":"span","marks":[],"text":"Income is treated as Long Term Capital Gain and taxed as per the prevalent tax rules. These gains are tax-free up to ₹ 1 lakh per year, and any earnings beyond this amount are subject to a 10% long-term capital gains tax."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"66652a2147f4","_type":"block","children":[{"_key":"66652a2147f40","_type":"span","marks":[],"text":"It allows the investor to start investing as low as ₹ 500."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5cfc8d907df5","_type":"block","children":[{"_key":"5cfc8d907df50","_type":"span","marks":[],"text":"It allows the investor to invest in lumpsum amount or in the form of SIPs."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"706dde358824","_type":"block","children":[{"_key":"706dde3588240","_type":"span","marks":[],"text":"Return and Risk"}],"markDefs":[],"style":"h2"},{"_key":"ce0bc3bf6570","_type":"block","children":[{"_key":"ce0bc3bf65700","_type":"span","marks":[],"text":"ELSS funds carry higher risk compared to traditional tax-saving options like PPF and NSC due to their equity exposure. However, they also offer the potential for higher returns over the long-term, aligning with the higher risk-reward profile of equities."}],"markDefs":[],"style":"normal"},{"_key":"54bca5f5e6b8","_type":"block","children":[{"_key":"54bca5f5e6b80","_type":"span","marks":[],"text":"The strategy of diversification across companies and sectors helps in mitigating the risk to some extent. However, the inherent risk present in equities as an investment class continues."}],"markDefs":[],"style":"normal"},{"_key":"d0fd50ba4c51","_type":"block","children":[{"_key":"d0fd50ba4c510","_type":"span","marks":[],"text":"ELSS vs NPS"}],"markDefs":[],"style":"h2"},{"_key":"172d0d4d4594","_type":"table","rows":[{"_key":"1z5g4q6","_type":"tableRow","cells":["","ELSS","NPS"]},{"_key":"rqlxtu0","_type":"tableRow","cells":["Nature of investment","A type of mutual fund that primarily invests in equity and equity-related instruments. It offers the potential for high returns but also carries higher market risk due to equity exposure.","A government-sponsored pension scheme that offers a mix of equity, corporate bonds, government securities, and alternative assets. It is designed for retirement planning and offers a diversified portfolio with varying risk profiles based on the investment option"]},{"_key":"k86l9c9","_type":"tableRow","cells":["Tax implications","Investments qualify for tax deductions under Section 80C of the Income Tax Act, up to a maximum of ₹1.5 lakh in a financial year. Additionally, long-term capital gains (LTCG) up to ₹1 lakh from ELSS are tax-exempt.","Contributions to NPS Tier I account qualify for tax deductions under Section 80CCD(1) within the overall limit of ₹1.5 lakh under Section 80C. An additional deduction of up to ₹50,000 is available under Section 80CCD(1B). Withdrawals from the mandatory NPS Tier 1 are not taxed."]},{"_key":"nyj7ys1","_type":"tableRow","cells":["Lock-in period","ELSS has a lock-in period of three years, which is the shortest among tax-saving investment options under Section 80C.","NPS has a longer lock-in period, with investments in the Tier I account being locked in until retirement age, although partial withdrawals are allowed under certain conditions."]},{"_key":"kqmrx0d","_type":"tableRow","cells":["Flexibility","ELSS offers flexibility in terms of investment amount and withdrawal options after the lock-in period. Investors can choose to invest through lump-sum or systematic investment plans (SIPs).","NPS offers flexibility in choosing investment options, allocation among asset classes, and fund managers. Withdrawals from the Tier I account are restricted, with conditions attached. Withdrawals can be freely made from the Tier 2 account."]}]},{"_key":"6399445bd48f","_type":"block","children":[{"_key":"6399445bd48f0","_type":"span","marks":[],"text":"Comparison of returns"}],"markDefs":[],"style":"h2"},{"_key":"a0dffa8ffe95","_type":"block","children":[{"_key":"a0dffa8ffe950","_type":"span","marks":[],"text":"ELSS"}],"markDefs":[],"style":"h3"},{"_key":"78ee5cb85d95","_type":"block","children":[{"_key":"78ee5cb85d950","_type":"span","marks":[],"text":"Trailing returns delivered by the 10 largest funds 9(by AUM) as per data tracked by "},{"_key":"78ee5cb85d951","_type":"span","marks":["3b5d667f80ae"],"text":"Moneycontrol.com"},{"_key":"78ee5cb85d952","_type":"span","marks":[],"text":":"}],"markDefs":[{"_key":"3b5d667f80ae","_type":"link","href":"https://www.moneycontrol.com/mutual-funds/"}],"style":"normal"},{"_key":"a8e83b9bede8","_type":"table","rows":[{"_key":"3xp95mo","_type":"tableRow","cells":["Scheme Name","AuM (Cr)","1Y","5Y","10Y"]},{"_key":"0k5erh4","_type":"tableRow","cells":["Axis ELSS Tax Saver Fund - Direct Plan - Growth","36,257.53","5%","18%","13%"]},{"_key":"y44ldef","_type":"tableRow","cells":["SBI ELSS Tax Saver Fund - Direct Plan - Growth","30,616.22","3%","28%","15%"]},{"_key":"syq082n","_type":"tableRow","cells":["Mirae Asset ELSS Tax Saver Fund - Direct Plan - Growth","26,537.48","6%","24%","-"]},{"_key":"vn1bjbu","_type":"tableRow","cells":["DSP ELSS Tax Saver Fund - Direct Plan - Growth","17,427.57","5%","26%","17%"]},{"_key":"yasaamz","_type":"tableRow","cells":["HDFC ELSS Tax saver - Direct Plan – Growth","16,908.00","7%","27%","14%"]},{"_key":"lqd643k","_type":"tableRow","cells":["Aditya Birla Sun Life ELSS Tax Saver Fund - Direct Plan - Growth","15,869.72","4%","16%","12%"]},{"_key":"zoo8k54","_type":"tableRow","cells":["Nippon India ELSS Tax Saver Fund - Direct Plan - Growth","15,623.15","1%","25%","11%"]},{"_key":"wdv09ub","_type":"tableRow","cells":["ICICI Prudential ELSS Tax Saver Fund - Direct Plan - Growth","14,660.64","5%","23%","14%"]},{"_key":"du0y2of","_type":"tableRow","cells":["Quant ELSS Tax Saver Fund - Direct Plan - Growth","11,922.65","-9%","33%","22%"]},{"_key":"f3hotnp","_type":"tableRow","cells":["Canara Robeco ELSS Tax Saver Fund - Direct Plan - Growth","9,102.87","4%","23%","15%"]}]},{"_key":"662bedf99c10","_type":"block","children":[{"_key":"662bedf99c100","_type":"span","marks":[],"text":"NPS"}],"markDefs":[],"style":"h3"},{"_key":"178f2746d3fb","_type":"block","children":[{"_key":"178f2746d3fb0","_type":"span","marks":[],"text":"Trailing returns (% p.a.) delivered by various Pension Fund Managers for the Tier 1 E (Equity) Scheme over a 10-year period ending on 11th July, 2025, as published by the "},{"_key":"178f2746d3fb1","_type":"span","marks":["24b8b8fe202a"],"text":"NPS Trust"},{"_key":"178f2746d3fb2","_type":"span","marks":[],"text":", are shown below:"}],"markDefs":[{"_key":"24b8b8fe202a","_type":"link","href":"https://npstrust.org.in/weekly-snapshot-nps-schemes"}],"style":"normal"},{"_key":"783fc638880e","_type":"table","rows":[{"_key":"fq1wan8","_type":"tableRow","cells":["Pension Fund","AUM(₹ Crs)","1 Year","5 Years","10 Years"]},{"_key":"5fsv8hn","_type":"tableRow","cells":["Aditya Birla Sun Life Pension Fund Management Limited","1,746.66","3.42%","20.03%","NA"]},{"_key":"2vre558","_type":"tableRow","cells":["Axis Pension Fund Management Limited","4,266.92","3.07%","NA","NA"]},{"_key":"wgflp4m","_type":"tableRow","cells":["HDFC Pension Fund Management Ltd.","60,891.46","4.47%","21.32%","13.40%"]},{"_key":"9nn6i46","_type":"tableRow","cells":["ICICI Pru. Pension Fund Mgmt Co. Ltd.","21,908.75","3.46%","22.33%","13.14%"]},{"_key":"zry3i12","_type":"tableRow","cells":["Kotak Mahindra Pension Fund Ltd.","3,209.39","5.50%","21.99%","13.33%"]},{"_key":"2js3w23","_type":"tableRow","cells":["LIC Pension Fund Ltd.","6,960.23","3.71%","21.83%","12.27%"]},{"_key":"x7q50z7","_type":"tableRow","cells":["SBI Pension Funds Pvt. Ltd","23,501.93","-0.36%","19.48%","12.01%"]},{"_key":"99cs82w","_type":"tableRow","cells":["Tata Pension Fund Management Pvt. Ltd.","2,002.39","1.77%","NA","NA"]},{"_key":"hutp77s","_type":"tableRow","cells":["UTI Pension Fund Ltd.","4,727.24","3.10%","22.36%","13.37%"]},{"_key":"1nnjft3","_type":"tableRow","cells":["DSP Pension Fund Managers Private Limited","2,087.90","12.24%","NA","NA"]}]},{"_key":"b86cbd3f6c6c","_type":"block","children":[{"_key":"b86cbd3f6c6c0","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"1ccf307012bc","_type":"block","children":[{"_key":"1ccf307012bc0","_type":"span","marks":[],"text":"The returns delivered by most NPS funds are within a narrow range. ELSS funds, on the other hand, display a greater variance in performance. Thus:"}],"markDefs":[],"style":"normal"},{"_key":"0fd041a1afea","_type":"block","children":[{"_key":"0fd041a1afea0","_type":"span","marks":[],"text":"ELSS funds have the capacity to deliver better gross returns than NPS funds."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"8523256aeca0","_type":"block","children":[{"_key":"8523256aeca00","_type":"span","marks":[],"text":"NPS Tier 1 has tax benefits on withdrawals that are unlimited while gains on ELSS liquidation are tax-exempt only upto ₹ 1 lakh in a year. Thus, ELSS should be the preferred investment for smaller amounts and NPS for larger."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"3d696012ab07","_type":"block","children":[{"_key":"3d696012ab070","_type":"span","marks":[],"text":"Where the investment is being made as a means to achieving the allocation to equity, ELSS should be prioritized over NPS."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}],"publishedAt":"2026-07-19T18:30:00.000Z","slug":{"_type":"slug","current":"2023-10-03-equity-linked-saving-scheme"},"title":"Equity Linked Saving Scheme (ELSS)"}');
