INSERT INTO `sanity_easyWinsPage` (`id`, `data`) VALUES ('easyWinsSingleton', '{"_createdAt":"2026-07-15T06:43:41Z","_id":"easyWinsSingleton","_rev":"8VyNrOEo8uWkcWBKVWpdsF","_system":{"base":{"id":"easyWinsSingleton","rev":"s2wDSUpWBbCAmLaTqQeZBp"}},"_type":"easyWinsPage","_updatedAt":"2026-07-16T16:07:39Z","cards":[{"_key":"1","desc":"Choose a direct MF over a regular MF — save on fees every single year.","title":"Shift to Direct Funds","to":"/2023/08/18/when-investing-in-a-mutual-fund-choose-a-direct-mf-over-a-regular-mf/"},{"_key":"2","desc":"Tax benefits and low-cost investment options for retirement planning.","title":"Participate in NPS","to":"/2023/08/20/national-pension-system-nps/"},{"_key":"3","desc":"Earn better returns on emergency funds than a savings account.","title":"Switch to Liquid Funds","to":"/2023/08/19/why-keeping-money-in-a-liquid-mutual-fund-is-better-for-short-term-needs-than-keeping-it-in-a-savings-account/"},{"_key":"4","desc":"Move from fixed deposits to government small savings schemes.","title":"Leverage Government Schemes","to":"/2023/08/23/government-savings-schemes/"}],"introParagraph1":"We share a few easy things that you can do to improve investment outcomes. With most investment decisions, there is a potential benefit and associated downside. One has to evaluate the benefits against the costs to decide what to do. With many decisions, whether you are better or worse off, depends upon whether equity market returns are better or worse than fixed income returns in the future over your holding horizon.","introParagraph2":"The Easy Wins are different in that these are opportunities for benefits without any significant associated downside. These are actions that you can take where we are very confident that you will be better off for taking these actions, whether markets go up or down.","title":"Easy Wins"}');
