INSERT INTO `sanity_simpleStrategyPage` (`id`, `data`) VALUES ('simpleStrategySingleton', '{"_createdAt":"2026-07-15T06:43:41Z","_id":"simpleStrategySingleton","_rev":"OrjjZZLPs7UERz88SxOt3P","_system":{"base":{"id":"simpleStrategySingleton","rev":"OrjjZZLPs7UERz88SxOpDl"}},"_type":"simpleStrategyPage","_updatedAt":"2026-07-16T16:09:13Z","elements":[{"_key":"1","link":"/2023/08/03/compound-interest-and-exponential-growth/","n":"01","text":"Start saving early if you can, even if the amounts of saving are small."},{"_key":"2","link":"/2023/08/11/index-funds/","n":"02","text":"Investment in stocks – Do not pick individual stocks or securities."},{"_key":"3","link":"/2023/08/05/asset-allocation/","n":"03","text":"Focus on deciding how much to put into equities and how much to put into fixed income assets. This is Asset Allocation and has the biggest impact on your future gains and losses."},{"_key":"4","link":"/2023/08/20/national-pension-system-nps/","n":"04","text":"Use the National Pension Scheme for your long-term investment goals."},{"_key":"5","link":"/2023/08/11/index-funds/","n":"05","text":"Exposure to asset classes – Use Index funds for your equity risk exposure."},{"_key":"6","link":"/2023/08/23/government-savings-schemes/","n":"06","text":"Exposure to asset classes – Use Government Small savings Schemes for your fixed income exposures."},{"_key":"7","link":"/2023/08/18/when-investing-in-a-mutual-fund-choose-a-direct-mf-over-a-regular-mf/","n":"07","text":"Invest in Direct Mutual Funds and avoid Regular Funds."},{"_key":"8","link":"/2023/08/19/why-keeping-money-in-a-liquid-mutual-fund-is-better-for-short-term-needs-than-keeping-it-in-a-savings-account/","n":"08","text":"Keep your savings for emergency needs in a liquid mutual fund instead of a bank savings account."}],"elementsTitle":"Elements of a simple investment strategy","introParagraph1":"Investing can be very complex. However it is possible to create simple investment strategies that can be surprisingly effective.","introParagraph2":"Here we suggest a simple investment strategy that is easy to understand and that is likely to be more effective than most complex investment strategies recommended to individual investors.","title":"A Simple Investment Strategy"}');
INSERT INTO `sanity_post` (`id`, `data`) VALUES ('article-1', '{"_createdAt":"2026-07-11T13:42:19Z","_id":"article-1","_rev":"lI9zik0MAICgRaEKdqRXo1","_system":{"base":{"id":"article-1","rev":"lI9zik0MAICgRaEKdqRVuR"}},"_type":"post","_updatedAt":"2026-08-06T03:45:52Z","body":[{"_key":"bc02e95aef71","_type":"block","children":[{"_key":"bc02e95aef710","_type":"span","marks":[],"text":"Preservation and growth of money, simple as they may sound, are not easy tasks. In the olden days one may have needed to protect money from thieves and robbers. The modern world has its share of thieves and robbers, though most of them will not rid you of your valuables at gunpoint."}],"markDefs":[],"style":"normal"},{"_key":"d9525fb8360e","_type":"block","children":[{"_key":"d9525fb8360e0","_type":"span","marks":[],"text":"Investing is a choice being made by the investor. A choice needs to be made because the future is uncertain. Though we have some idea about how it might turn out, nobody knows for sure. Just because a certain commodity has appreciated over the last 5 years does not mean it will do so for the next 5 years as well. Investment advertisements regularly and mandatorily warn investors that past performance is no guarantee of future returns."}],"markDefs":[],"style":"normal"},{"_key":"070c1f3e0652","_type":"block","children":[{"_key":"070c1f3e06520","_type":"span","marks":[],"text":"Most investment advisors will have you fill out a form based on which they evaluate your ‘risk profile,’ or ability to take investment risks, and recommend options accordingly."}],"markDefs":[],"style":"normal"},{"_key":"f99c60eab7b1","_type":"block","children":[{"_key":"f99c60eab7b10","_type":"span","marks":[],"text":"The risk-reward trade-off is well known. The greater the projected return, the greater the risk. Investors with a low ability to handle risk are recommended safe options like government bonds and bank deposits."}],"markDefs":[],"style":"normal"},{"_key":"a02c82f508b5","_type":"block","children":[{"_key":"a02c82f508b50","_type":"span","marks":[],"text":"What you are not told is that there is risk in every investment."}],"markDefs":[],"style":"normal"},{"_key":"29376a80af43","_type":"block","children":[{"_key":"29376a80af430","_type":"span","marks":[],"text":"Equity Investing"}],"markDefs":[],"style":"h2"},{"_key":"400b6d9e4ed9","_type":"block","children":[{"_key":"400b6d9e4ed90","_type":"span","marks":[],"text":"Equity is designed to bear risk in bad times."}],"markDefs":[],"style":"normal"},{"_key":"f4f3c7eca727","_type":"block","children":[{"_key":"f4f3c7eca7270","_type":"span","marks":[],"text":"When you invest in equity you take the risk that the business will be unsuccessful and that you will lose money. The only reason that people invest in equity is because they expect that on average the business will be successful and that they will make money as compensation for bearing this risk. Historically equity markets have delivered high returns. It is reasonable to expect that in the future too, one should expect to get higher returns for bearing equity risk. However, when one invests in equity, one is taking risk while hoping to generate higher returns than fixed income investments like government or corporate bonds or bank fixed deposits."}],"markDefs":[],"style":"normal"},{"_key":"b53a4b81dd98","_type":"block","children":[{"_key":"b53a4b81dd980","_type":"span","marks":[],"text":"Fixed Income Investing"}],"markDefs":[],"style":"h2"},{"_key":"32ca467a19bf","_type":"block","children":[{"_key":"32ca467a19bf0","_type":"span","marks":[],"text":"With fixed income instruments, there is a promise to pay you for borrowing money from you. These come with an interest rate and a schedule for payment of principal. The interest rate can be fixed or floating based upon a specified index."}],"markDefs":[],"style":"normal"},{"_key":"a8036745aa5b","_type":"block","children":[{"_key":"a8036745aa5b0","_type":"span","marks":[],"text":"Fixed income investments have credit risk – that the promises of fixed payments made are not kept. There can be a default; the promising entity may go bankrupt. If the counterpart to a fixed income investment is very good, such as the government in its own currency, the credit risk can be very small."}],"markDefs":[],"style":"normal"},{"_key":"c025cce83d45","_type":"block","children":[{"_key":"c025cce83d450","_type":"span","marks":[],"text":"The value of traded fixed-income investments changes as interest rates change and they can go up or down in value as interest rates decrease or increase."}],"markDefs":[],"style":"normal"},{"_key":"7a942af34a01","_type":"block","children":[{"_key":"7a942af34a010","_type":"span","marks":[],"text":"Fixed Income investments are denominated in terms of money and the value of money has fluctuated over time, with a general tendency to decline in value as a result of inflation. The real (inflation adjusted) value of fixed income instruments is therefore exposed to risk. Over time, the decline in real value can be substantial."}],"markDefs":[],"style":"normal"},{"_key":"4c3da321a2e4","_type":"block","children":[{"_key":"4c3da321a2e40","_type":"span","marks":[],"text":"There are inflation-linked instruments, which promise a fixed real or inflation-adjusted return. If the promise comes from a government the credit risk can be minimal. However, there exists the risk that the calculation agent (often a government related entity) does not properly reflect actual inflation as has happened in Argentina. There are controversies about the calculation of inflation in other countries. Even eliminating that risk, taxes are due on nominal returns. Therefore, even if one has a fixed real rate instrument from a government, the after-tax real value will not be fixed and therefore have risk."}],"markDefs":[],"style":"normal"},{"_key":"1a3ae79690fc","_type":"block","children":[{"_key":"1a3ae79690fc0","_type":"span","marks":[],"text":"When economies go through crisis and turmoil, all assets can do very poorly with many assets losing almost all value; Zimbabwe, Venezuela and Lebanon are examples. Recently, Sri Lanka and Pakistan are examples closer to home where there was no place to hide without bearing significant losses in domestic assets. This makes the case for investing abroad, if possible, worth considering. However, changes in the law and taxation can reduce the returns from foreign assets as well in times of crisis."}],"markDefs":[],"style":"normal"},{"_key":"59cea4e92024","_type":"block","children":[{"_key":"59cea4e920240","_type":"span","marks":[],"text":"While real estate and human capital are not included in the investments we are considering, it is worth highlighting some aspects of the value of investing in real estate and human capital."}],"markDefs":[],"style":"normal"},{"_key":"bbf296f14113","_type":"block","children":[{"_key":"bbf296f141130","_type":"span","marks":[],"text":"Real estate"}],"markDefs":[],"style":"h2"},{"_key":"97f29f6a3ea7","_type":"block","children":[{"_key":"97f29f6a3ea70","_type":"span","marks":[],"text":"Real estate has the benefit of going up in value with inflation as well as growth in population and per capita income. Residential housing is the largest expenditure for families. Owning residential real estate hedges one’s future expenditure or liability stream on account of rental payment and therefore reduces the risk of affordability of housing. It therefore has attractive risk-return characteristics over long horizons, particularly when one considers simultaneously one’s assets and liabilities. However, as refugees have experienced, when one is uprooted, one cannot take real estate with you."}],"markDefs":[],"style":"normal"},{"_key":"bbe3cabb4e30","_type":"block","children":[{"_key":"bbe3cabb4e300","_type":"span","marks":[],"text":"Human capital"}],"markDefs":[],"style":"h2"},{"_key":"15e4f437529b","_type":"block","children":[{"_key":"15e4f437529b0","_type":"span","marks":[],"text":"Investing in human capital, particularly for one’s children, has the benefit of always being with them through crisis and turmoil. It is also a real asset and exposed to growth in the economy through growth in population and per capita income. Human capital also has positive lifetime externalities."}],"markDefs":[],"style":"normal"},{"_key":"5da5c330f143","_type":"block","children":[{"_key":"5da5c330f1430","_type":"span","marks":[],"text":"Conclusion"}],"markDefs":[],"style":"h2"},{"_key":"a5ca355bccfd","_type":"block","children":[{"_key":"a5ca355bccfd0","_type":"span","marks":[],"text":"So, what should one do if one wants a low level of risk?"}],"markDefs":[],"style":"normal"},{"_key":"fe83f5a442a6","_type":"block","children":[{"_key":"fe83f5a442a60","_type":"span","marks":[],"text":"Short term government bonds are often described as a risk-free asset. This is pretty accurate if one has a need for the funds over a short horizon. The rate is fixed; there is no exposure to changes in interest rates and the inflation rate over a short horizon can be pretty accurately predicted based upon recent history. The risk in both nominal and real terms is almost nil. However, most people seldom have a very short-term horizon for their investments. For those with a long-term horizon, short-term government bonds can be quite risky in nominal and even more so in real terms, particularly in emerging markets with high and variable levels of inflation. For those with a long investment horizon, typically real outcomes are more important than nominal outcomes. An inflation-linked government bond investment with a maturity matching the investment horizon could be considered low risk to the horizon. The value of this investment will however vary on a daily basis."}],"markDefs":[],"style":"normal"},{"_key":"4afbadc64b45","_type":"block","children":[{"_key":"4afbadc64b450","_type":"span","marks":[],"text":"The investment horizon matters when one considers risk."}],"markDefs":[],"style":"normal"},{"_key":"79324eb2cca7","_type":"block","children":[{"_key":"79324eb2cca70","_type":"span","marks":[],"text":"Equity is a real asset in that revenue and profit can be expected to go up with inflation. One can make the case that over long horizons fixed income investments are not as much lower in risk than equities than they are over shorter horizons. In emerging markets with higher and more variable inflation, the difference between fixed income and equity risk can be lower than is the case with developed markets with lower and more stable inflation rates."}],"markDefs":[],"style":"normal"},{"_key":"be2bf6a6d4d4","_type":"block","children":[{"_key":"be2bf6a6d4d40","_type":"span","marks":[],"text":"Equities have historically delivered higher returns over long horizons."}],"markDefs":[],"style":"normal"},{"_key":"1f7190ac7366","_type":"block","children":[{"_key":"1f7190ac73660","_type":"span","marks":[],"text":"If someone tells you that equity always pays off in the long run, have them take a look at the equity markets that ceased to exist after communist transitions in Russia and China and the equity market experience in Japan."}],"markDefs":[],"style":"normal"},{"_key":"a26d10eba726","_type":"block","children":[{"_key":"a26d10eba7260","_type":"span","marks":[],"text":"Bank deposits carry the risk of bank failure. Deposits in banks are insured only up to ₹ 500,000."}],"markDefs":[],"style":"normal"},{"_key":"71acf3b14762","_type":"block","children":[{"_key":"71acf3b147620","_type":"span","marks":[],"text":"There could be liquidity risk; the inability to cash out when you need the money."}],"markDefs":[],"style":"normal"},{"_key":"a7f7b919693a","_type":"block","children":[{"_key":"a7f7b919693a0","_type":"span","marks":[],"text":"While a government might ensure that instruments like bank deposits and government bonds are honoured, they cannot guarantee the non-depreciation of the currency in case of economic mismanagement."}],"markDefs":[],"style":"normal"}],"publishedAt":"2025-08-30T18:30:00.000Z","slug":{"_type":"slug","current":"2023-08-04-there-is-always-some-risk"},"title":"There is always some risk"}');

